function wlv1AddrParse(address){
  const out={};
  if(!address)return out;
  String(address).split(',').forEach(chunk=>{
    const piece=chunk.trim();
    const idx=piece.indexOf(':');
    if(idx<=0)return;
    const label=piece.slice(0,idx).trim().toUpperCase();
    const value=piece.slice(idx+1).trim();
    if(!label||!value)return;
    const key=({VILL:'VILLAGE',VILLAGE:'VILLAGE',PO:'POST',POST:'POST',PS:'THANA',THANA:'THANA',DIST:'DISTRICT',DISTRICT:'DISTRICT',PIN:'PIN'})[label];
    if(key)out[key]=value;
  });
  return out;
}
