function unsyncedLocalRowsForCloudReset(t,remoteRows){
 // V219 production candidate fix:
 // If staff saves a row before Supabase SDK/background init finishes, the first cloud pull must NOT wipe it.
 // Earlier V217/V218 reset local data from cloud immediately; a new Enquiry saved during that window disappeared
 // from list/search and never reached Supabase. Keep only truly new local rows created after this app boot.
 try{
  let remoteIds=new Set((Array.isArray(remoteRows)?remoteRows:[]).map(r=>r&&r.id).filter(Boolean));
  let bootTime=Number(window.__RK_APP_BOOT_TIME||Date.now());
  return cleanRows(rawLoad(t)).filter(r=>r&&r.id&&!remoteIds.has(r.id)&&rowStamp(r)>=bootTime);
 }catch(e){return []}
}
window["unsyncedLocalRowsForCloudReset"]=unsyncedLocalRowsForCloudReset;
function resetLocalTableFromCloud(t,rows){
 // Supabase is the source of truth, but local rows created in the current boot and not yet pushed are protected.
 try{
  let remote=normalizeTableRows(t,cleanRows(rows||[]));
  let keep=mergeById(unsyncedLocalRowsForCloudReset(t,remote),protectedRows(t));
  let merged=normalizeTableRows(t,mergeById(remote,keep));
  RAM_STORE[t]=merged;
  localStorage.setItem('rk_'+t,JSON.stringify(stripLargePhotos(RAM_STORE[t])));
  if(!keep.length)clearPendingCloud(t); else markPendingCloud(t);
  return true
 }catch(e){return false}
}
window["resetLocalTableFromCloud"]=resetLocalTableFromCloud;
