// LOCAL-FIRST nightly sync: once a day around 2 AM, push anything saved on this
// phone up to the cloud and pull everyone else's latest down. Runs quietly.
function startNightlyCloudSync(){
 if(window.__RK_NIGHTLY_TIMER)return;
 window.__RK_NIGHTLY_TIMER=setInterval(async()=>{
  try{
   if(!sb||!user)return;
   let d=new Date(), dayKey=d.toISOString().slice(0,10);
   if(d.getHours()===2 && window.__RK_LAST_NIGHTLY!==dayKey){
    window.__RK_LAST_NIGHTLY=dayKey;
    /* 🔵🔒 V451 EGRESS-SAFE (19.08.2026, TK-approved):
       Daily 2 AM must NOT full-push all tables. On ordinary nights only rows/tables
       that are actually pending are pushed. Once every 7 days the existing full
       safety sync is intentionally kept, so a missed local pending marker can still
       be recovered without paying the full-database cost every single night. */
    const __weeklySafety=wlv1NeedWeeklyFull();
    await flushPendingCloud(__weeklySafety ? undefined : 'pending');
    await pullCloudAllForVisibility('nightly-2am', true);
   }
  }catch(e){}
 },60000);
}
window["startNightlyCloudSync"]=startNightlyCloudSync;

