 // অফলাইনে তোলা যে ছবির সরাসরি আপলোড আগে ব্যর্থ হয়েছিল, নেট ফিরলে সেগুলো এখন
 // directCloudUpsertRow দিয়ে (ছবি-সহ) পাঠানো হয় — কোনো ছবি হারায় না।
 // ⛔ শুধু ব্যর্থ-হওয়া ছবি-সারি (bounded); সফল হলে directCloudUpsertRow নিজেই তালিকা থেকে মুছে দেয়।
 try{
  let pend=wlv1PhotoPendingGet();
  for(const key of pend){
   let parts=String(key).split('|'), pt=parts[0], pid=parts.slice(1).join('|');
   let rowP=(load(pt)||[]).find(x=>x&&String(x.id)===String(pid));
   if(rowP&&(rowP.photo||rowP.patientPhoto)){ await directCloudUpsertRow(pt,rowP); }
   else { wlv1PhotoPendingDel(pt,pid); }
  }
 }catch(_e){}
