const delSoft=async(t,id)=>{
 if(!isMaster())return toast('Delete only Master Admin');
 let a=load(t),i=a.findIndex(x=>x.id===id);
 if(i<0)return toast('Record not found');
 let rec=a[i];
 let tr={id:wlv1TrashIdFor(t,id),table:t,record:rec,deletedAt:new Date().toISOString(),deletedBy:user.mobile};
 add('trash',tr);
 let okT=false; try{ okT=await directCloudUpsertRow('trash',tr) }catch(e){ okT=false }
 if(!okT)return toast('Trash-এ রাখা গেল না — কিছুই মোছা হয়নি');
 let gone=await wlv1CloudDeleteRow(t,id);
 if(!gone)return toast('Cloud-এ মোছা গেল না — কিছুই মোছা হয়নি');
 a.splice(i,1);save(t,a);
 try{ await wlv1MarkDeletedCloud(t,id) }catch(e){}
 toast('Moved to Trash');dashboard()
};
function toast(s){let el=$('#toast');el.textContent=s;el.style.display='block';setTimeout(()=>el.style.display='none',2600)}
/* V386 — পপ-আপের রঙিন হেডার: অ্যান্ড্রয়েডের `native/PremiumAlert.kt`-এর
   `severityOf()` (লাইন ৫৯-৭৯) ও `iconFor()` (লাইন ৮৪-১১৩) হুবহু নকল।
   ⛔ কোনো পপ-আপের লেখা · বোতাম · কাজ বদলায়নি — শুধু শিরোনামের `<h2>`-তে
      একটা ক্লাস (anSevG/anSevY/anSevR) বসে, যাতে CSS সবুজ/হলুদ/লাল হেডার আঁকে।
   ⛔ `.modalBack`-এর ক্লাস বদলানো হয়নি (নইলে বাইরে চেপে বন্ধ করা ভেঙে যেত)। */
function anSeverityOf(title){
  var t=String(title||''), l=t.toLowerCase();
  if(l.indexOf('request')>=0 || t.indexOf('\u0985\u09a8\u09c1\u09b0\u09cb\u09a7')>=0) return 'Y';
  var R=['delete','delete forever','permanently','reject','remove','final confirmation','restore cloud','sure?'];
  for(var i=0;i<R.length;i++) if(l.indexOf(R[i])>=0) return 'R';
  if(t.indexOf('\u09ae\u09c1\u099b')>=0 || t.indexOf('\u09a7\u09cd\u09ac\u0982\u09b8')>=0) return 'R';
  var Y=['already exists','already in the system','confirm','logout','restore','problem','crash','error','warning','overpay'];
  for(var j=0;j<Y.length;j++) if(l.indexOf(Y[j])>=0) return 'Y';
  if(t.indexOf('\u09ac\u09c7\u09b6\u09bf \u09b9\u09df\u09c7 \u09af\u09be\u099a\u09cd\u099b\u09c7')>=0 || t.indexOf('\u09ac\u09be\u09a4\u09bf\u09b2')>=0) return 'Y';
  if(t.charAt(0)==='\u26a0') return 'Y';
  return 'G';
}
function anDialogIcon(title){
  var t=String(title||''), l=t.toLowerCase(), c=t.charCodeAt(0)||0;
  /* প্রথম অক্ষর ইতিমধ্যেই ইমোজি হলে কিছু যোগ হয় না (PremiumAlert.kt:89-96) */
  if((c>=0xD800&&c<=0xDBFF)||(c>=0x2190&&c<=0x21FF)||(c>=0x2600&&c<=0x27BF)||(c>=0x2B00&&c<=0x2BFF)) return '';
  var M=[['password','\uD83D\uDD11'],['delete','\uD83D\uDDD1\uFE0F'],['restore','\u267B\uFE0F'],['logout','\uD83D\uDEAA'],
         ['photo','\uD83D\uDCF7'],['remark','\uD83D\uDCDD'],['note','\uD83D\uDCDD'],['payment','\uD83D\uDCB0'],['income','\uD83D\uDCB0'],
         ['arrived','\u2705'],['approve','\u2705'],['confirm','\u2705'],['crash','\u26A0\uFE0F'],['error','\u26A0\uFE0F'],['problem','\u26A0\uFE0F'],
         ['branch','\uD83D\uDCCB'],['select','\uD83D\uDCCB'],['call','\uD83D\uDCDE'],['document','\uD83D\uDCC4']];
  if(t.indexOf('\u09ae\u09c1\u099b')>=0) return '\uD83D\uDDD1\uFE0F';
  for(var i=0;i<M.length;i++) if(l.indexOf(M[i][0])>=0) return M[i][1];
  return '\u2139\uFE0F';
}
window["anSeverityOf"]=anSeverityOf;window["anDialogIcon"]=anDialogIcon;
window["toast"]=toast;function modal(html){
      const root=$id('modalRoot'); if(!root)return;
      const hasClose=/closeModal\s*\(|>\s*Close\s*</i.test(String(html||''));
      root.innerHTML=`<div class="modalBack" onclick="if(event.target.className==='modalBack')closeModal()"><div class="modal">${html}${hasClose?'':`<div class="actions"><button class="ghost" onclick="closeModal()">Close</button></div>`}</div></div>`;
      /* 🔴 V436 — পপ-আপের ভিতরের তারিখ-ঘরগুলোতেও একই dd/mm/yyyy ব্যবস্থা */
      try{ wlv1AutoDateBoxes(root); }catch(e){}
      /* শিরোনামে severity-ক্লাস + (দরকার হলে) ইমোজি — অ্যান্ড্রয়েডের নিয়মে */
      try{
        const h=root.querySelector('.modal>h2');
        if(h && !h.classList.contains('anSevG') && !h.classList.contains('anSevY') && !h.classList.contains('anSevR')){
          const raw=h.textContent||'';
          const sv=anSeverityOf(raw);
          h.classList.add('anSev'+sv);
          try{ h.parentNode.classList.add('anSev'+sv); }catch(_e){}
          /* RMP পপ-আপ = অ্যান্ড্রয়েডের `premiumDialogShell` (DoctorVisitActivity.kt:1294)
             — গ্রেডিয়েন্ট নয়, নিরেট #145A32 হেডার ও ১dp #145A32 কিনারা। */
          try{ if(h.classList.contains('anRmp')) h.parentNode.classList.add('anRmp'); }catch(_e){}
          const ic=anDialogIcon(raw);
          if(ic) h.textContent=ic+'  '+raw;
        }
      }catch(e){}
    }
