 let wlv1Ord=(n)=>{n=Number(n||0);if(n<=1)return 'Advance';let m100=n%100,m10=n%10,sfx=(m100>=11&&m100<=13)?'th':(m10===1?'st':m10===2?'nd':m10===3?'rd':'th');return n+sfx+' Payment'};
 let wlv1IsTreat=(z)=>{let t=String(z.payType||'treatment').toLowerCase(),r=String(z.remarks||'').toLowerCase();return !(t==='registration'||t==='visit_fee'||t==='visitfee'||t==='medicine'||t==='bill_edit'||t==='attendance_mark'||t==='chamber_expected'||r.includes('visit fee')||r.includes('registration fee'))};
