/* 🔴🆕🔒 V437 #9 (নিজের অডিটে ধরা) — ফোনে রোগীর পেমেন্ট-পপ-আপে চেম্বারের
   **₹0 "Marked Arrived"** সারিগুলোও দেখা যায় (TK নিজে চেয়েছিলেন —
   `PaymentActivity.kt:356-360`), শুধু **গোনায়** ধরা হয় না। ওয়েবে ওগুলো
   `amount>0` ছাঁকনিতে **আগেই** বাদ পড়ে যেত, তাই পপ-আপে কখনো দেখাত না।
   ⛔ শুধু এই পপ-আপের জন্য — দিনের Collection/মোট কোথাও ₹0 সারি ঢোকে না। */
function collectionRowsWithZero(){ return wlv1CollectionRowsRaw(null, true) }
window["collectionRowsWithZero"]=collectionRowsWithZero;
window["collectionRowsAll"]=collectionRowsAll;
function collectionRows(){ return wlv1CollectionRowsRaw(wlv1RefundedMobiles()) }
function wlv1CollectionRowsRaw(refunded, keepZero){

 var wlv1NotRefunded=function(mob){
  if(!refunded)return true;
  var m=String(mob||'').replace(/\D/g,'').slice(-10);
  return !(m.length===10&&refunded[m]);
 };
  // 🔒 V217 (§B216): Refund row (payType='refund') এখানে বাদ — নইলে
 // positive amount হিসেবে "আজকের Collection"-এ ভুল করে যোগ হয়ে যেত।
 // ⛔ সম্পূর্ণ বিয়োগ-হিসাব (Chamber Board/Collection-এ approved refund
 // সত্যিই কমানো) এই ধাপে করা হয়নি — এখন শুধু ভুল করে যোগ হওয়া বন্ধ,
 // TK-কে আলাদা করে জানানো আছে।
 let pays=scoped(load('payments')).filter(x=>wlv1NotRefunded(x.mobile)&&String(x.payType||'').toLowerCase()!=='refund').map(x=>{let sp=wlv1PaymentSplit(x);return {source:collectionPaymentLabel(x),payLabel:x.payLabel||x.paymentLabel||'',date:x.date,name:x.name||'',mobile:x.mobile||'',branch:x.branch||'',mode:wlv1SplitMode(sp.cash,sp.online),amount:Number(x.amount||0),cashAmount:sp.cash,onlineAmount:sp.online,id:x.patientId||x.id,patientId:x.patientId||'',patientCode:x.patientCode||'',payType:x.payType||'treatment',remarks:x.remarks||'',pidCode:String(x.patientCode||'')||wlv1PidCode(x.mobile),createdAt:x.createdAt||'',receivedBy:x.receivedBy||'',createdBy:x.createdBy||'',dailyEvents:Array.isArray(x.dailyEvents)?x.dailyEvents:[]};});
 pays=wlv1MergeDailyTreatmentRows(pays);
 let meds=scoped(load('products')).filter(x=>x.kind==='medicinePayment'||x.deposit||x.total).filter(x=>wlv1NotRefunded(x.mobile)).map(x=>({source:'Medicine Payment',date:x.date,name:x.customer||x.name||'Walk-in',mobile:x.mobile||'',branch:x.branch||'',mode:payMode(x.mode),amount:Number(x.deposit||0),id:x.id,remarks:x.remarks||'',payType:'medicine'   /* 🔴 V437 #14: ফোনে fallback নেই (MedicinePaymentActivity.kt:441-443) */,pidCode:wlv1PidCode(x.mobile),createdAt:x.createdAt||''}));
 /* 🔴 V437 #9 — `keepZero` দিলে ₹0 সারিও থাকে (শুধু রোগীর নিজের পপ-আপের জন্য);
    ⛔ ডিফল্টে আগের মতোই শুধু ₹0-এর বেশি — কোনো মোট/হিসাব বদলায়নি। */
 return [...pays,...meds].filter(x=>keepZero?true:Number(x.amount||0)>0);
}
window["collectionRows"]=collectionRows;
function overview(){
  let all=collectionRows().filter(x=>x.date===today());
  let cashRows=all.filter(x=>Number(x.cashAmount||0)>0),upiRows=all.filter(x=>Number(x.onlineAmount||0)>0);
  let cash=all.reduce((sum,x)=>sum+Number(x.cashAmount!=null?x.cashAmount:(payMode(x.mode)==='CASH'?x.amount:0)||0),0),upi=all.reduce((sum,x)=>sum+Number(x.onlineAmount!=null?x.onlineAmount:(payMode(x.mode)==='UPI'?x.amount:0)||0),0);
  // 🔒 V217 (§B216, TK-এর নির্দেশে সম্পূর্ণ বিয়োগ-হিসাব): collectionRows()
  // refund row আগেই বাদ দেয় (ভুল-যোগ বন্ধ), কিন্তু আজকের Total Collection-এ
  // approved refund এখন সত্যিই **বিয়োগ**ও হয় — Chamber Board-এর সেই একই নিয়ম।
  try{
    let refundsToday=load('payments').filter(x=>String(x.date||'').slice(0,10)===today()&&wlv1IsApprovedRefund(x));
    refundsToday.forEach(x=>{
      let amt=Number(x.amount||0);
      if(payMode(x.mode)==='UPI') upi-=amt; else cash-=amt;
    });
  }catch(_e){}
  let cashCount=cashRows.length,upiCount=upiRows.length;
  return {cash,on:upi,upi,total:cash+upi,cashCount,onCount:upiCount,upiCount,totalCount:all.length};
}
window["overview"]=overview;
function counts(){let f=scoped(load('followups')),p=scoped(load('patients')),e=scoped(load('enquiries'));return {inq:f.filter(x=>x.stage==='Inquiry'&&!isConvertedOrClosed(x)).length,pat:f.filter(x=>x.stage==='Patient'&&!isConvertedOrClosed(x)).length,tr:f.filter(x=>x.stage==='Treatment'&&!isConvertedOrClosed(x)).length,over:f.filter(x=>x.nextFollow&&x.nextFollow<=today()&&!isConvertedOrClosed(x)).length,q:p.filter(x=>x.queue&&!x.doctorComplete).length,reg:p.length,enq:e.length}}
window["counts"]=counts;
