/* ══════════════════════════════════════════════════════════════════════════
   🔴🔴🔒 V511 (২১.০৮.২০২৬, TK-নির্দেশ ছবিসহ) — স্বয়ংক্রিয় নোটিশে **👁 View**।

   TK-এর কথা: *"এটা একটা নতুন এনকোয়ারি হয়েছে, এখন অ্যাকশন কি হতে পারে? আমার
   হিসাবে তো অ্যাকশন হতে হয় ভিউ... ভিউতে চাপ দিলে রিডাইরেক্ট করবে নাম্বারটা
   যেখানে থাকতে হবে — এনকোয়ারি হলে ফলোআপের ইনকয়ারি সেকশনে, রেজিস্ট্রেশন হলে
   ভিজিট সেকশনে, অ্যাডভান্স হলে কত টাকা এডভান্স করল সেখানে।"*

   ⛔ ফোনের `BriefingAdapter`/`BriefingActivity`-র হুবহু একই নিয়ম।
   ⛔ এই তিন নোটিশে **Reply নেই** (কী রিপ্লাই দেবেন?) — View · Seen · Delete।
   ⛔ হাতে লেখা Briefing ও অনুমোদনের নোটিশ এক অক্ষরও বদলায়নি।
   ══════════════════════════════════════════════════════════════════════════ */
/* নম্বর খোঁজার নিয়ম — ফোনের `MOBILE_PATTERN`-এর হুবহু একই।
   ⚠️ `+917099468221` (গায়ে গায়ে লাগানো) — ফোনে ঠিক এই ধরনটাই আগে ধরা পড়ত না,
      তাই View চিরকাল লুকানো থাকত। এখানে সেই ভুল যাতে না হয়। */
function wlv1NoticeMobile(b){
  try{
    var m=String((b&&b.message)||'').match(/(?:^|[^0-9])(?:\+?91[\-\s]?)?([6-9][0-9]{9})(?![0-9])/);
    return m?m[1]:'';
  }catch(e){ return ''; }
}
window["wlv1NoticeMobile"]=wlv1NoticeMobile;

function wlv1NoticeViewBtn(b){
  if(!isAutoNotice(b))return '';
  var mm=wlv1NoticeMobile(b);
  if(!mm)return '';
  return `<button onclick="wlv1NoticeView('${esc(String(b.id))}')">👁 View</button>`;
}
window["wlv1NoticeViewBtn"]=wlv1NoticeViewBtn;

/* View চাপলে — নোটিশের ধরন অনুযায়ী ঠিক জায়গায়।
   ⛔ ব্রাঞ্চ: নোটিশটা অন্য ব্রাঞ্চের হলে মাস্টারের ছাঁকনি সেই ব্রাঞ্চে বদলে
      দেওয়া হয় (TK-অনুমোদিত, ২১.০৮.২০২৬), আর ছোট করে জানিয়ে দেওয়া হয়।
      স্টাফের ব্রাঞ্চ নিজের — ছোঁয়া হয় না। */
function wlv1NoticeView(id){
  try{
    var b=briefings().find(function(x){return String(x.id)===String(id)});
    if(!b)return toast('Notice not found');
    var mm=wlv1NoticeMobile(b);
    if(!mm)return toast('No mobile number in this notice');
    var t=String(b.title||'').trim().toLowerCase();
    /* ব্রাঞ্চ বদল — শুধু মাস্টার, শুধু দরকার হলে */
    try{
      if(isMaster()){
        var want=String(b.branch||'').trim();
        var now=String(wlv1BranchGet()||'').trim();
        if(want && !/^all$/i.test(want) && !/^all$/i.test(now) &&
           want.toLowerCase()!==now.toLowerCase()){
          wlv1BranchSet(want);
          toast('Branch switched to '+want);
        }
      }
    }catch(e){}
    if(t==='advance received'){ summaryByMobile(mm); return; }
    /* Enquiry / Registration → Follow-up-এ, যে সেকশনে নম্বরটা আছে সেখানেই */
    var d=today();
    __followDateFilter={mode:'',from:'',to:''};
    var stage='Inquiry';
    try{
      ['Inquiry','Patient','Treatment'].some(function(st){
        var hit=followStats(st).rows.some(function(r){return mob(r.mobile)===mob(mm)});
        if(hit){ stage=st; return true; }
        return false;
      });
    }catch(e){}
    window.__RK_PINNED_FOLLOW_MOBILE = mm;
    followup(stage);
  }catch(e){ toast('Could not open') }
}
window["wlv1NoticeView"]=wlv1NoticeView;
