function autoNoticeFresh(b){let d=String(b?.date||'').trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(d))return false;let diff=(new Date(today()+'T00:00:00')-new Date(d+'T00:00:00'))/86400000;return diff>=0&&diff<=AUTO_NOTICE_DAYS}
