/* 🔵 V405 (16.08.2026, TK-অনুমোদিত — Egress): এই ফাংশনটা **দুটো টেবিল থেকে
   ১০০০+১০০০ সারি** নামায় (নোটিশের পুরো লেখা ও সব উত্তর সহ), আর ডাকা হত
   **প্রতিবার হোমে ফেরা ও Briefing পর্দা খোলায় — কোনো বিরতি ছাড়াই**।
   এখন ৫ মিনিটের বিরতি। ⛔ নতুন নোটিশ তবু হারায় না: (ক) নোটিশ পাঠানো/উত্তর/
   "Seen" সবই সঙ্গে সঙ্গে ক্লাউডে যায় ও স্থানীয় তালিকায় বসে, (খ) ৫ মিনিট পরের
   যেকোনো ডাকেই সব নেমে আসে, (গ) জোর করে আনতে `refreshBriefingsFromCloud(true)`।
   ⛔ ব্যর্থ/ফাঁকা ফল কখনো "সময়" হিসেবে ধরা হয় না — তাই আটকে যাবে না। */
let __wlv1BriefAt=0;
async function refreshBriefingsFromCloud(force){
 try{
  if(force!==true&&__wlv1BriefAt&&(Date.now()-__wlv1BriefAt)<300000)return true;
  if(!sb)await initCloudClientOnly();
  if(!sb)return false;
  let out=[];
  /* 🌐💰🔒 V492 (২০.০৮.২০২৬, TK-নির্দেশ — Supabase Egress ৯২%): আগে প্রতি ৫
     মিনিটে **পুরো briefings টেবিল** (সব ঘরসহ) নামত। এখন প্রথমবার একবার পুরোটা,
     তারপর থেকে শুধু `updatedAt` বদলেছে এমন সারিগুলোই।
     ⛔ নিচের merge (id ধরে বসানো) আগে থেকেই ছিল — এক অক্ষরও বদলায়নি, তাই
        delta সারিগুলো হুবহু আগের মতোই জমা হয়।
     ⛔ প্রতি ৬ ঘণ্টায় একবার আবার পুরোটা মিলিয়ে নেওয়া হয়, যাতে কম্পিউটারের কপি
        কখনো সার্ভারের সাথে বেমিল হয়ে থেকে না যায় (ফোনের অ্যাপেও একই নিয়ম)।
     ⛔ পড়া ব্যর্থ হলে আগের মতোই জমানো তালিকা অটুট থাকে। */
  let __brSince='',__brFullAt=0;
  try{__brSince=localStorage.getItem('wlv1BriefSince')||'';__brFullAt=+(localStorage.getItem('wlv1BriefFullAt')||0)||0}catch(e){}
  let __brNeedFull=(force===true)||!__brSince||(Date.now()-__brFullAt)>21600000;
  let __brOk=false,__brMax=__brSince;
  try{
   let q=sb.from('briefings').select('*').limit(1000);
   if(!__brNeedFull)q=q.gt('updatedAt',__brSince);
   let {data,error}=await q;
   if(!error&&Array.isArray(data)){
    __brOk=true;
    out=out.concat(normalizeCloudRows(data));
    data.forEach(r=>{let u=String((r&&r.updatedAt)||'').trim();if(u&&u>__brMax)__brMax=u});
    try{
     localStorage.setItem('wlv1BriefSince',__brMax||'1970-01-01T00:00:00.000Z');
     if(__brNeedFull)localStorage.setItem('wlv1BriefFullAt',String(Date.now()));
    }catch(e){}
   }
  }catch(e){}
  /* সফলভাবে পড়া হয়েছে অথচ একটাও নতুন সারি নেই — সেটাও সফল। নইলে ৫ মিনিটের
     বিরতিটা কখনো বসত না, আর শান্ত সময়ে বারবার অনুরোধ যেত। */
  if(__brOk&&!out.length){__wlv1BriefAt=Date.now();return true}
  try{let {data,error}=await sb.from('products').select('*').eq('kind','briefing').limit(1000);if(!error&&Array.isArray(data))out=out.concat(normalizeCloudRows(data).map(briefingFromProductRow).filter(Boolean))}catch(e){}
  if(out.length){
   let map=new Map();
   [...briefings(),...out].forEach(b=>{if(b&&b.id)map.set(b.id,{...(map.get(b.id)||{}),...b})});
   save('briefings',Array.from(map.values()).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))),{skipCloud:true});
   __wlv1BriefAt=Date.now();   // 🔵 V405: **সফল** পড়ার সময়ই কেবল ধরা হয়
   return true;
  }
 }catch(e){}
 return false
}
