// V254 Emergency Safe Fix: dashboard collection card fallback.
// This prevents Dashboard/Login boot failure if collectionDashboardCard is missing.
function collectionDashboardCard(o){
 o=o||{};
 let total=Number(o.total||0);
 // 🔒 B584 (TK-নির্দেশ, ০৮.০৮.২০২৬): Today Collection ₹0 হলে ড্যাশবোর্ডে
 // অটোমেটিক দেখানোর দরকার নেই — ফাঁকা ফেরত, কার্ডই বসে না।
 if(total<=0){ return ''; }
 let clickAttr=isMaster()?` onclick="branchWiseCollectionPage()" style="cursor:pointer"`:'';
 // 🔒 B584 (TK-নির্দেশ): Today Collection এক লাইনে — লেবেল · মোট · ব্রেকডাউন।
 return `<div class="card dashCollectionCard todayCollectionCard tccOneLine"${clickAttr}><b>Today Collection</b><strong>${money(total)}</strong><small>Cash ${money(Number(o.cash||0))} · Online ${money(Number(o.on||0))} · ${Number(o.totalCount||0)} Txn</small></div>`;
}
function branchWiseCollectionPage(){
  if(!isMaster())return toast('শুধু Master Admin');
  let allRows=collectionRows().filter(x=>x.date===today());
  let byBranch={};
  allRows.forEach(r=>{ let b=r.branch||'Unknown',sp=wlv1PaymentSplit(r); byBranch[b]=byBranch[b]||{cash:0,online:0,count:0}; byBranch[b].cash+=sp.cash;byBranch[b].online+=sp.online;byBranch[b].count++; });
  // 🔴 TK-অডিট-অনুরোধ (01.08.2026): collectionRows() Refund সম্পূর্ণ বাদ দেয়
  // (ভুল-যোগ বন্ধ), কিন্তু approved refund তখনও বিয়োগ হত না — overview()-এর
  // একই নিয়ম এখানেও (ব্রাঞ্চ ধরে ধরে) বসানো হলো।
  try{
    load('payments').filter(x=>String(x.date||'').slice(0,10)===today()&&wlv1IsApprovedRefund(x)).forEach(x=>{
      let b=x.branch||'Unknown'; byBranch[b]=byBranch[b]||{cash:0,online:0,count:0};
      let amt=Number(x.amount||0);
      if(payMode(x.mode)==='UPI') byBranch[b].online-=amt; else byBranch[b].cash-=amt;
    });
  }catch(_e){}
  let branches=Object.keys(byBranch);
  let html=branches.length?branches.map(b=>{
    let d=byBranch[b];
    return `<button class="card" style="width:100%;text-align:left" onclick="branchCollectionDetail('${esc(b)}')"><b>${esc(b)}</b><br><strong>${money(d.cash+d.online)}</strong><br><small>Cash ${money(d.cash)} · Online ${money(d.online)} · ${d.count} Transactions</small></button>`;
  }).join(''):'<div class="card mut">আজ কোনো collection নেই</div>';
  page('Branch-wise Collection (Today)',html,true);
}
window["branchWiseCollectionPage"]=branchWiseCollectionPage;
function branchCollectionDetail(branchName){
  let rows=collectionRows().filter(x=>x.date===today()&&(x.branch||'Unknown')===branchName);
  let cash=rows.reduce((s,x)=>s+wlv1PaymentSplit(x).cash,0);
  let online=rows.reduce((s,x)=>s+wlv1PaymentSplit(x).online,0);
  // 🔴 TK-অডিট-অনুরোধ (01.08.2026): এই ব্রাঞ্চের আজকের approved refund বিয়োগ।
  try{
    load('payments').filter(x=>String(x.date||'').slice(0,10)===today()&&(x.branch||'Unknown')===branchName&&wlv1IsApprovedRefund(x)).forEach(x=>{
      let amt=Number(x.amount||0);
      if(payMode(x.mode)==='UPI') online-=amt; else cash-=amt;
    });
  }catch(_e){}
  let list=rows.map(r=>`<div class="card"><b>${esc(r.name||r.mobile||'-')}</b> · ${esc(r.source||'')}<br><small>${esc(r.mode)} · ${money(r.amount)}</small></div>`).join('')||'<div class="card mut">কোনো লেনদেন নেই</div>';
  page(branchName+' — আজকের Collection',`<div class="card"><b>Cash:</b> ${money(cash)} &nbsp; <b>Online:</b> ${money(online)} &nbsp; <b>Total:</b> ${money(cash+online)}</div>${list}`,true);
}
window["branchCollectionDetail"]=branchCollectionDetail;
window["collectionDashboardCard"]=collectionDashboardCard;

