 try{repairConvertedEnquiryRows();repairAtoZWorkflowFormula()}catch(e){};
 /* 🔒 খাতার সারি B119: হোমে ঢুকলে একবার মনে করিয়ে দেয় কার কার রিমার্ক বাকি।
    ⛔ কিছুই আটকায় না, শুধু একটা বার্তা; ব্যর্থ হলেও হোম আগের মতোই খোলে। */
 try{ setTimeout(function(){ try{ wlv1RemarkPendingNotice() }catch(_e){} }, 1200) }catch(_e){}setTimeout(()=>{runWhenIdle(()=>{try{refreshBriefingsFromCloud().then(()=>{});if(sb&&user)flushPendingCloud('pending').catch(()=>{})}catch(e){}},5000)},5000);let c=counts(),o=overview(),role=user.role;
let roleTitle={master:'Master Admin',staff:'Staff',doctor:'Doctor',field:'Field Officer'}[role]||role;
