function wlv1BranchInfo(branch){
  var b=(C.branches||[]).find(function(x){return String(x.name||'').toLowerCase()===String(branch||'').toLowerCase()})||(C.branches||[])[0]||{};
  var clinic=(String(b.name||'')==='Kishanganj')?'TK BISWAS PILES CLINIC':'MAA AYURVED PILES CLINIC';
  return {name:b.name||'',clinic:clinic,address:b.address||'',phone:b.mobile||''};
}
