// 🔒 B588 (TK-নির্দেশ, 08.08.2026): বার্তার তারিখের পাশে সময়ও থাকবে — ফরম্যাট
// "6.30 PM" (h.mm, AM/PM বড় হাতে; অ্যান্ড্রয়েডের লক-করা টাইম-ফরম্যাটের মতো)।
function wlv1NowTime(){ var d=new Date(); var h=d.getHours(); var m=d.getMinutes(); var ap=h>=12?'PM':'AM'; h=h%12; if(h===0)h=12; return h+'.'+(m<10?'0'+m:m)+' '+ap; }
window["wlv1NowTime"]=wlv1NowTime;
function wlv1MsgText(branch,name,pid,kind,o){
  o=o||{};var b=wlv1BranchInfo(branch);
  /* 🔴 V430 — ফোনে তারিখ ও সময় **আলাদা দুটো লাইনে** যায় (শুধু বিলের বার্তায়),
     বাকি বার্তায় শুধু তারিখ। আগে ওয়েবে দুটো জুড়ে একটাই লেখা হত। এখন দুটোই
     আলাদা করে পাঠানো হয়, বার্তা নিজে ঠিক জায়গায় বসিয়ে নেয়। */
  o = Object.assign({}, o, {time: o.time || wlv1NowTime(), paidAt: o.paidAt || o.dateIso || ''});
  var order=(b.name==='Kishanganj')?['hi','bn','en']:['bn','hi','en'];
  var parts=order.map(function(l){return wlv1MsgBlock(l,name,pid,kind,o)});
  // 🔒 B587 (TK-নির্দেশ, 08.08.2026): নিচে একই সই — ধন্যবাদান্তে + TK BISWAS
  // (বড় হাতে) + Founder & Consultant + ব্রাঞ্চের নাম/ঠিকানা/হেল্পলাইন
  // (অ্যান্ড্রয়েডের মতোই)। ব্রাঞ্চ তথ্য অপরিবর্তিত।
  var sign='ধন্যবাদান্তে\nTK BISWAS\nFounder & Consultant\n\n'+b.clinic+'\n'+b.address+'\nহেল্পলাইন : '+b.phone;
  return parts.join('\n\n')+'\n\n'+sign;
}
window["wlv1MsgText"]=wlv1MsgText;
// 🔒 B591 (TK-নির্দেশ, 08.08.2026): ওয়েবেও এক-ভাষার বার্তা (bn/hi/en যেটা বাছা হবে)
// — অ্যান্ড্রয়েডের মতোই। সই সেই ভাষা অনুযায়ী (বাংলায় "ধন্যবাদান্তে", হিন্দি/English সরাসরি নাম)।
function wlv1MsgTextLang(branch,name,pid,kind,o,lang){
  o=o||{};var b=wlv1BranchInfo(branch);
  /* 🔴 V430 — উপরের একই নিয়ম (তারিখ ও সময় আলাদা)। */
  o = Object.assign({}, o, {time: o.time || wlv1NowTime(), paidAt: o.paidAt || o.dateIso || ''});
  lang=(lang==='hi'||lang==='en')?lang:'bn';
  var body=wlv1MsgBlock(lang,name,pid,kind,o);
  var sign=(lang==='bn')
    ? 'ধন্যবাদান্তে\nTK BISWAS\nFounder & Consultant\n\n'+b.clinic+'\n'+b.address+'\nহেল্পলাইন : '+b.phone
    : 'TK BISWAS\nFounder & Consultant\n\n'+b.clinic+'\n'+b.address+'\nHelpline : '+b.phone;
  return body+'\n\n'+sign;
}
window["wlv1MsgTextLang"]=wlv1MsgTextLang;

/* 🔒 TK-APPROVED (28.07.2026) — কম্পিউটারে ক্লিনিকের কার্ড (ছবি)।
   ব্রাউজার নিজেই আঁকে, ইন্টারনেট লাগে না, কোনো ওয়াটারমার্ক বা টুলের নাম নেই।
   ⚠️ কম্পিউটারের WhatsApp Web-এ লিংক দিয়ে ছবি পাঠানো যায় না — তাই এখানে
   ছবিটা নামিয়ে নেওয়ার বোতাম, স্টাফ চাইলে WhatsApp-এ জুড়ে দেবেন। লেখা
   পাঠানোর পথ আগের মতোই আছে। */
function wlv1CardImage(branch,text,cb){
  try{
    var b=wlv1BranchInfo(branch);
    var W=1080,PAD=56,lineH=44;
    var probe=document.createElement('canvas').getContext('2d');
    probe.font='30px sans-serif';
    var lines=[];
    String(text||'').split('\n').forEach(function(raw){
      if(!raw.trim()){lines.push('');return}
      var line='';
      raw.split(' ').forEach(function(w){
        var t=line?line+' '+w:w;
        if(probe.measureText(t).width<=W-PAD*2){line=t}else{if(line)lines.push(line);line=w}
      });
      lines.push(line);
    });
    var headerH=240,footerH=120,H=headerH+lines.length*lineH+60+footerH;
    var cv=document.createElement('canvas');cv.width=W;cv.height=H;
    var c=cv.getContext('2d');
    c.fillStyle='#FDFCF9';c.fillRect(0,0,W,H);
    var g=c.createLinearGradient(0,0,W,headerH);g.addColorStop(0,'#082E26');g.addColorStop(1,'#0E4C38');
    c.fillStyle=g;c.fillRect(0,0,W,headerH);
    c.fillStyle='#C6A04A';c.fillRect(0,headerH-5,W,5);
    var draw=function(logoImg){
      var left=PAD;
      if(logoImg){
        c.fillStyle='#FFFFFF';c.fillRect(PAD,40,160,160);
        c.drawImage(logoImg,PAD+14,54,132,132);
        c.strokeStyle='#C6A04A';c.lineWidth=4;c.strokeRect(PAD,40,160,160);
        left=PAD+190;
      }
      var parts=String(b.clinic).split(' ');
      c.fillStyle='#FFFFFF';c.font='bold 46px sans-serif';
      c.fillText(parts.slice(0,-2).join(' ')||b.clinic,left,96);
      c.fillStyle='#C6A04A';c.font='bold 38px sans-serif';
      c.fillText(parts.slice(-2).join(' '),left,148);
      c.fillStyle='#C4D6CE';c.font='24px sans-serif';
      c.fillText(b.address,left,190);
      c.fillStyle='#3A485C';c.font='30px sans-serif';
      var y=headerH+52;
      lines.forEach(function(l){if(l)c.fillText(l,PAD,y);y+=lineH});
      c.fillStyle='#082E26';c.fillRect(0,H-footerH,W,footerH);
      c.fillStyle='#C6A04A';c.font='bold 32px sans-serif';
      c.fillText('Helpline  '+b.phone,PAD,H-footerH+74);
      cv.toBlob(function(bl){cb(bl)},'image/png');
    };
    var img=new Image();
    img.onload=function(){draw(img)};
    img.onerror=function(){draw(null)};
    img.src=(b.name==='Kishanganj')?'assets/kishanganj-final-logo.jpg':'assets/maa-ayurved-final-logo.jpg';
  }catch(e){try{cb(null)}catch(_e){}}
}
window["wlv1CardImage"]=wlv1CardImage;
function wlv1DownloadCard(branch){
  var t=window.__wlv1MsgText||'';
  wlv1CardImage(branch,t,function(bl){
    if(!bl)return toast('Could not make the image');
    try{
      var a=document.createElement('a');
      a.href=URL.createObjectURL(bl);a.download='clinic-message.png';a.click();
      setTimeout(function(){URL.revokeObjectURL(a.href)},4000);
      toast('Image downloaded — attach it in WhatsApp');
    }catch(e){toast('Could not download the image')}
  });
}
window["wlv1DownloadCard"]=wlv1DownloadCard;

// 🔴🟢 খাতার সারি B433 (TK-নির্দেশ, 05.08.2026 — "দুইজন স্টাফ একই ব্যক্তিকে
// একই বার্তা পাঠিয়েছেন, রোগী বিভ্রান্ত হয়ে গেছেন। নিয়ম একই হবে সব
// ব্রাঞ্চ/সব জায়গায় — পেশেন্ট বললেই RMP-তে আলাদা হবে না")। ফোনের
// `MessageSentLog.kt`-এর ঠিক একই নিয়ম, একই ক্লাউড টেবিল (`message_log`)।
// ⛔ শুধু মনে করিয়ে দেয়, পাঠানো আটকায় না।
async function wlv1CheckPriorSend(mobile,kind,recipientType){
  try{
    let ok=await initCloudClientOnly();
    if(!ok||!sb)return null;
    let d=mob(mobile);
    if(!d||d.length!==10)return null;
    let {data,error}=await sb.from('message_log').select('sent_by_name,sent_at,channel')
      .eq('mobile',d).eq('kind',kind).eq('recipient_type',recipientType||'patient')
      .order('sent_at',{ascending:false}).limit(1);
    if(error||!Array.isArray(data)||!data.length)return null;
    return data[0];
  }catch(e){return null}
}
window["wlv1CheckPriorSend"]=wlv1CheckPriorSend;
function wlv1LogSent(mobile,kind,branch,name,channel,recipientType){
  try{
    let d=mob(mobile);
    if(!d||d.length!==10||!kind)return;
    let row={id:'mlog_'+Date.now()+'_'+d,mobile:d,kind,recipient_type:recipientType||'patient',
      branch:branch||'',name:name||'',sent_by:(user&&user.mobile)||'',sent_by_name:(user&&user.name)||'',channel};
    initCloudClientOnly().then(ok=>{ if(ok&&sb) sb.from('message_log').upsert([row],{onConflict:'id'}).catch(()=>{}) }).catch(()=>{})
  }catch(e){}
}
window["wlv1LogSent"]=wlv1LogSent;
function wlv1PriorWarningHtml(prior){
  if(!prior)return '';
  let who=esc(prior.sent_by_name||'staff');
  let when=prior.sent_at?(' — '+esc(fmtDateTime(prior.sent_at))):'';
  return '<div style="background:#FFF6E0;border-radius:10px;padding:8px 10px;margin:0 0 8px;font-size:12px;font-weight:bold;color:#8A5A00">⚠️ Already sent by '+who+when+'.</div>';
}
async function wlv1AskSend(branch,name,mobile,pid,kind,o,waOnly){
  try{
    var d=mob(mobile);if(!d||d.length!==10)return;
    // 🔒 B591 (TK-নির্দেশ): আগে ভাষা বাছাই (bn/hi/en), তারপর সেই এক ভাষার বার্তা।
    // 🔒 B592 (TK-নির্দেশ): অ্যান্ড্রয়েডের showLanguagePicker-এর হুবহু চেহারা —
    // সবুজ হেডার + সাবটাইটেল + প্রতিটা ভাষার কার্ড (নাম + ছোট বর্ণনা)।
    window.__wlv1SendArgs={branch:branch,name:name,mobile:mobile,pid:pid,kind:kind,o:o,waOnly:waOnly};
    var __opt=function(lang,label,sub){return '<div onclick="wlv1PickSendLang(\''+lang+'\')" style="cursor:pointer;background:#F7FAFC;border:1px solid #D8E1EC;border-radius:12px;padding:12px 14px;margin:0 0 8px"><div style="font-size:15px;font-weight:800;color:#10223A">'+label+'</div><div style="font-size:12px;color:#6B7A90;margin-top:2px">'+sub+'</div></div>';};
    modal('<div class="card" style="padding:0;overflow:hidden">'+
      '<div style="background:#145A32;color:#fff;font-size:16px;font-weight:800;padding:14px 16px">🌐 বার্তার ভাষা বাছুন</div>'+
      '<div style="padding:12px 16px 2px;font-size:12.5px;color:#3C4859">'+esc(name||'')+' · '+esc(d)+' — কোন ভাষায় বার্তা পাঠাবেন?</div>'+
      '<div style="padding:8px 16px 2px">'+
        __opt('bn','Bengali','বাংলায় বার্তা পাঠান')+
        __opt('hi','Hindi','हिंदी में संदेश भेजें')+
        __opt('en','English','Send message in English')+
      '</div>'+
      '<div style="padding:2px 16px 16px"><button class="ghost" style="width:100%" onclick="closeModal()">Cancel</button></div>'+
      '</div>');
  }catch(e){console.warn('lang pick skipped',e)}
}
function wlv1PickSendLang(lang){ var a=window.__wlv1SendArgs||{}; closeModal(); wlv1AskSendLang(a.branch,a.name,a.mobile,a.pid,a.kind,a.o,lang,a.waOnly); }
window["wlv1PickSendLang"]=wlv1PickSendLang;
async function wlv1AskSendLang(branch,name,mobile,pid,kind,o,lang,waOnly){
  try{
    var d=mob(mobile);if(!d||d.length!==10)return;
    var text=wlv1MsgTextLang(branch,name,pid,kind,o,lang);
    // 🔒 B589 (TK-অনুমোদিত): reg/payment বার্তায় A4 রসিদ বোতাম।
    var __pRec=load('patients').find(function(x){return mob(x.mobile)===d;});
    var __a4Kind=(kind==='reg')?'reg':((kind==='pay'||kind==='adv'||kind==='receipt'||kind==='bill')?'pay':'');
    var __a4Btn=(__a4Kind&&__pRec)?('<button style="width:100%;margin-top:8px;background:#0f5132;color:#fff;border:none" onclick="wlv1ShowMsgA4()">📄 A4 '+(__a4Kind==='reg'?'Registration':'Receipt')+' — Send / Print</button>'):'';
    window.__wlv1A4Ctx={id:(__pRec&&__pRec.id)||'',kind:__a4Kind,o:o||{}};
    var prior=null;
    try{ prior=await wlv1CheckPriorSend(d,kind,'patient'); }catch(_e){}
    modal('<div class="card">'+wlv1PriorWarningHtml(prior)+'<h3 style="margin:0 0 8px">Send to patient</h3>'+
      '<div style="font-size:12.5px;color:#475467;margin-bottom:6px">'+esc(name||'')+' · '+esc(d)+'</div>'+
      '<pre style="white-space:pre-wrap;font-family:inherit;font-size:12.5px;background:#f7fafc;border:1px solid #e2e8f0;border-radius:10px;padding:10px;margin:0 0 10px">'+esc(text)+'</pre>'+
      '<div style="display:flex;gap:8px">'+
      '<button style="flex:1;background:#0C9E33;color:#fff;border:none" onclick="wlv1DoSend(\''+d+'\',\'wa\')">WhatsApp</button>'+
      '<button style="flex:1;background:#E4E8EE;color:#3C4859;border:none" onclick="closeModal()">পরে পাঠাব</button>'+
      '<button style="flex:1;background:#1E5AB4;color:#fff;border:none" onclick="wlv1DoSend(\''+d+'\',\'sms\')">SMS</button>'+
      '</div>'+
      __a4Btn+'</div>');
    window.__wlv1MsgText=text;
    window.__wlv1MsgMeta={branch:branch,name:name,mobile:d,kind:kind};
  }catch(e){console.warn('patient message skipped',e)}
}
window["wlv1AskSend"]=wlv1AskSend;
window["wlv1AskSendLang"]=wlv1AskSendLang;
function wlv1ShowMsgA4(){ var c=window.__wlv1A4Ctx||{}; if(!c.id)return toast('Patient not found'); if(c.kind==='reg')wlv1ShowRegA4(c.id,c.o||{}); else wlv1ShowPayA4(c.id,c.o||{}); }
window["wlv1ShowMsgA4"]=wlv1ShowMsgA4;
function wlv1DoSend(digits,how){
  var t=window.__wlv1MsgText||'';
  var meta=window.__wlv1MsgMeta||{};
  try{
    if(how==='wa')window.open('https://wa.me/91'+digits+'?text='+encodeURIComponent(t),'_blank');
    else window.location.href='sms:'+digits+'?body='+encodeURIComponent(t);
    // 🔴🟢 খাতার সারি B433 — সত্যিই পাঠানো হলে ব্যাকগ্রাউন্ডে রেকর্ড হয়।
    if(meta.kind)wlv1LogSent(digits,meta.kind,meta.branch,meta.name,how==='wa'?'whatsapp':'sms','patient');
  }catch(e){toast('Could not open the app')}
  try{closeModal()}catch(e){}
}
window["wlv1DoSend"]=wlv1DoSend;

function wlv1PhTint(id){var el=document.getElementById(id);if(!el)return;var set=function(){el.style.color=(String(el.value||'')===''?'#8A97AB':'');};set();el.addEventListener('change',set);}
window["wlv1PhTint"]=wlv1PhTint;
function branchOptions(sel=''){return C.branches.map(b=>`<option ${sel===b.name?'selected':''}>${b.name}</option>`).join('')}
window["branchOptions"]=branchOptions;
function allUsers(){let u=C.users||{};return Array.isArray(u)?u:Object.entries(u).flatMap(([role,list])=>(list||[]).map(x=>({...x,role})))}
window["allUsers"]=allUsers;
function staffOptions(sel=''){let users=allUsers();let list=users.filter(u=>u.role==='staff'&&(isMaster()||u.branch===user.branch||user.branch==='All'));if(!list.length&&user)list=[user];let seen=new Set();list=list.filter(u=>{let k=mob(u.mobile||u.name);if(!k||seen.has(k))return false;seen.add(k);return true});return list.map(u=>`<option value="${esc(u.mobile||u.name)}" ${String(sel||user?.mobile)==String(u.mobile)?'selected':''}>${esc(u.name||u.mobile)} - ${esc(mob(u.mobile))} (${esc(u.branch||'')})</option>`).join('')}
window["staffOptions"]=staffOptions;
function callReceivedOptions(sel=''){let users=allUsers();let adminList=users.filter(u=>u.role==='master');if(!adminList.length&&user?.role==='master')adminList=[user];let staffList=users.filter(u=>u.role==='staff'&&(isMaster()||u.branch===user.branch||user.branch==='All'));if(user?.role==='staff'&&!staffList.some(u=>mob(u.mobile)===mob(user.mobile)))staffList.unshift(user);let seen=new Set();let opts=[];adminList.forEach(u=>{let v=u.mobile||'Admin';let k=mob(v)||'Admin';if(seen.has('admin'+k))return;seen.add('admin'+k);opts.push(`<option value="${esc(v)}" ${mob(sel||user?.mobile)===mob(v)?'selected':''}>Admin</option>`)});staffList.forEach(u=>{let v=u.mobile||u.name||'';let k=mob(v)||v;if(!k||seen.has('staff'+k))return;seen.add('staff'+k);opts.push(`<option value="${esc(v)}" ${mob(sel||user?.mobile)===mob(v)?'selected':''}>${esc(codeName(v))}</option>`)});return opts.join('')}
window["callReceivedOptions"]=callReceivedOptions;

function patientPhotoInputs(prefix,hasPhoto=false){return `<div class="photoChoice premiumPhotoChoice regPhotoChoice"><button type="button" class="small ghost" onclick="document.getElementById('${prefix}Camera').click()">📷 Open Camera</button><button type="button" class="small ghost" onclick="document.getElementById('${prefix}Gallery').click()">🖼️ Gallery</button>${hasPhoto?`<button type="button" class="small ghost redText" onclick="removePatientPhoto('${prefix}')">🗑️ Remove Photo</button>`:''}<input id="${prefix}Camera" class="hiddenFile" type="file" accept="image/*" capture="environment"><input id="${prefix}Gallery" class="hiddenFile" type="file" accept="image/*"></div>`}
window["patientPhotoInputs"]=patientPhotoInputs;
function photoFromEither(prefix){return fileData(document.getElementById(prefix+'Camera')).then(x=>x||fileData(document.getElementById(prefix+'Gallery')))}
window["photoFromEither"]=photoFromEither;
function removePatientPhoto(prefix){let id=$('#'+prefix+'PatientId')?.value;if(!id)return toast('Patient not found');let p=upd('patients',id,{photo:''});/* 🔴 TK-অনুমোদিত: followups-এ ছবি-কপি বন্ধ */toast('Photo removed');closeModal();try{followup('Patient')}catch(e){summary(id)}}
window["removePatientPhoto"]=removePatientPhoto;
// V106 selective safe fix: patient photo pen button must not throw editPatientPhoto is not defined.
/* 🖥️🔵 Patient Photo — পপ-আপ থেকে **পূর্ণ পাতা** (TK-অনুমোদিত প্রুফ, ১৫.০৮.২০২৬, "খুব সাবধানে")।
   Android-এর `native/PatientPhotoActivity.kt` (২৭৯ লাইন) + `activity_patient_photo.xml` পড়ে মিলিয়ে:
   ← Back · রোগীর তথ্য-কার্ড (নাম · ☎ নম্বর · 🆔 আইডি) · **বড় করে ছবি** · তারপর বোতাম।
   ⛔ **চারটে বোতামের কাজ (onclick) এক অক্ষরও বদলায়নি** — একই `savePatientPhotoInput()` ·
      `removePatientPhotoById()` · একই লুকানো file input দুটো (একই id, একই accept/capture)।
   ⛔ **TK-কে আগে জানিয়ে অনুমতি নেওয়া দুটো বিষয়:**
      (১) ফোনে আলাদা "Save Photo" বোতাম আছে; ওয়েবে ছবি বাছলেই **সঙ্গে সঙ্গে সেভ** হয় —
          এটা চালু নিয়ম, **ইচ্ছে করে অপরিবর্তিত** রাখা হলো (স্টাফ এভাবেই অভ্যস্ত)।
      (২) Cancel/Back → অ্যাপের নিজের `goBackOnePage()` (লাইন ১১৯৭), নতুন কিছু বানানো হয়নি।
   ⛔ ছবি না থাকলে আগের মতোই "Remove Photo" দেখায় না।                                    */
function openPatientPhotoSheet(p){
 if(!p)return toast('Patient not found');
 let has=!!p.photo;
 let pic = has ? `<img class="ppPhoto" src="${esc(p.photo)}" alt="Patient photo">`
                : `<div class="ppPhoto ppBlank">👤</div>`;
 let meta = (p.mobile?`<div class="ppMeta">☎ ${esc(normMob(p.mobile))}</div>`:'')
          + (p.patientId?`<div class="ppMeta">🆔 ${esc(p.patientId)}</div>`:'');
 page('Patient Photo', `<div class="card ppCard">
  <input id="editPatientId" type="hidden" value="${esc(p.id)}">
  <div class="ppInfo"><div class="ppAvatar">👤</div>
    <div><div class="ppName">${esc(String(p.name||'').toUpperCase()||normMob(p.mobile||''))}</div>${meta}</div></div>
  <div class="ppPhotoWrap">${pic}</div>
  <div class="ppBtns">
    <button type="button" class="ghost" onclick="document.getElementById('editPatientCamera').click()">📷 Open Camera</button>
    <button type="button" class="ghost" onclick="document.getElementById('editPatientGallery').click()">🖼️ Gallery</button>
    ${has?`<button type="button" class="ghost redText" onclick="removePatientPhotoById('${esc(p.id)}')">🗑️ Remove Photo</button>`:''}
    <button type="button" class="ghost" onclick="goBackOnePage()">❌ Cancel</button>
  </div>
  <input id="editPatientCamera" class="hiddenFile" type="file" accept="image/*" capture="environment" onchange="savePatientPhotoInput('${esc(p.id)}',this)">
  <input id="editPatientGallery" class="hiddenFile" type="file" accept="image/*" onchange="savePatientPhotoInput('${esc(p.id)}',this)">
 </div>`, true);
}
window["openPatientPhotoSheet"]=openPatientPhotoSheet;
function editPatientPhoto(id){let p=load('patients').find(x=>x.id===id)||load('patients').find(x=>mob(x.mobile)===mob(id));openPatientPhotoSheet(p)}
window["editPatientPhoto"]=editPatientPhoto;
async function savePatientPhotoInput(id,inp){let data=await fileData(inp);if(!data)return;let p=upd('patients',id,{photo:data});if(!p)return toast('Patient not found');/* 🔴 TK-অনুমোদিত (02.08.2026, স্ক্রিনশটে দাগ দিয়ে আলোচনা করে): followups-এ ছবির কপি বসানো বন্ধ — কোথাও দেখানোই হতো না, শুধু জায়গা/Egress খরচ করত। patients.photo-ই এখন একমাত্র উৎস। */toast('Photo saved');closeModal();try{followup('Patient')}catch(e){try{summary(id)}catch(_){dashboard()}}}
window["savePatientPhotoInput"]=savePatientPhotoInput;
function removePatientPhotoById(id){let p=upd('patients',id,{photo:''});if(!p)return toast('Patient not found');/* 🔴 TK-অনুমোদিত: followups-এ ছবি-কপি বন্ধ, নিচে ব্যাখ্যা savePatientPhotoInput-এ */toast('Photo removed');closeModal();try{followup('Patient')}catch(e){try{summary(id)}catch(_){dashboard()}}}
window["removePatientPhotoById"]=removePatientPhotoById;
/* TK (27.07.2026), ধাপ ৩: একই রোগীর দুটো 'patients' সারি থাকলে (ডুপ্লিকেট রেজিস্ট্রেশন) কোন সারিটা আসল — এখন ফোন আর কম্পিউটার একই নিয়ম মানে: ১) চলতি ব্রাঞ্চের সারি, ২) নইলে যে সারিতে সত্যিকারের বিল আছে, ৩) নইলে প্রথমটা। একটাই সারি থাকলে (স্বাভাবিক অবস্থা) আগের মতোই সেটাই। */
function wlv1PickPatientRow(list,preferBranch){if(!list||!list.length)return null;if(list.length===1)return list[0];let branchMatch=null,billed=null;for(const r of list){if(!r)continue;if(!branchMatch&&preferBranch&&String(r.branch||'').toLowerCase()===String(preferBranch||'').toLowerCase())branchMatch=r;if(!billed&&Number(r.bill||0)>0)billed=r;}return branchMatch||billed||list[0];}
function patientByFollow(x){return wlv1PickPatientRow(load('patients').filter(p=>mob(p.mobile)===mob(x.mobile)||p.id===x.refId),x&&x.branch)||undefined}
window["patientByFollow"]=patientByFollow;
function editPatientPhotoByMobile(m){let p=load('patients').find(x=>mob(x.mobile)===mob(m));if(!p)return toast('Patient link missing. Please retry');editPatientPhoto(p.id)}
window["editPatientPhotoByMobile"]=editPatientPhotoByMobile;
// V195 Global Photo Edit Lock: no pen icon. Patient photo is square and opens edit only after 3 taps/clicks.
// No visible hint text is shown anywhere.
let __photoTapState={key:'',count:0,at:0};
function handlePatientPhotoTap(key){
 let k=String(key||''),now=Date.now();
 if(__photoTapState.key!==k||now-__photoTapState.at>1200)__photoTapState={key:k,count:0,at:now};
 __photoTapState.count++;__photoTapState.at=now;
 if(__photoTapState.count>=3){__photoTapState={key:'',count:0,at:0};editPatientPhotoByMobile(k)}
}
window["handlePatientPhotoTap"]=handlePatientPhotoTap;


/* ==== WEB APP . helpers that make this screen behave exactly like the native
   Android app (TK rule, 2026.07.25: whatever the native app has, the web app
   must have the same). All names start with wlv1 so nothing existing clashes. */
function wlv1Dot(iso){ if(!iso) return ''; const p=String(iso).split('-'); return p.length===3?(p[2]+'.'+p[1]+'.'+p[0]):String(iso); }
window["wlv1Dot"]=wlv1Dot;
function wlv1ShowDate(inputId,showId){ const i=$('#'+inputId), s=$('#'+showId); if(i&&s) s.textContent = i.value? wlv1Dot(i.value) : (showId==='eNextShow'?'Tap to select (optional)':''); }
window["wlv1ShowDate"]=wlv1ShowDate;
/* 🔴🔴🔴🆕🔒 V436 (TK-রিপোর্ট ১৮.০৮.২০২৬ — *"ওয়েব এ Date Format ঠিক নেই কেন?
   31/12/2026 এরকম থাকার কথা ছিল"*)।
   **কারণ:** `<input type="date">` ঘরটা ব্রাউজার **নিজের ভাষা অনুযায়ী** আঁকে —
   TK-এর Chrome ইংরেজি(US) বলে **08/18/2026** দেখাত। HTML/CSS দিয়ে ওটা বদলানো
   যায় না। প্রজেক্টে ৫টা ঘরে আগে থেকেই সমাধান ছিল (`wlv1DateBox`): উপরে নিজেদের
   লেখা দেখানো হয়, আর আসল ঘরটা স্বচ্ছ করে তার উপরে বসানো — চাপলে সেই একই
   ক্যালেন্ডারই খোলে। বাকি **১৩টা** ঘরে সেটা ছিল না।
   এই ফাংশনটা পর্দা আঁকার পরে ওই বাকি ঘরগুলোতেও ঠিক একই ব্যবস্থা বসিয়ে দেয়।
   ⛔ **ঘরটা মোছা বা নতুন করে বানানো হয় না** — একই নোড সরিয়ে মোড়কের ভিতরে
      রাখা হয়, তাই `id` · `onchange` · `value` · সব হ্যান্ডলার অক্ষত থাকে।
   ⛔ ঘরের নিজের ক্লাস (`input` ইত্যাদি) দেখানোর লেখাটাতে বসানো হয়, তাই চেহারা
      আগের মতোই থাকে।
   ⛔ যেগুলো আগেই `wlv1DateBox`-এর ভিতরে, সেগুলো ছোঁয়া হয় না (দুবার হয় না)।
   ⛔ যেকোনো গোলমালে নিঃশব্দে বাদ — পর্দা আগের মতোই চলে। */
function wlv1AutoDateBoxes(root){
  try{
    var list=(root||document).querySelectorAll('input[type="date"]');
    for(var i=0;i<list.length;i++){
      var inp=list[i];
      if(!inp||inp.getAttribute('data-wlv1db')) continue;
      if(inp.closest&&inp.closest('.wlv1DateBox')) continue;
      var box=document.createElement('div');
      box.className='wlv1AutoDateBox';
      var sp=document.createElement('span');
      sp.className=(inp.className||'')+' wlv1AutoDateTxt';
      if(!inp.parentNode) continue;
      inp.parentNode.insertBefore(box,inp);
      box.appendChild(sp); box.appendChild(inp);
      inp.setAttribute('data-wlv1db','1');
      (function(inp2,sp2){
        var paint=function(){
          try{
            /* ⛔ ফোনের সঙ্গে হুবহু: ফোনের ফরম/ছাঁকনিতে তারিখ **বিন্দু** দিয়ে
               (`dotDate` ⇒ 18.08.2026); শুধু Payment-এর হেডারে স্ল্যাশ
               (`PaymentActivity.kt:204`)। তাই এখানেও বিন্দু — দুই জায়গাতেই
               দিন আগে, মাস পরে (আর কখনো আমেরিকান ধরন নয়)। */
            sp2.textContent = inp2.value
              ? String(wlv1Dot(inp2.value))
              : (inp2.getAttribute('data-empty')||'dd.mm.yyyy');
          }catch(e){}
        };
        paint();
        inp2.addEventListener('input',paint);
        inp2.addEventListener('change',paint);
      })(inp,sp);
    }
  }catch(e){}
}
window["wlv1AutoDateBoxes"]=wlv1AutoDateBoxes;

