async function initCloudClientOnly(){
 // V221 real save fix: create Supabase client without doing an immediate pull/reset.
 // A full initCloud() pull right after Save could refresh the list before the new row is uploaded,
 // making staff see "saved" but not find the record. Save path must upsert first.
 try{
  if(sb)return true;
  if(!C.supabaseUrl||!C.supabaseKey)return false;
  await ensureSupabaseSdk();
  if(!window.supabase)return false;
  sb=window.supabase.createClient(C.supabaseUrl,C.supabaseKey);
  try{wireRealtime()}catch(e){}
  return true;
 }catch(e){return false}
}
window["initCloudClientOnly"]=initCloudClientOnly;
async function directCloudUpsertRow(t,row){
 const carriesPhotoField=!!(row&&typeof row==='object'&&(Object.prototype.hasOwnProperty.call(row,'photo')||Object.prototype.hasOwnProperty.call(row,'patientPhoto')));
 try{
  protectNewRow(t,row);
  let ok=await initCloudClientOnly();
  if(!ok||!sb){
   try{if(RT_NO_PHOTO_COLS[t]&&carriesPhotoField)wlv1PhotoPendingAdd(t,row&&row.id)}catch(_e){}
   markPendingCloud(t);return false
  }
  for(const ct of CLOUD_TABLE_ALIASES(t)){
   let payload=cloudSafeRows(t,[withMeta(t,row,false)]);
   let r=await cloudUpsertAdaptive(ct,t,payload);
   // 🔵 শুধু এই payload সত্যিই photo ঘর বহন করলে সফলতার পরে photo-pending মুছি।
   // সাধারণ non-photo update কোনো আগের offline photo retry ভুল করে মুছতে পারবে না।
   if(r.ok){clearPendingCloud(t);try{if(RT_NO_PHOTO_COLS[t]&&carriesPhotoField)wlv1PhotoPendingDel(t,row&&row.id)}catch(_e){}return true}
  }
 }catch(e){console.warn('direct cloud upsert failed',t,e)}
 // 🔵 সরাসরি photo upload ব্যর্থ হলে তবেই id মনে রাখি; non-photo update এখানে ঢুকবে না।
 try{if(RT_NO_PHOTO_COLS[t]&&carriesPhotoField)wlv1PhotoPendingAdd(t,row&&row.id)}catch(_e){}
 markPendingCloud(t);return false
}
window["directCloudUpsertRow"]=directCloudUpsertRow;
