function duplicatePopup(d){
 let name=d.name||normMob(d.mobile),typ=duplicateType(d),mm=mob(d.mobile);
 let cont=typ==='Enquiry'?`<button onclick="continueRegistrationFromEnquiry('${mm}')">Registration</button>`:'';
 let isRejected=wlv1IsTerminalFollowStatus(d.status);
 let contEntry=`<button onclick=\"wlv1ContinueEntry('${mm}')\">Continue Entry</button>`;
 let cancelBtn=isRejected?'':`<button style="background:#d92d20;color:#fff" onclick="duplicatePopupCancelTop('${mm}')">Reject</button>`;
 modal(`<h2>⚠️ এই নম্বর আগেই সিস্টেমে আছে</h2><div class="card duplicateCard"><div><b>নাম:</b> ${esc(name)}<br><b>Mobile:</b> ${esc(normMob(d.mobile))}<br><b>Branch:</b> ${esc(d.branch||'-')}</div><span class="dupStatusBadge">${esc(d.stage||d.status||'-')}</span></div><div class="actions duplicateActions"><button onclick="closeModal();summaryByMobile('${mm}')">Preview History</button>${cont}${contEntry}${cancelBtn}</div>`)}

/* 🔴 TK-REPORTED CLASS OF PROBLEM (ঠিক করা হলো 27.07.2026): কম্পিউটারে এই
   "Continue Entry" বোতামগুলো (তিন জায়গায়) কিছুই করত না — শুধু একটা লেখা দেখাত,
   পুরনো এন্ট্রি আপডেট হত না। ফোনের অ্যাপে এই কাজটা আগে থেকেই আছে
   (EnquiryRepository.restoreAndMove) এবং এটা TK-এর লক করা নিয়ম: একই নম্বরে কখনো
   দ্বিতীয় রেকর্ড তৈরি হবে না — পুরনো রেকর্ডটাই ফিরিয়ে এনে, ফরমে যে ব্রাঞ্চ বাছা
   হয়েছে সেখানে সরানো হবে, পুরনো ইতিহাস অক্ষত রেখে। টাকা/পেমেন্টে হাত দেওয়া হয় না। */
function wlv1ContinueEntry(mmRaw){
 try{
  const m=mob(mmRaw);
  if(!m)return toast('Mobile missing');
  const val=id=>{try{const el=$('#'+id);return el?String(el.value||'').trim():''}catch(_e){return ''}};
  const br=val('eBranch'), dis=val('eDis'), rem=val('eRem'), next=val('eNext');
  const staff=user?.name||user?.mobile||'';
  const now=new Date().toISOString();
  const push=[]; let touched=0;

  let fus=load('followups').map(f=>{
   if(mob(f.mobile)!==m)return f;
   touched++;
   const nf={...f,
    branch:br||f.branch, status:'Active', nextFollow:next||f.nextFollow, updatedAt:now,
    lastRemark:rem||f.lastRemark, disease:dis||f.disease,
    history:[...(f.history||[]),{date:today(),remark:'Restored & moved to '+(br||f.branch||'')+' (Enquiry form)',staff:staff,status:'Active'}]};
   push.push({table:'followups',row:nf});
   return nf;
  });
  save('followups',fus);

  let enqs=load('enquiries').map(e=>{
   if(mob(e.mobile)!==m)return e;
   touched++;
   const ne={...e,branch:br||e.branch,status:'Active',disease:dis||e.disease,updatedAt:now};
   push.push({table:'enquiries',row:ne});
   return ne;
  });
  save('enquiries',enqs);

  /* রোগীর সারিতে শুধু ব্রাঞ্চ — টাকার হিসাব ছোঁয়া হয় না (ফোনের নিয়মের মতোই)। */
  let pats=load('patients').map(p=>{
   if(mob(p.mobile)!==m)return p;
   touched++;
   const np={...p,branch:br||p.branch,updatedAt:now};
   push.push({table:'patients',row:np});
   return np;
  });
  save('patients',pats);

  if(!touched){closeModal();return toast('Old record not found — please try again')}
  push.forEach(x=>{try{directCloudUpsertRow(x.table,x.row)}catch(_e){try{markPendingCloud(x.table)}catch(__e){}}});
  closeModal();
  toast('Old entry updated'+(br?(' — moved to '+br):''));
  try{['eName','eMob','eAddr','eRem'].forEach(i=>{let el=$('#'+i);if(el)el.value=''})}catch(_e){}
  setTimeout(()=>{try{followup('Inquiry')}catch(_e){}},150);
 }catch(e){toast('Could not update — please try again')}
}
window["wlv1ContinueEntry"]=wlv1ContinueEntry;
