function patientJourneySource(x){
 let cb=String(x?.createdBy||x?.receivedBy||'').trim();
 if(cb==='Public Website'||String(x?.timeType||'').includes('Online')||String(x?.disease||'').includes('Public Appointment')||x?.appointmentDate)return 'Public Website (Book Appointment)';
 if(String(x?.refBy||'').trim())return String(x.refBy).trim();
 return cb||'Staff Entry / Phone Call';
}
