   let followupsByRefOrMobilePatientStage=new Map();
   followupsArr.forEach((f,idx)=>{
     if(String(f.stage||'')==='Patient'){
       if(f.refId)followupsByRefOrMobilePatientStage.set('r:'+f.refId, idx);
       let mm=mob(f.mobile); if(mm)followupsByRefOrMobilePatientStage.set('m:'+mm, idx);
     }
   });
