function signalCancelEntry(followId){
  let rows=load('followups'),i=rows.findIndex(a=>a.id===followId);
  if(i<0)return;
  let x=rows[i];
  // 🔒 V217 (§B216, Master Fix Order §14, item 1 — কম্পিউটারেও, TK-এর "ঝুঁকিহীন"
  // নির্দেশে): ফোনের অ্যাপের একই Same-Day নিয়ম এখানেও — নতুন কোনো বোতাম/UI নয়,
  // আগে থেকেই থাকা `wlv1CanDeletePaymentNow`-এর সেই একই পরীক্ষিত ফাংশন
  // পুনর্ব্যবহার (আজ/গতকাল + নিজের ব্রাঞ্চ + চেম্বার বন্ধ না থাকলে)।
  // 🆕 B467 (06.08.2026): এই বোতাম শুধু Enquiry কার্ডেই থাকে (callSignal
  // "Enquiry" লেবেল) — টাকা এখনো জমা পড়েনি, তাই TK-নির্দেশে এখন সবসময় ফ্রি।
  if(!isMaster() && typeof wlv1CanDeletePaymentNow==='function' && !wlv1CanDeletePaymentNow({date:x.date, branch:x.branch}, false)){
    if(!confirm('This is an old entry — only Master can Reject it now.\n\nSend a notification to Master?')) return;
    try{
      let req={id:uid('brief'),date:today(),title:'Reject request — '+(x.name||normMob(x.mobile||'')),
        message:'Wants to Reject an old entry.\nMobile : '+normMob(x.mobile||'')+'\nBranch : '+(x.branch||'')+
                 '\nRequested by : '+(codeName(user&&user.mobile)||''),
        targets:{roles:['master']},branch:x.branch||'',seen:[],replies:[],
        createdBy:(user&&user.mobile)||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
      add('briefings',req);
      try{ cloudUpsertBriefing(req) }catch(_e){}
      toast('Master notified');
    }catch(_e){ toast('Could not send — check connection'); }
    return;
  }
  let rejectRemark='Cancelled by staff (signal 3-tap)';
  wlv1RejectFollowupGroup(x,'Cancelled',rejectRemark,user?.name||user?.mobile||'');
  closeModal();toast('Reject List-এ পাঠানো হলো');followup(x.stage||'Inquiry');
}
