function followBadge(x){if(!x.nextFollow)return '<span class="pill blueP">No Date</span>';let late=dateDaysLate(x.nextFollow);return late?`<span class="pill priorityP">⚡ Priority Call · ${late} Day${late>1?'s':''}</span>`:`<span class="pill yellow">${esc(x.nextFollow)}</span>`}
