window["followActionGuard"]=followActionGuard;
function syncEnquiryCancelFromFollow(x,remark,status='Cancelled'){
 // V450: close every matching enquiry row. A stale duplicate enquiry must not
 // be able to recreate a rejected Follow-up on another device/app install.
 try{
  let enq=load('enquiries'),m=mob(x?.mobile),rid=x?.refId||'',changed=false;
  let terminalStatus=String(status||'Cancelled');
  for(let j=0;j<enq.length;j++){
   let e=enq[j];
   if(!((rid&&e.id===rid)||(m&&mob(e.mobile)===m)))continue;
   let minCalls=Math.max(0,Number(x?.__rejectCallCountMin||0));
   let currentCalls=Number(e.callCount||x?.callCount||0);
   let updRow={...e,status:terminalStatus,stage:terminalStatus,remarks:remark||e.remarks||terminalStatus,
    callCount:Math.max(minCalls,currentCalls),updatedAt:new Date().toISOString(),
    cancelledAt:e.cancelledAt||new Date().toISOString(),cancelledBy:user?.mobile||''};
   enq[j]=updRow; protectNewRow('enquiries',updRow); changed=true;
  }
  if(changed)save('enquiries',enq);
 }catch(e){console.warn('Enquiry cancel sync failed',e)}
}
window["syncEnquiryCancelFromFollow"]=syncEnquiryCancelFromFollow;
// TK-REPORTED (31.07.2026, খাতার সারি B217 — "REJECT লেখা Card যাচাই...
// কেন সেই Card Active Visit List-এ আছে এবং Advance/Test button সক্রিয়")।
// একই মোবাইল ও stage-এর ডুপ্লিকেট `followups` সারি থাকলে, একটাকে Reject
// করলে সঙ্গীটা আগে Active-ই থেকে যেত (তাই তালিকায় থেকে যেত, বোতাম সক্রিয়
// থেকে যেত) — এটা ঠিক ফোনের নেটিভ অ্যাপে ৩০.০৭.২০২৬-এ ধরা পড়া ও ঠিক করা
// একই বাগ (`closeSiblingFollowUps()`, FollowUpRepository.kt), শুধু ওয়েব
// অ্যাপে এতদিন পোর্ট করা হয়নি। এখন হুবহু একই নিয়ম এখানেও।
// ⛔ Design/UI কিছু বদলায়নি — শুধু ডেটার সামঞ্জস্য।
/* 🔴🔴🔒 V448 (TK-নির্দেশ ১৮.০৮.২০২৬: "শুধু Android কেন, ওয়েবেও তো করতে হবে")।
   **আসল কারণ (কোড ধরে যাচাই):** ওয়েবের Delete (`wlv1DeleteDraftEntryImpl` ও
   master-approval `wlv1ApproveDeleteNotice`) শুধু আসল রেকর্ডটাই (enquiries/
   patients) মুছে `deleted_records`-এ তোলে — কিন্তু ওই মোবাইলের `followups`
   সারি **কখনো ছোঁয়াই হতো না**। Android-এ এই cascade আগেই ছিল
   (`TrashHelper.moveToTrashWithFollowupCascade`), কিন্তু ওয়েবে এতদিন
   পোর্টই করা হয়নি — তাই ডিলিট করা নম্বর followups-নির্ভর যেকোনো তালিকায়
   (যেটা বেশিরভাগ তালিকা) Active-ই থেকে যেত, ফিরে-আসার মতো দেখাত।
   **সমাধান:** ডিলিট সফল হওয়ার পরে এই ফাংশন ওই মোবাইলের সব followups সারি
   (যেকোনো stage) 'Cancelled' করে দেয় — Android-এর TrashHelper hide-loop-এর
   ঠিক একই নিয়ম (already Cancelled/Incomplete বাদে)। ⛔ স্থানীয়-প্রথম
   `save()` দিয়েই হয় (এই প্রজেক্টের প্রমাণিত রিট্রাই-সহ পুশ), তাই নেট-বিলম্বেও
   চুপচাপ হারায় না — `queueCloudTableSave`-এর নিজস্ব রিট্রাই এখানে আপনা-আপনি
   কাজ করে। */
function wlv1IsTerminalFollowStatus(status){
  return ['cancelled','incomplete','rejected','closed'].includes(String(status||'').toLowerCase());
}
window["wlv1IsTerminalFollowStatus"]=wlv1IsTerminalFollowStatus;

function wlv1CloseFollowUpsForDeletedMobile(mobile){
  try{
    const d = mob(mobile);
    if (d.length !== 10) return;
    let rows = load('followups');
    let changed = false;
    for (let j = 0; j < rows.length; j++) {
      const r = rows[j];
      if (!r || mob(r.mobile) !== d) continue;
      if (wlv1IsTerminalFollowStatus(r.status)) continue;
      rows[j] = {...r, status: 'Cancelled', updatedAt: new Date().toISOString(),
        history: [...(r.history||[]), {date: today(), time: isoNow(), remark: 'Deleted', staff: user?.name || user?.mobile || ''}]};
      changed = true;
    }
    if (changed) save('followups', rows);
  } catch(_e) {}
}
window["wlv1CloseFollowUpsForDeletedMobile"]=wlv1CloseFollowUpsForDeletedMobile;

function wlv1CloseSiblingFollowUps(mobileRaw, stage, excludeId, status, remark, staffName){
  try {
    const d = mob(mobileRaw);
    if (d.length !== 10) return;
    let rows = load('followups');
    let changed = false;
    for (let j = 0; j < rows.length; j++) {
      const r = rows[j];
      if (!r || r.id === excludeId) continue;
      if (mob(r.mobile) !== d) continue;
      if (r.stage !== stage) continue;
      if (wlv1IsTerminalFollowStatus(r.status)) continue;
      const upd = {...r, status, updatedAt: new Date().toISOString()};
      if (remark) upd.lastRemark = remark;
      if (staffName) upd.history = [...(r.history||[]), {date: today(), time: isoNow(), remark: remark || status, staff: staffName}];
      rows[j] = upd;
      changed = true;
    }
    if (changed) save('followups', rows);
  } catch(_e) {}
}
function wlv1RejectFollowupGroup(source,status='Cancelled',remark='Rejected',staffName=''){
  try{
    if(!source)return false;
    const d=mob(source.mobile),stage=String(source.stage||''),now=new Date().toISOString();
    let rows=load('followups'),changed=false,matched=false;
    for(let j=0;j<rows.length;j++){
      const r=rows[j]; if(!r)continue;
      const sameByMobileStage=(d.length===10&&mob(r.mobile)===d&&String(r.stage||'')===stage);
      const sameById=source.id&&String(r.id)===String(source.id);
      if(!sameByMobileStage&&!sameById)continue;
      matched=true;
      if(wlv1IsTerminalFollowStatus(r.status))continue;
      let hist={date:today(),time:isoNow(),remark:remark||status,staff:staffName||user?.name||user?.mobile||'',nextFollow:'',status:status,decisionVersion:'V450'};
      let updRow={...r,status:status,lastRemark:remark||r.lastRemark||status,nextFollow:'',updatedAt:now,history:[...(r.history||[]),hist]};
      if(Number(source.__rejectCallCountMin||0)>0)updRow.callCount=Math.max(Number(source.__rejectCallCountMin||0),Number(r.callCount||0));
      rows[j]=updRow; protectNewRow('followups',updRow); changed=true;
    }
    if(changed)save('followups',rows);
    if(d.length===10){
      try{syncEnquiryCancelFromFollow(source,remark,status)}catch(_e){}
      if(stage==='Patient'||stage==='Treatment'){
        try{load('patients').filter(p=>mob(p.mobile)===d&&!p.doctorComplete).forEach(p=>{try{upd('patients',p.id,{doctorComplete:true})}catch(_e){}})}catch(_e){}
      }
    }
    try{_invalidateFollowLookupCache()}catch(_e){}
    return matched;
  }catch(_e){return false}
}
window["wlv1RejectFollowupGroup"]=wlv1RejectFollowupGroup;

function updateFollowAction(id,patch,historyItem,redirectStage){let rows=load('followups'),i=rows.findIndex(a=>a.id===id);if(i<0&&String(id||'').startsWith('virtual_')){let eid=String(id).replace(/^virtual_/,'');let e=load('enquiries').find(x=>x.id===eid);if(e){let made=ensureFollow(e,'Inquiry',e.nextFollow||today(),e.remarks||'');rows=load('followups');i=rows.findIndex(a=>a.id===made.id);id=made.id}}if(i<0)return toast('Follow-up not found');let x={...rows[i]},g=followActionGuard(x);if(g==='reject'){let rejectRemark=historyItem?.remark||patch.lastRemark||'Cancelled after 5 calls';x.__rejectCallCountMin=5;wlv1RejectFollowupGroup(x,'Cancelled',rejectRemark,user?.name||user?.mobile||'');closeModal();followup('Inquiry');return}
/* 🔴 B378 (TK-নির্দেশ, 03.08.2026 — B377-এর ধারাবাহিকতা): "৫ বার কল →
   Continue" যদি একই দিনে হয় (lastCallDate===আজ), followActionGuard()
   ততক্ষণে x.callCount=0 বসিয়ে দিয়েছে, আর এই একই-দিনের শাখা সেই ০-কেই
   হুবহু রেখে দিত (নতুন কল-দিন ধরে বৃদ্ধির শাখাটা এড়িয়ে) — তাই সিগন্যাল
   তখনও Nill-ই থেকে যেত। এখন Math.max(1,...) — সক্রিয় Inquiry-এন্ট্রির
   সিগন্যাল কখনো একদম শূন্য দেখাবে না (B215/B377-এর একই নিয়ম মেনে)।
   ⛔ ভিন্ন-দিনের বৃদ্ধির শাখা (Math.min(5,...+1)) অপরিবর্তিত। */
let inc=(x.stage==='Inquiry'?(x.lastCallDate===today()?Math.max(1,Number(x.callCount||0)):Math.min(5,Number(x.callCount||0)+1)):Number(x.callCount||0));rows[i]={...x,...patch,callCount:inc,lastCallDate:today(),updatedAt:new Date().toISOString(),history:[...(x.history||[]),historyItem]};save('followups',rows);closeModal();followup(redirectStage||x.stage)}
window["updateFollowAction"]=updateFollowAction;
function _todayPendingCallCore(tab='Inquiry'){let f=mergeFollow(scoped(load('followups'))).filter(x=>x.nextFollow===today()&&!isConvertedOrClosed(x)).filter(x=>x.stage!=='Inquiry'||isInquiryVisibleRow(x));let stages=['Inquiry','Patient','Treatment'].filter(t=>f.some(x=>x.stage===t));if(!stages.length)return page('Today Pending Call','<div class="card mut">আজ কোনো Pending Call নেই</div>');if(!stages.includes(tab))tab=stages[0];let tabs=stages.map(t=>`<button class="small ${t===tab?'':'ghost'}" onclick="todayPendingCall('${t}')">${stageLabel(t)} (${f.filter(x=>x.stage===t).length})</button>`).join('');let rows=f.filter(x=>x.stage===tab);page('Today Pending Call',`<div class="actions">${tabs}</div><div id="followRows">${rows.map(fuCard).join('')||'<div class="card mut">No records found</div>'}</div>`) }
