        let __allF=v266CleanFollowRows(scoped(load('followups')));
        let __higher = tab==='Inquiry' ? ['Patient','Treatment'] : (tab==='Patient' ? ['Treatment'] : []);
        if(__higher.length){
          let __hm=new Set(__allF.filter(r=>__higher.includes(String(r.stage||''))&&!isConvertedOrClosed(r)).map(r=>mob(r.mobile)));
          rows=rows.filter(r=>!__hm.has(mob(r.mobile)));
        }
        let __seen=new Set(), __dedup=[];
        rows.slice().sort((a,b)=>String(b.recordDate||b.date||'').localeCompare(String(a.recordDate||a.date||''))).forEach(r=>{let m=mob(r.mobile);if(m&&__seen.has(m))return;if(m)__seen.add(m);__dedup.push(r)});
