  +`</div>`;

 /* ---------- ৪টে বোতাম (FollowUpActivity.kt:1951-1990) ---------- */
 let actionsRow=`<div class="anFuActions">`
  +`<button class="callBtn" onclick="contact('${x.mobile}','call');event.stopPropagation();" title="Call">📞</button>`
  +`<button class="waBtn" onclick="contact('${x.mobile}','wa');event.stopPropagation();" title="WhatsApp">💬</button>`
  +`<button class="viewBtn" onclick="viewFollow('${x.id}');event.stopPropagation();" title="View All">👁</button>`
  +`<button class="nextBtn" onclick="nextFollowDate('${x.id}');event.stopPropagation();" title="${nextLabel}">➜</button>`
  +`</div>`;

 return `<div class="card followCard finalFollow anFu ${x.stage}">`
  +`<div class="anFuTop">${left}`
   +`<div class="anFuMain">`
    +`<div class="anFuHead">`
     +`<div class="anFuInfo">`
      +`<div class="anFuNameRow"><span class="anFuSl"></span><b class="anFuName">${esc(display)}</b></div>`
      +`<b class="anFuMobile">📞 ${esc(normMob(x.mobile))}</b>`
      +`<div class="anFuTags"><span class="anFuTag">${esc(String(x.branch||'-').toUpperCase())}</span><span class="anFuSep">|</span><span class="anFuTag">${esc(String(x.disease||'-').toUpperCase())}</span>${wlv1AddrChip}</div>`
      +wlv1IdRow
     +`</div>`
     +(right?`<div class="anFuRight">${right}</div>`:'')
    +`</div>`
   +`</div>`
  +`</div>`
  +remarkBox
  +actionsRow
 +`</div>`;
