function draftCardWeb(x,serial,extraLabel,pickId){
 let display=x.name||normMob(x.mobile);
 let metaParts=[serial+'.'];
 let bd=[x.branch,x.disease].filter(v=>v&&String(v).trim()).map(v=>String(v).toUpperCase());
 if(bd.length) metaParts.push(bd.join(' · '));
 if(x.patientId) metaParts.push('\uD83C\uDD94 '+x.patientId);
 if(extraLabel) metaParts.push(extraLabel);
 let metaLine=metaParts.join('  ·  ');
 let actionsRow=`<div class="followActions anDrActions">`
+`<button class="callBtn" onclick="contact('${x.mobile}','call');event.stopPropagation();" title="Call">📞</button><button class="waBtn" onclick="contact('${x.mobile}','wa');event.stopPropagation();" title="WhatsApp">💬</button><button class="viewBtn" onclick="viewFollow('${x.id}');event.stopPropagation();" title="View All">👁</button></div>`;
 let pickBox = pickId
  ? `<label class="anDrPickLbl" onclick="event.stopPropagation();"><input type="checkbox" ${wlv1DraftPicks.has(String(pickId))?'checked':''} onchange="wlv1DraftTogglePick('${esc(pickId)}',this.checked);event.stopPropagation();" class="anDrPickBox"></label>`
  : '';
 let topAlign = pickId ? 'center' : 'baseline';
 return `<div class="card followCard finalFollow draftCompact anDr ${x.stage||''}"><div class="anDrBody">
<div class="draftTopRow anDrTop anDrTop-${topAlign}">${pickBox}
<b class="anDrMob">📞 ${esc(normMob(x.mobile))}</b>
<b class="anDrName">${esc(display)}</b>
</div>
<div class="draftMetaRow anDrMeta">${esc(metaLine)}</div>
<p class="lastRemarkClick anDrRemark" onclick="openRemarkNote('${x.id}');event.stopPropagation();">${esc(x.lastRemark||'No remark')}</p>
</div><div class="draftActionsWrap">${actionsRow}</div></div>`;
}
