function viewFollow(id){
      let x=frArr('followups').find(a=>a.id===id);
      if(!x&&String(id||'').startsWith('virtual_')){
        let eid=String(id).replace(/^virtual_/,'');
        let e=frArr('enquiries').find(a=>a.id===eid||mob(a.mobile)===mob(eid));
        if(e){ let made=ensureFollow(e,'Inquiry',e.nextFollow||today(),e.remarks||''); x=frArr('followups').find(a=>a.id===made.id); id=made.id; }
      }
      if(!x)return toast('Follow-up not found');let mm=frMobile(x.mobile);let p=frArr('patients').find(a=>a.id===x.patientDbId||a.id===x.refId||frMobile(a.mobile)===mm)||{};let e=frArr('enquiries').find(a=>frMobile(a.mobile)===mm)||{};let pays=frArr('payments').filter(a=>frMobile(a.mobile)===mm||a.patientId===p.id);let med=frArr('medical').filter(a=>a.patientId===p.id||frMobile(a.mobile)===mm);
      let photo=(p.photo||x.photo)?`<img class="summaryPhoto vaPhoto" src="${esc(p.photo||x.photo)}">`:`<div class="summaryPhoto vaPhoto blank">👤</div>`;
      // Icon + accent color per update type, so the timeline is scannable at a glance
      // instead of a wall of identical-looking cards.
      let typeStyle=(type)=>{
        let t=String(type||'').toLowerCase();
        if(t.includes('enquiry'))return {icon:'📞',color:'#1067d8'};
        if(t.includes('registration')||t.includes('visit'))return {icon:'👣',color:'#16a36d'};
        if(t.includes('payment'))return {icon:'💰',color:'#f79009'};
        if(t.includes('medical')||t.includes('prescription')||t.includes('medicine')||t.includes('diet')||t.includes('blood'))return {icon:'🩺',color:'#6941c6'};
        return {icon:'📝',color:'#667085'};
      };
      let timeline=[];
      /* 🔴🔴🔒 V512 (২১.০৮.২০২৬) — Android-এর সাথে মিলিয়ে **Note সংশোধনের পথ**।
         এতদিন এই টাইমলাইনের সারিতে কোন রেকর্ড থেকে লেখাটা এসেছে সেই চিহ্নই
         রাখা হতো না, তাই সংশোধন করার কোনো উপায়ই ছিল না। এখন শুধু দুটো
         চেনার চাবি (`_eid` = কোন Enquiry, `_fid`+`_hidx` = কোন Follow-up-এর
         কত নম্বর রিমার্ক) সঙ্গে রাখা হয়। ⛔ দেখানোর লেখা/ক্রম/গণনা — কিছুই
         বদলায়নি, শুধু দুটো বাড়তি ঘর যোগ হলো। */
      if(e.id)timeline.push({type:'Enquiry',date:e.date||e.createdAt,by:e.receivedBy||e.createdBy,note:e.remarks||'',status:e.status||e.stage,_eid:e.id});
      (x.history||[]).forEach((h,hi)=>timeline.push({type:h.status||'Follow-up',date:h.date,by:h.staff,note:h.remark,next:h.nextFollow,_fid:x.id,_hidx:hi}));
      if(p.id)timeline.push({type:'Registration / Visit',date:p.registrationDate||p.visitDate||p.date,by:p.registeredBy||p.createdBy,note:wlv1RegistrationNote(p),status:'Visit'});
      /* 🔒 খাতার সারি B52 (TK, 28.07.2026 রাত): নম্বর বাড়ে দিন ধরে, সারি ধরে নয়।
         একই দিনে যতবারই টাকা নেওয়া হোক — সব একটাই নম্বরে (Advance / 2nd Payment …)।
         ফোনের অ্যাপেও ঠিক এই একই হিসাব (PatientTimelineRepository), তাই দুই জায়গায়
         এক নম্বরই দেখায়। ⛔ টাকার অঙ্কে হাত পড়ে না। */
      let wlv1PayOrd=(n)=>{n=Number(n||0);if(n<=1)return 'Advance';let m100=n%100,m10=n%10,sfx=(m100>=11&&m100<=13)?'th':(m10===1?'st':m10===2?'nd':m10===3?'rd':'th');return n+sfx+' Payment'};
      let wlv1TreatPays=(pays||[]).filter(z=>{let t=String(z.payType||'treatment').toLowerCase(),r=String(z.remarks||'').toLowerCase();return !(t==='registration'||t==='visit_fee'||t==='visitfee'||t==='attendance_mark'||r.includes('visit fee')||r.includes('registration fee'))});
      let wlv1PayDays=[...new Set(wlv1TreatPays.map(z=>String(z.date||'')).filter(Boolean))].sort();
      pays.forEach(pay=>{let isTreat=wlv1TreatPays.indexOf(pay)>-1,di=wlv1PayDays.indexOf(String(pay.date||''));
        let lbl=(isTreat&&di>-1)?wlv1PayOrd(di+1):(pay.payLabel||pay.paymentLabel||'Payment');
        timeline.push({type:lbl,date:pay.date,by:pay.receivedBy||pay.createdBy,note:money(pay.amount)+' · '+(pay.mode||''),status:'Payment'})});
      med.forEach(m=>timeline.push({type:m.type||'Medical',date:m.date,by:m.createdBy,note:m.details||m.selected||m.decision||'',status:'Medical'}));
      // Most recent update first -- what actually happened LAST is what staff need to
      // see immediately (e.g. "why wasn't treatment started after registration"),
      // not buried at the bottom under everything from months ago.
      timeline.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
      let VA_PAGE=5;
      let visibleRows=timeline.slice(0,VA_PAGE);
      let hiddenRows=timeline.slice(VA_PAGE);
      let rowHtml=(t,i)=>{let ts=typeStyle(t.type);return `<div class="card anTlRow ${(i%2)?'anTlOdd':''}" style="--anTl:${ts.color}">
        <div class="anTlHead">
          <b class="anTlType">${ts.icon} ${esc(t.type||'Update')}</b>
          <small class="anTlDate">${esc(fmtDate(t.date||''))}</small>
        </div>
        <small class="anTlBy">By: ${esc(codeName(t.by||'')||t.by||'-')}${t.next?' · Next: '+esc(fmtDate(t.next)):''}</small>
        ${(t._eid||t._fid)?`<button class="small ghost anTlEditBtn" onclick="wlv1EditTlNote('${esc(t._eid||'')}','${esc(t._fid||'')}',${(t._hidx===undefined||t._hidx===null)?-1:Number(t._hidx)},'${esc(x.id)}');event.stopPropagation();">✏️ Edit</button>`:''}
        ${t.note?(wlv1NoteIsStructured(t.note)?`<p class="anTlNote anTlTap" onclick="${String(t.type||'').toLowerCase().includes('prescription')?'wlv1ShowPrescriptionCards':'wlv1ShowNoteCards'}('${wlv1B64(t.note)}','${esc(fmtDate(t.date||''))}');event.stopPropagation();">${esc(String(t.note).slice(0,58))}${String(t.note).length>58?'…':''} <span class="anTlMore">📄 বিস্তারিত</span></p>`:`<p class="anTlNote">${esc(t.note)}</p>`):''}
      </div>`};
      let visibleHtml=visibleRows.map(rowHtml).join('')||'<div class="card mut">No history</div>';
      let hiddenHtml=hiddenRows.length?`<div id="vaMoreRows" class="hidden">${hiddenRows.map(rowHtml).join('')}</div><button class="small ghost anTlMoreBtn" onclick="document.getElementById('vaMoreRows').classList.remove('hidden');this.remove();">View More (${hiddenRows.length})</button>`:'';
      /* 🖥️🔵 View All Timeline — পপ-আপ থেকে **পূর্ণ পাতা** (TK-অনুমোদিত প্রুফ, ১৫.০৮.২০২৬)।
         Android-এ এটা পূর্ণ পর্দা (`native/PatientTimelineActivity.kt`)। ⛔ **ভিতরের ডিজাইন
         এক অক্ষরও বদলায়নি** — উপরের নীল কার্ড · Recent Updates · প্রতিটা সারির আইকন/রং
         (সারি B568-এ TK-অনুমোদিত) হুবহু আগেরটাই। শুধু (১) পপ-আপের ফ্রেম সরে পাতা হলো,
         (২) ভিতরের `<h2>` বাদ (পাতার নিজের শিরোনাম আছে, নইলে দুবার লেখা উঠত),
         (৩) "Close" → "← Back", যা অ্যাপের নিজের `goBackOnePage()` ডাকে।
         ⛔ "Add Remark" আগের মতোই `openRemarkNote()` খোলে (পাতার উপরে পপ-আপ — সমস্যা নেই)। */
      page('View All Timeline', `<div class="card anTlCard anTlStage-${esc(String(x.stage||'Inquiry'))}"><div class="summaryIdentity anTlIdent">${photo}<div><b class="anTlName">${esc(p.name||x.name||e.name||frNorm(mm))}</b><br><span class="anTlSub">${esc(p.patientId||'')} ${p.patientId?'· ':''}${esc(frNorm(mm))}</span><br><span class="anTlSub">${esc(p.branch||x.branch||e.branch||'')}</span> · <span class="anTlStagePill">${esc(frStageName(x))}</span>${((p.address||x.address||e.address||'').trim())?`<br><span class="anTlSub">📍 ${esc((p.address||x.address||e.address||'').trim())}</span>`:''}</div></div></div><div class="sectionTitle anTlSecTitle">Recent Updates</div>${visibleHtml}${hiddenHtml}<div class="actions"><button onclick="openRemarkNote('${id}')">Add Remark</button></div>`, true);
    }
