/* 🔒 B568 (08.08.2026, TK-অনুমোদিত প্রুফ "সাজ ২ — নীল কার্ড") — টাইমলাইনের জট-পাকানো
   Note একই লেখা ধরে পরিষ্কার নীল-কার্ডে দেখানো হয় (রিমার্ক / স্ট্যাটাস / চেক-আপ /
   পেমেন্ট আলাদা কার্ডে)। ⛔ কোনো সেভ-করা তথ্য বদলায় না — শুধু দেখানোর ধরন। Android-এর
   PatientTimelineActivity-এর একই পার্সিং নিয়মের হুবহু জোড়া (দুই জায়গায় এক রকম)। */
function wlv1NoteParse(txt){
  txt=String(txt||'').trim();
  var blocks=txt.split('|').map(function(s){return s.trim()}).filter(Boolean);
  var remarks=[],status=[],kv=[],pay=null;
  blocks.forEach(function(b){
    if(/^₹\s*[\d,]+/.test(b)){ pay=b; return; }
    if(b.indexOf(':')>-1 && (b.match(/;/g)||[]).length>=1){
      b.split(';').forEach(function(pair){
        pair=pair.trim(); if(!pair)return;
        var ci=pair.indexOf(':');
        if(ci>0){ var k=pair.slice(0,ci).trim(), v=pair.slice(ci+1).trim(); if(v)kv.push([k,v]); else if(k)status.push(k); }
        else status.push(pair);
      });
      return;
    }
    if(/^(Converted|Registered|Advance|Bill|Follow|Visit|Treatment|Refund|Enquiry|Marked|Moved|Inquiry)/i.test(b)){ status.push(b); return; }
    remarks.push(b);
  });
  return {remarks:remarks,status:status,kv:kv,pay:pay};
}
function wlv1NoteCards(txt){
  var d=wlv1NoteParse(txt);
  if(!d.remarks.length&&!d.status.length&&!d.kv.length&&!d.pay) return '<div class="nkCard"><div class="nkNote">'+esc(String(txt||'').trim()||'—')+'</div></div>';
  var h='';
  if(d.remarks.length) h+='<div class="nkCard"><div class="nkT">📌 রিমার্ক</div><div class="nkNote">'+d.remarks.map(esc).join('<br>')+'</div></div>';
  if(d.status.length) h+='<div class="nkCard"><div class="nkT">🧾 স্ট্যাটাস</div><div class="nkChips">'+d.status.map(function(s){return '<span class="nkChip">'+esc(s)+'</span>'}).join('')+'</div></div>';
  if(d.kv.length) h+='<div class="nkCard"><div class="nkT">🩺 ডাক্তার চেক-আপ</div>'+d.kv.map(function(p){return '<div class="nkKv"><span class="nkK">'+esc(p[0])+'</span><span class="nkV">'+esc(p[1])+'</span></div>'}).join('')+'</div>';
  if(d.pay) h+='<div class="nkCard"><div class="nkT">💰 পেমেন্ট</div><div class="nkPay">'+esc(d.pay)+'</div></div>';
  return h;
}
