/* ══════════════════════════════════════════════════════════════════════════
   🔴🔴🔒 V512 (২১.০৮.২০২৬) — **Timeline-এর Note / Remark সংশোধন (ওয়েব)**।
   ফোনের অ্যাপে এই কাজটা `PatientTimelineActivity.editEnquiryHistoryNote()`
   করে; ওখানে সারির উপরে ৩ বার চাপলে খুলত, আর V512-এ Note পপ-আপে একটা
   ✏️ Edit বোতামও বসানো হলো। ওয়েবে সংশোধনের কোনো পথই ছিল না — এখন প্রতিটা
   সংশোধনযোগ্য সারিতে ঐ একই ✏️ Edit।
   ⛔ **হুবহু ফোনের অ্যাপের নিয়ম**: Enquiry সারিতে `remarks` ঘরটা বদলায়;
      Follow-up সারিতে `history[i].remark`, আর সেটা যদি সবার শেষেরটা হয়
      তবেই `lastRemark`-ও। এর বাইরে একটা ঘরও ছোঁয়া হয় না।
   ⛔ Payment · Registration · Medical সারিতে এই বোতাম আসে না (ওদের নিজস্ব
      সম্পাদক আছে) — কারণ ঐ সারিগুলোয় `_eid`/`_fid` বসানোই হয় না।
   ⛔ কোনো সারি মোছা হয় না, কোনো নতুন সারি তৈরি হয় না, ইতিহাসের ক্রম বদলায় না।
   ══════════════════════════════════════════════════════════════════════════ */
function wlv1TlNoteText(eid,fid,hidx){
  try{
    if(eid){ var e=(load('enquiries')||[]).find(function(a){return String(a.id)===String(eid)}); return e?String(e.remarks||''):''; }
    if(fid){ var f=(load('followups')||[]).find(function(a){return String(a.id)===String(fid)}); if(!f)return '';
             var h=(f.history||[])[Number(hidx)]; return h?String(h.remark||''):''; }
  }catch(_e){}
  return '';
}
window["wlv1TlNoteText"]=wlv1TlNoteText;
function wlv1EditTlNote(eid,fid,hidx,backId){
  var cur=wlv1TlNoteText(eid,fid,hidx);
  modal('<h2>\u270F\uFE0F Edit Note</h2><textarea id="wlv1TlNote" class="input" rows="4" oninput="wlv1Caps(this)">'+esc(cur)+'</textarea>'
    +'<div class="actions"><button onclick="wlv1SaveTlNote(\''+esc(eid||'')+'\',\''+esc(fid||'')+'\','+Number(hidx)+',\''+esc(backId||'')+'\')">Save</button>'
    +'<button class="ghost" onclick="closeModal()">Cancel</button></div>');
}
window["wlv1EditTlNote"]=wlv1EditTlNote;
function wlv1SaveTlNote(eid,fid,hidx,backId){
  var el=document.getElementById('wlv1TlNote');
  var text=el?String(el.value||'').trim():'';
  try{
    if(eid){
      /* ⛔ অ্যাপের **নিজস্ব প্রমাণিত** লেখার পথ `upd()` — ওটাই `updatedAt` বসায়,
         `protectNewRow()` ডাকে, তারপর ক্লাউডে পাঠায়। নিজে হাতে `save()` করলে
         `updatedAt` পুরোনোই থেকে যেত, আর `mergeForCloudPush()` (rowStamp তুলনা)
         ক্লাউডের পুরোনো লেখাটাকেই জিতিয়ে দিত — সংশোধন নিঃশব্দে ফিরে যেত। */
      if(!(load('enquiries')||[]).some(function(a){return String(a.id)===String(eid)}))return toast('Enquiry not found');
      upd('enquiries',eid,{remarks:text});
    }else if(fid){
      var f=(load('followups')||[]).find(function(a){return String(a.id)===String(fid)});
      if(!f)return toast('Follow-up not found');
      var hist=(f.history||[]).slice();
      var k=Number(hidx);
      if(!(k>=0&&k<hist.length))return toast('Remark not found');
      hist[k]=Object.assign({},hist[k],{remark:text});
      var patch={history:hist};
      if(k===hist.length-1)patch.lastRemark=text;   /* ফোনের অ্যাপের হুবহু একই শর্ত */
      upd('followups',fid,patch);
    }else{ return toast('Nothing to edit'); }
  }catch(_e){ return toast('Could not save - try again'); }
  closeModal();
  toast('Saved');
  try{ if(backId) viewFollow(backId); }catch(_e){}
}
