function adminPaymentAnalyticsHtml(){
 if(!isMaster())return '';
 let rows=collectionRows().filter(x=>x.date===today());
 let branches=[...new Set((C.branches||[]).map(b=>b.name).concat(rows.map(x=>x.branch).filter(Boolean)))];
 // 🔴 TK-অডিট-অনুরোধ (01.08.2026): collectionRows() Refund বাদ দেয়, approved
 // refund তখনও বিয়োগ হয়নি — ব্রাঞ্চ ধরে ধরে বিয়োগ করা হলো (overview()-এর নিয়ম)।
 let refundByBranch={};
 try{
   load('payments').filter(x=>String(x.date||'').slice(0,10)===today()&&wlv1IsApprovedRefund(x)).forEach(x=>{
     let b=x.branch||'Unknown'; refundByBranch[b]=(refundByBranch[b]||0)+Number(x.amount||0);
   });
 }catch(_e){}
 let cards=branches.map(br=>{let brRows=rows.filter(x=>sameBranch(x.branch,br));let total=brRows.reduce((s,x)=>s+Number(x.amount||0),0)-(refundByBranch[br]||0);if(!total)return '';let visit=brRows.filter(x=>x.source==='Visit Fee').reduce((s,x)=>s+Number(x.amount||0),0);let treat=brRows.filter(x=>x.source==='Treatment Payment').reduce((s,x)=>s+Number(x.amount||0),0);return `<button class="card adminPayBranch" onclick="collectionBranchBreakdown('${esc(br)}')"><b>${esc(br)}</b><strong>${money(total)}</strong><small>Visit ${money(visit)} · Treatment ${money(treat)}</small></button>`}).join('');
 return cards ? `<div class="grid reportGrid adminPayGrid">${cards}</div>` : '';
}
