function collectionBranchBreakdown(br){
  let rows=collectionRows().filter(x=>x.date===today()&&sameBranch(x.branch,br));
  let byStaff={};
  rows.forEach(x=>{
    /* V452: a combined daily Treatment row may contain events taken by different
       staff and by different modes. Attribute each stored event to its real staff;
       legacy rows without events fall back to the old row-level attribution. */
    let evs=(x.source==='Treatment Payment'&&Array.isArray(x.dailyEvents)&&x.dailyEvents.length)?x.dailyEvents:null;
    if(evs){evs.forEach(e=>{let amt=Number(e.amount||0),m=String(e.mode||'CASH').toUpperCase(),k=codeName(e.receivedBy||e.createdBy||'')||'Unknown';byStaff[k]=byStaff[k]||{total:0,visit:0,treat:0,cash:0,online:0,count:0};byStaff[k].total+=amt;byStaff[k].treat+=amt;if(m==='ONLINE'||m==='UPI')byStaff[k].online+=amt;else byStaff[k].cash+=amt;byStaff[k].count++});return}
    let k=codeName(x.receivedBy||x.createdBy||'')||'Unknown',sp=wlv1PaymentSplit(x);byStaff[k]=byStaff[k]||{total:0,visit:0,treat:0,cash:0,online:0,count:0};byStaff[k].total+=Number(x.amount||0);if(x.source==='Visit Fee')byStaff[k].visit+=Number(x.amount||0);if(x.source==='Treatment Payment')byStaff[k].treat+=Number(x.amount||0);byStaff[k].cash+=sp.cash;byStaff[k].online+=sp.online;byStaff[k].count++
  });
  // 🔴 TK-অডিট-অনুরোধ (01.08.2026): এই ব্রাঞ্চের আজকের approved refund, যে
  // স্টাফ নিয়েছিলেন তাঁর total/cash/online থেকে বিয়োগ (visit/treat উপ-ভাগ
  // অপরিবর্তিত রাখা হলো — refund কোন উপ-ভাগ থেকে এসেছে তা নিশ্চিতভাবে জানা যায় না)।
  try{
    load('payments').filter(x=>String(x.date||'').slice(0,10)===today()&&sameBranch(x.branch,br)&&wlv1IsApprovedRefund(x)).forEach(x=>{
      let k=codeName(x.receivedBy||x.createdBy||'')||'Unknown';
      byStaff[k]=byStaff[k]||{total:0,visit:0,treat:0,cash:0,online:0,count:0};
      let amt=Number(x.amount||0);
      byStaff[k].total-=amt;
      if(payMode(x.mode)==='CASH')byStaff[k].cash-=amt; else byStaff[k].online-=amt;
    });
  }catch(_e){}
  let rowsHtml=Object.entries(byStaff).map(([k,v])=>`<div class="card"><b>${esc(k)}</b><br>Total: ${money(v.total)} · Count: ${v.count}<br><small>Visit: ${money(v.visit)} · Treatment: ${money(v.treat)} · Cash: ${money(v.cash)} · Online: ${money(v.online)}</small></div>`).join('');
  page('Branch Collection - '+br,rowsHtml||'<div class="card mut">No records</div>',true)
}
