let wlv1PayDate='';
/* 🔵 B612 parity (10.08.2026): ISO createdAt → "3:42 PM"। Android-এর সাথে এক
   রাখতে raw HH:mm digit পড়া হয় (timezone-বদল নয়) — বেশির ভাগ পেমেন্ট ফোনে
   তৈরি (লোকাল IST digit), তাই দুই অ্যাপেই এক সময় দেখায়। ফাঁকা/ভুল → ""। */
function wlv1Time12(iso){
  if(!iso) return '';
  try{
    var t=String(iso).split('T')[1]; if(!t) return '';
    var hm=t.slice(0,5).split(':'); var h=parseInt(hm[0],10), m=parseInt(hm[1],10);
    if(isNaN(h)||isNaN(m)) return '';
    var ap=h>=12?'PM':'AM'; h=h%12; if(h===0)h=12;
    return h+':'+(m<10?'0'+m:m)+' '+ap;
  }catch(e){ return ''; }
}
