/* WEB APP . branch (and month) pickers for the Master collection lists,
   matching the native CollectionListActivity. */
let wlv1CollBranch = '';   /* 🟢🔒 V398: মনে-রাখা মানের প্রতিচ্ছবি (wlv1BranchGet) */
let wlv1CollMonth  = '';
function wlv1CollPickers(mode){
  let monthPick = '';
  if(mode==='Monthly'){
    const now = new Date(); const opts=[];
    for(let i=0;i<24;i++){
      const d=new Date(now.getFullYear(), now.getMonth()-i, 1);
      const key=d.toISOString().slice(0,7);
      const label=d.toLocaleString('en-US',{month:'long',year:'numeric'}).toUpperCase();
      if(!wlv1CollMonth && i===0) wlv1CollMonth=key;
      opts.push(`<option value="${key}" ${wlv1CollMonth===key?'selected':''}>${label}</option>`);
    }
    monthPick = `<select class="input wlv1CollMonthSel" onchange="wlv1CollMonth=this.value;collectionList('Monthly')">${opts.join('')}</select>`;
  }
  /* 🟢🔒 V398: Android-এর মতো ব্রাঞ্চ-পিল হেডারে; মাস-বাছাই আগের জায়গাতেই। */
  return `<div id="collBranchWrap" class="wlv1HdrPick">${wlv1BranchSelectHtml(`collectionList('${mode}')`,{cls:'wlv1CollBranchSel'})}</div>`
    + (monthPick?`<div class="wlv1CollPick">${monthPick}</div>`:'');
}
window["wlv1CollPickers"]=wlv1CollPickers;
function collectionList(mode='All'){
 let rows=collectionRows();
 // TK-REQUESTED (2026-07-25): Master can narrow any of these lists to one branch.
 // 🟢🔒 V398: ব্রাঞ্চটা এখন মনে রাখা হয় — এক জায়গা থেকে (wlv1BranchGet)।
 wlv1CollBranch=wlv1BranchGet();
 let __collAsk=false, __g=wlv1BranchGate(rows);
 if(__g===null){ __collAsk=true; rows=[]; } else { rows=__g; }
 let title='Collection History';
 if(mode==='Cash'){rows=rows.map(x=>{let sp=wlv1PaymentSplit(x);return {...x,amount:sp.cash,cashAmount:sp.cash,onlineAmount:0,mode:'CASH'}}).filter(x=>Number(x.amount||0)>0);title='Cash Collection'}
 else if(mode==='Online'){rows=rows.map(x=>{let sp=wlv1PaymentSplit(x);return {...x,amount:sp.online,cashAmount:0,onlineAmount:sp.online,mode:'ONLINE'}}).filter(x=>Number(x.amount||0)>0);title='UPI Collection'}
 else if(mode==='Monthly'){
  let ym=wlv1CollMonth||today().slice(0,7);rows=rows.filter(x=>String(x.date||'').slice(0,7)===ym);title='Monthly Collection';
 }else if(mode==='All'){rows=rows.filter(x=>x.date===today());title='Today Collection'}
 rows=rows.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 let total=rows.reduce((sum,x)=>sum+Number(x.amount||0),0);
 // 🔴 TK-অডিট-অনুরোধ (01.08.2026): collectionRows() Refund বাদ দেয়, approved
 // refund তখনও বিয়োগ হত না — উপরের rows-এর হুবহু একই ব্রাঞ্চ/মোড/তারিখ
 // ছাঁকনি refund-এও বসিয়ে total থেকে বিয়োগ করা হলো।
 try{
   let refunds=load('payments').filter(wlv1IsApprovedRefund);
   let __rg=wlv1BranchGate(refunds); refunds=(__rg===null)?[]:__rg;   /* 🟢🔒 V398: rows-এর হুবহু একই ছাঁকনি */
   if(mode==='Cash') refunds=refunds.filter(x=>payMode(x.mode)==='CASH');
   else if(mode==='Online') refunds=refunds.filter(x=>payMode(x.mode)==='UPI');
   else if(mode==='Monthly'){ let ym=wlv1CollMonth||today().slice(0,7); refunds=refunds.filter(x=>String(x.date||'').slice(0,7)===ym); }
   else if(mode==='All') refunds=refunds.filter(x=>x.date===today());
   refunds.forEach(x=>{ total-=Number(x.amount||0); });
 }catch(_e){}
 /* 🔴🔴🆕🔒 V437 #১ (নিজের অডিটে ধরা) — ফোনের Collection তালিকায় উপরে **তিনটে
    ঘর** থাকে (`activity_collection_list.xml:118-200`, `CollectionListActivity.kt:254-259`):
    `💵 Cash` · `📱 Online` · `👥 Patients`; আর সারসংক্ষেপে ব্রাঞ্চের নামও
    (`"N Transactions · ALL BRANCH"`, `:250`)। ওয়েবে এর কিছুই ছিল না।
    ⛔ তিনটে হিসাবই ফোনের হুবহু: CASH = `mode=="CASH"`, Online = বাকি সব,
       Patients = আলাদা মোবাইল-বা-নাম গুনে। ⛔ উপরের `total` ছোঁয়া হয়নি। */
 const __clCash = rows.reduce((a,x)=>a+wlv1PaymentSplit(x).cash,0);
 const __clOnl  = rows.reduce((a,x)=>a+wlv1PaymentSplit(x).online,0);
 const __clPat  = new Set(rows.map(x=>mob(x.mobile)||x.name||x.id).filter(Boolean)).size;
 const __clWhere = (function(){ try{ const v=String(wlv1BranchGet()||''); return (!v||v==='All')?'ALL BRANCH':v.toUpperCase(); }catch(e){ return 'ALL BRANCH'; } })();
 const __clBoxes = `<div class="wlv1PayBoxes wlv1ClBoxes"><div class="wlv1PayBox"><span>💵 Cash</span><b>${money(__clCash)}</b></div><div class="wlv1PayBox"><span>📱 Online</span><b>${money(__clOnl)}</b></div><div class="wlv1PayBox"><span>👥 Patients</span><b>${__clPat}</b></div></div>`;
 let html=wlv1CollPickers(mode)+`<div class="card collectionListSummary"><b>${esc(title)}</b><br><span class="mut">Total: ${money(total)} · ${rows.length} Transactions · ${esc(__clWhere)}</span>${__clBoxes}</div>`+ /* 🔴🔴🆕🔒 V437 #৮ (নিজের অডিটে ধরা) — ফোনের সারিতে (`CollectionAdapter.kt:59-116`)
    নাম + **রোগের চিপ** · সবুজ মোটা `+91 …` · **ID** · `📍 ঠিকানা` · আর টাকার
    নিচে **সময়** থাকে; আর `tvSource` ইচ্ছে করে **লুকানো**
    (`item_collection_row.xml` → `visibility="gone"`)। ওয়েবে উল্টো ছিল: ঠিকানা/
    রোগ/ID/সময় কিছুই ছিল না, অথচ ফোনে লুকানো "source" লাইনটা দেখানো হত।
    ⛔ Payment পর্দার সারিতে (`wlv1ChamberRowHtml`-এর পাশের `payListRow2`) এই
       সবই আগে থেকেই আছে — এখানে সেই একই তথ্যই বসানো হলো, নতুন কিছু নয়।
    ⛔ চাপলে কী হয় (রোগীর ইতিহাস / কল / ডিটেইলস) — এক অক্ষরও বদলায়নি। */
 (rows.map(x=>{
   let nm=String(x.name||'Walk-in').trim();
   let mode=payMode(x.mode);
   let pt=load('patients').find(pp=>mob(pp.mobile)===mob(x.mobile))||{};
   let dis=String(pt.disease||'').trim();
   let disChip=dis?`<span class="payDisChip">${esc(dis.toUpperCase())}</span>`:'';
   let al1=[pt.village,pt.po].filter(Boolean).join(', '),al2=[pt.ps,pt.district,pt.pin].filter(Boolean).join(', ');
   let addrHtml=(al1||al2)?(esc(al1.toUpperCase())+(al2?'<br>'+esc(al2.toUpperCase()):'')):(pt.address?wlv1AddrTwo(String(pt.address).toUpperCase()):'');
   let addrRow=addrHtml?`<div class="payAddr">📍 ${addrHtml}</div>`:'';
   let idc=x.pidCode||pt.patientId||'';
   let tm=wlv1Time12(x.createdAt);
   return `<div class="card payHistoryList" onclick="showCollectionRowDetails('${esc(x.mobile)}')" style="cursor:pointer !important;"><div class="row"><div><div class="payNameRow"><b class="wlv1NameLink" onclick="event.stopPropagation();summaryByMobile('${esc(mob(x.mobile))}')" title="Tap for History">${esc(nm.toUpperCase())}</b>${disChip}</div><div class="payMob2"><span class="wlv1CallLink" onclick="event.stopPropagation();contact('${esc(x.mobile)}','call')" title="Tap to call">${esc(normMob(x.mobile||''))}</span></div>${idc?`<div class="payIdRow2"><span class="payIdTag2">ID</span> ${esc(idc)}</div>`:''}${addrRow}<div class="mut tiny">${esc(fmtDate(x.date||''))}${x.branch?' · '+esc(x.branch):''}</div></div><div class="payAmount"><b>${money(x.amount)}</b><em class="${mode==='UPI'?'online':'cash'}">${esc(mode)}</em>${tm?`<span class="payTime2">${esc(tm)}</span>`:''}</div></div></div>`;
 }).join('')||(__collAsk?wlv1BranchAskCard():'<div class="card mut">No collection found</div>')   /* 🔴 V437 #7 — ফোনের হুবহু লেখা (CollectionListActivity.kt:260) */);
 page(title,html,true);
}
window["collectionList"]=collectionList;

