function ordinalPaymentLabel(n){n=Number(n||1);if(n<=1)return 'Advance';let mod100=n%100,mod10=n%10,suf='th';if(mod100<11||mod100>13){if(mod10===1)suf='st';else if(mod10===2)suf='nd';else if(mod10===3)suf='rd'}return n+suf+' Payment'}
window["ordinalPaymentLabel"]=ordinalPaymentLabel;
/* TK (27.07.2026), "এক রোগী = এক রেকর্ড" ধাপ ২: একটা পেমেন্ট কখনো রোগীর row id-তে (ফোনের অ্যাপ), কখনো মানুষের পড়ার Patient ID কোডে (এই ওয়েব অ্যাপের Chamber পর্দা) জমা হয়। শুধু একটাকে মেলালে অন্যটায় জমা টাকা হারিয়ে যেত। এখন দুটোই মেলে। মোবাইল দিয়ে মেলানো এখানে যোগ করা হয়নি ইচ্ছে করেই — এক পরিবারে এক নম্বর থাকলে অন্যের টাকা ঢুকে যেত। */
/* 🔎 TK-ORDERED CODE AUDIT (27.07.2026): a payment is matched to a patient by the
   patients row id OR the human Patient ID code. That misses money filed under a
   SECOND patients row for the same person (a duplicate registration) -- Paid then
   showed too low and Due too high here, while Patient Details (which also reads by
   mobile) showed the right total. Safe to close now: by TK's locked rule ONE MOBILE
   = ONE REGISTRATION, so a payment carrying this patient's mobile is this patient's
   own. Matching is only WIDENED -- nothing that matched before stops matching, and
   the payment type filter (Visit Fee / marks excluded) is unchanged, so no total can
   be counted twice. Same fix as the phone's Follow-up card. */
function payOwnedBy(x,p){if(!x||!p)return false;const owner=String(x.patientId||'');
  if(owner&&(owner===String(p.id||'')||(!!p.patientId&&owner===String(p.patientId))))return true;
  const pm=mob(p.mobile),xm=mob(x.mobile);
  if(!pm||!xm||pm!==xm)return false;
  /* 🔴🔴🔒 V520 (২২.০৮.২০২৬, TK-অনুমোদিত) — **দুই রোগীর টাকা কখনো মিশবে না।**
     নিচের মোবাইল-fallback বসানো হয়েছিল "এক মোবাইল = এক রোগী" ধরে নিয়ে (পুরোনো
     সারিতে `patientId` না থাকলে টাকা যেন হারিয়ে না যায়)। V516-এর পরে এক
     নম্বরে **সত্যিই দুজন আলাদা রোগী** থাকতে পারেন — তখন এই fallback স্বামীর
     টাকা স্ত্রীর পর্দায় দেখিয়ে দিত। এই একটা ফাংশনই ওয়েবের **১৫টা**
     টাকা-গোনার জায়গার ভিত্তি, তাই এখানেই একবার ঠিক করা হয়েছে।
     ⛔ টাকা হারানো অসম্ভব: প্রতিটা পেমেন্টের সারিতে মালিকের আইডি
        **সবসময়** লেখা হয় (`wlv1BuildTreatmentEventRow` → `patientId:p.id`,
        ফোনেও একই) — তাই উপরের ১ নম্বর শর্তেই সেটা ধরা পড়ে।
     ⛔ যে নম্বরে ঘোষিত আলাদা রোগী নেই, সেখানে দুটো শর্তই false → fallback
        **হুবহু আগের মতোই** চলে (খাতার সারি B30 অটুট)। */
  if(wlv1IsDeclaredSeparateRowId(String(p.id||''),pm))return false;
  if(owner&&wlv1IsDeclaredSeparateRowId(owner,pm))return false;
  return true;}
/* 🔒 খাতার সারি B106 — নম্বর বাড়ে **দিন ধরে**, সেভ ধরে নয় (ফোনের `PaymentRepository.nextLabelFor`-এর হুবহু নকল)।
   TK-এর নিয়ম (খাতার সারি B52): ১ম টাকা = `Advance`, তারপর `2nd Payment` · `3rd Payment` …।
   **একই দিনে যতবারই টাকা নেওয়া হোক নম্বর একটাই থাকবে**; পরের নম্বর তখনই, যখন রোগী আবার নতুন দিনে টাকা দেবেন।
   ⛔ আগে এখানে **সারি গুনে** নম্বর বসত — তাই নেট ধীর থাকলে স্টাফ বুঝতে না পেরে একদিনে ৪ বার সেভ করলে
      `Advance · 2nd · 3rd · 4th` হয়ে যেত। ফোনে এটা ২৮.০৭.২০২৬-এ ঠিক হয়েছিল, কম্পিউটারে হয়নি — এখন দুটো এক।
   ⛔ টাকার অঙ্কে কোনো হাত পড়ে না — শুধু কোন নাম/নম্বর বসবে সেটা ঠিক হয়। */
function nextPaymentLabel(pid,forDate){
 let p=load('patients').find(x=>x.id===pid)||{id:pid};
 let day=String(forDate||today()).slice(0,10);
 let dates=[...new Set(load('payments').filter(x=>payOwnedBy(x,p)&&isTreatmentPaymentRow(x))
   .map(x=>String(x.date||'').slice(0,10)).filter(Boolean))].sort();
 let i=dates.indexOf(day);
 if(i>-1)return ordinalPaymentLabel(i+1);
 return ordinalPaymentLabel(dates.filter(d=>d<day).length+1);
}
window["nextPaymentLabel"]=nextPaymentLabel;
/* 🔒 খাতার সারি B106 — ওই রোগীর নামে **আজ** ইতিমধ্যে কত টাকা নেওয়া হয়ে গেছে
   (ফোনের `PaymentRepository.paidOnDateFor`-এর হুবহু নকল)। ⛔ ক্লাউডে বাড়তি কোনো অনুরোধ নেই। */
function wlv1PaidOnDate(pid,forDate){
 try{
  let p=load('patients').find(x=>x.id===pid)||{id:pid},d=String(forDate||today()).slice(0,10);
  return load('payments').filter(x=>payOwnedBy(x,p)&&isTreatmentPaymentRow(x)&&String(x.date||'').slice(0,10)===d)
    .reduce((s,x)=>s+Number(x.amount||0),0);
 }catch(e){return 0}
}
window["wlv1PaidOnDate"]=wlv1PaidOnDate;
function wlv1PaidToday(pid){return wlv1PaidOnDate(pid,today())}
window["wlv1PaidToday"]=wlv1PaidToday;
/* 🔒 খাতার সারি B106 — একই দিনে দ্বিতীয়বার টাকা নেওয়ার আগে সতর্কবার্তা
   (ফোনের `PaymentDayGuard.confirmIfAlreadyPaidToday`-এর হুবহু নকল, একই লেখা)।
   TK-এর কথা (খাতার সারি B52): *"স্টাফ ভুল করে ৩-৪ বার পেমেন্ট নিয়ে নিয়েছে... হয়তো
   ইন্টারনেট স্লো ছিল, বুঝতে পারেনি যে পেমেন্ট হয়ে গেছে... প্রয়োজনে স্টাফকে ওয়ার্নিং দেবে।"*
   ⛔ এখানে কোনো টাকা সেভ বা বাতিল হয় না — এটা শুধু একটা প্রশ্ন।
   ⛔ আজ কিছু নেওয়া না হয়ে থাকলে কোনো প্রশ্নই আসে না — রোজকার কাজে একটাও বাড়তি চাপ পড়ে না।
   ⛔ অ্যাপের চালু `confirm()`-ই ব্যবহার করা হয়েছে — নতুন কোনো ডিজাইন বসানো হয়নি। */
function wlv1DayGuardOk(pid,name,forDate){
 let day=String(forDate||today()).slice(0,10),paid=Number(wlv1PaidOnDate(pid,day)||0);
 if(paid<=0)return true;
 let who=String(name||'').trim()||'this patient',when=day===today()?'TODAY':fmtDate(day);
 return confirm('₹'+Math.round(paid).toLocaleString('en-IN')+' has already been taken from '+who+' '+when+' ('+nextPaymentLabel(pid,day)+').\n\n'
  +'If the connection was slow, that earlier payment may have saved without you noticing.\n\n'
  +'If this is genuinely NEW money, it will be ADDED to that day’s existing payment. No second payment row will be created; CASH and ONLINE stay separately counted.');
}
window["wlv1DayGuardOk"]=wlv1DayGuardOk;
function paymentDisplayLabel(x,idx){return x.payLabel||x.paymentLabel||ordinalPaymentLabel((idx||0)+1)}
window["paymentDisplayLabel"]=paymentDisplayLabel;
