// 🔒 V217 (§B216, Master Fix Order §14, item 9 "Website Password নিরাপদ
// Migration, বর্তমান Login বন্ধ করা যাবে না"): Android অ্যাপ থেকে login হলে
// PBKDF2 hash `usercredentials.password_hash`-এ বসে (V216 §4)। plaintext
// `password` কলাম **এখনো অছুঁয়ে/coexist** থাকে (TK-এর নিয়ম — চালু Login
// কখনো ভাঙা যাবে না)। এই ফাংশনটা শুধু hash-টা আলাদা করে আনে — hash থাকলে
// login()-এ Web Crypto দিয়ে hash মিলিয়ে দেখা হবে (বেশি নিরাপদ, plaintext
// নেটে/স্ক্রিনে কোথাও তুলনা হয় না); hash না থাকলে **আগের মতোই** plaintext
// তুলনা চলবে — কোনো user-এর Login কখনো বন্ধ হবে না।
async function cloudPasswordHashForMobile(mm){
 try{
  mm=mob(mm); if(!mm)return '';
  let ok=await initCloudClientOnly(); if(!ok||!sb)return '';
  let {data,error}=await sb.from('usercredentials').select('password_hash').eq('mobile',mm).limit(1);
  if(error||!Array.isArray(data)||!data.length)return '';
  return String(data[0]&&data[0].password_hash||'');
 }catch(e){ return ''; }
}
window["cloudPasswordHashForMobile"]=cloudPasswordHashForMobile;
// PBKDF2-HMAC-SHA256 যাচাই — Android-এর PasswordHasher.kt-এর সঙ্গে হুবহু এক
// ফরম্যাট (pbkdf2_sha256$<iterations>$<salt-base64>$<hash-base64>), Web
// Crypto API (SubtleCrypto) দিয়ে ব্রাউজারেই হিসাব হয়, পাসওয়ার্ড কখনো
// প্লেইন-টেক্সটে নেটে যায় না। পুরনো ব্রাউজারে SubtleCrypto না থাকলে বা
// কোনো সমস্যা হলে false ফেরত — login() তখন নিজে থেকেই plaintext-এ ফিরে যায়।
async function pbkdf2VerifyWeb(password, stored){
 try{
  if(!stored || stored.indexOf('pbkdf2_sha256$')!==0) return false;
  if(!window.crypto || !window.crypto.subtle) return false;
  let parts = stored.split('$');
  if(parts.length!==4) return false;
  let iters = parseInt(parts[1],10); if(!iters||iters<1) return false;
  let saltBin = atob(parts[2]);
  let salt = new Uint8Array(saltBin.length);
  for(let i=0;i<saltBin.length;i++) salt[i]=saltBin.charCodeAt(i);
  let expectedB64 = parts[3];
  let enc = new TextEncoder();
  let keyMaterial = await window.crypto.subtle.importKey('raw', enc.encode(password), {name:'PBKDF2'}, false, ['deriveBits']);
  let bits = await window.crypto.subtle.deriveBits({name:'PBKDF2', salt:salt, iterations:iters, hash:'SHA-256'}, keyMaterial, 256);
  let hashArr = new Uint8Array(bits);
  let bin=''; for(let i=0;i<hashArr.length;i++) bin+=String.fromCharCode(hashArr[i]);
  let hashB64 = btoa(bin);
  if(hashB64.length !== expectedB64.length) return false;
  let diff = 0;
  for(let i=0;i<hashB64.length;i++) diff |= hashB64.charCodeAt(i) ^ expectedB64.charCodeAt(i);
  return diff===0;
 }catch(e){ return false; }
}
window["pbkdf2VerifyWeb"]=pbkdf2VerifyWeb;
/* 🔵🔒 V418 (Egress — TK-এর কোটা পেরিয়ে যাওয়ার পর ধরা পড়েছে):
   প্রতিটা ব্যাকআপ সারিতে **গোটা অ্যাপের সব তথ্য** JSON হয়ে বসে থাকে (গড়ে ~৩ MB)।
   আগে Backup Center পর্দাটা খুললেই `select('*')` দিয়ে সবগুলোর ভিতরের তথ্য সহ
   নামত — এক চাপে ৩৩ MB। অথচ পর্দায় দেখানো হয় শুধু তারিখ · নাম · অবস্থা · সাইজ।
   এখন তালিকায় শুধু ওইটুকুই নামে (কয়েক KB)। ভিতরের তথ্য নামে **কেবল তখনই**,
   যখন কেউ Download বা Restore চাপেন — নিচে `wlv1BackupPayload()` দেখুন।
   ⛔ একটাও ব্যাকআপ মোছা হয়নি, কিছুই হারায়নি — শুধু অকারণে নামানো বন্ধ হলো।
   ⛔ mergeById স্প্রেড করে মেলায়, তাই এই ফোনে আগে থেকে থাকা payload মুছে যায় না। */
const WLV1_BAK_LIST_COLS='id,date,reason,status,size,by,at,createdAt,updatedAt';
async function pullBackupRecordsFromCloud(){try{let ok=await initCloudClientOnly();if(!ok||!sb)return false;let r=await sb.from('backuprecords').select(WLV1_BAK_LIST_COLS).order('createdAt',{ascending:false}).limit(30);if(r&&r.error){r=await sb.from('backuprecords').select('id,date,reason,status,size,createdAt,updatedAt').order('createdAt',{ascending:false}).limit(30);}let data=r&&r.data;if(!Array.isArray(data))return false;let rows=mergeById(normalizeCloudRows(data),backupRows()).slice(0,30);saveBackupRows(rows);return true}catch(e){return false}}
window["pullBackupRecordsFromCloud"]=pullBackupRecordsFromCloud;
/* একটা ব্যাকআপের ভিতরের তথ্য — এই যন্ত্রে থাকলে সেটাই, নইলে ক্লাউড থেকে ওই
   একটামাত্র সারি। ⛔ না পেলে সৎভাবে খালি ফেরে, আন্দাজে কিছু বানায় না। */
async function wlv1BackupPayload(id){
  try{
    let local=backupRows().find(x=>x.id===id);
    if(local&&local.payload) return String(local.payload);
    let ok=await initCloudClientOnly(); if(!ok||!sb) return '';
    let r=await sb.from('backuprecords').select('payload').eq('id',id).limit(1);
    if(r&&r.error) return '';
    let p=(r&&Array.isArray(r.data)&&r.data[0])?r.data[0].payload:'';
    if(p&&typeof p!=='string'){ try{ p=JSON.stringify(p); }catch(e){ p=''; } }
    return String(p||'');
  }catch(e){ return ''; }
}
window["wlv1BackupPayload"]=wlv1BackupPayload;
