function saveDoctorCall(id){
 let x=load('doctor_visits').find(a=>a.id===id);if(!x)return;
 if(isOtherBranchRecord(x)&&!confirm('This Doctor belongs to '+(x.branch||'other')+' Branch. Please take approval from that Branch Staff or Master Admin before proceeding. Continue?'))return;
 let note=($('#callRemark')?.value||'').trim(),next=$('#callNext')?.value||doctorDefaultNextDate(),expected=$('#callExpected')?.value||'';
 if(!note)return toast('Remarks mandatory');
 if(next<today())return toast('Past date not allowed');
 let hist=Array.isArray(x.callHistory)?x.callHistory:[];hist.unshift({date:today(),note,nextCallDate:next,by:user?.mobile||'',createdAt:new Date().toISOString()});
 upd('doctor_visits',id,{lastCallDate:today(),nextCallDate:next,expectedPatientDate:expected,callStatus:'Called',remarks:note,callHistory:hist,updatedAt:new Date().toISOString()});
 toast('Doctor call updated');closeModal();doctorVisit('pending')
}
