// "🩹 Fix Last Note"-এর ওয়েব-সংস্করণ। শুধু সবচেয়ে নতুন (index 0, কারণ
// saveDoctorCall()-ও unshift করে) call-history এন্ট্রির note-টাই বদলায় —
// callCount/lastCallDate/nextCallDate/callStatus/expectedDate কিছুই ছোঁয়া
// হয় না, নতুন এন্ট্রিও যোগ হয় না। ফোনের `editLastCallNote()`-এর হুবহু
// একই নিয়ম: callHistory[0].note ঠিক করার সাথে সাথে doctor_visits.remarks
// (কার্ডে যা দেখা যায়) ও একই টেক্সটে বসানো হয়।
function editLastCallNote(id){
  let x=load('doctor_visits').find(a=>a.id===id);if(!x)return;
  let hist=Array.isArray(x.callHistory)?x.callHistory:[];
  if(!hist.length)return toast('No call entry yet to fix');
  let cur=hist[0]||{};
  modal(`<h2>Fix Last Note</h2><div class="card"><b>${esc(x.name||'-')}</b><br>${esc(normMob(x.mobile||''))}<label>Note</label><textarea id="fixNoteText">${esc(cur.note||'')}</textarea><div class="actions"><button onclick="saveFixedLastNote('${id}')">Save</button><button class="ghost" onclick="closeModal()">Cancel</button></div></div>`);
}
window["editLastCallNote"]=editLastCallNote;
function saveFixedLastNote(id){
  let x=load('doctor_visits').find(a=>a.id===id);if(!x)return;
  let hist=Array.isArray(x.callHistory)?x.callHistory:[];
  if(!hist.length)return toast('No call entry yet to fix');
  let text=($('#fixNoteText')?.value||'').trim();
  if(!text)return toast('Note required');
  let newHist=hist.map((h,i)=>i===0?{...h,note:text}:h);
  upd('doctor_visits',id,{callHistory:newHist,remarks:text,updatedAt:new Date().toISOString()});
  toast('Last note fixed');closeModal();viewDoctorVisit(id);
}
window["saveFixedLastNote"]=saveFixedLastNote;
