/* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬: "সব কিছু Android এর মত হোক") — নাম-ছাড়া
   (walk-in) প্রেসক্রিপশন ও Medicine Slip-এর **ছাপা কাগজটা ওয়েবে সম্পূর্ণ আলাদা**
   ছিল: মাত্র ৩টে ঘর (Medicine Name · Dose/Advice · Duration), ℞ চিহ্ন নেই,
   ADVICE নেই, Next Follow-up নেই। ফোনে ওটা রোগীর কাগজের **হুবহু একই**
   (PrintCenterActivity.kt:1000-1006 → একই rx_print.html)।
   এখন ওয়েবেও রোগীর কাগজের সেই একই ৫-ঘরের গঠন — SL · Medicine Name · Dose ·
   When · Duration, বাঁয়ে ℞ ঘর, ADVICE ও Next Follow-up Date।
   ⛔ কোন ওষুধ কী ডোজ — কিছুই বদলায়নি, শুধু কাগজের সাজ ফোনের মতো হলো। */
function printDirectRx(type){
  if(!medDraft.length)addRxItem();
  let p=directPatientFromForm();
  let title=type==='prescription'?'PRESCRIPTION':'MEDICINE SLIP';
  medDraft.forEach(x=>rememberRxDefault(x.name,x.medicineType,x.dose,x.days,x.whenText));
  let list=medDraft.length?medDraft.map((m,i)=>{
    let dw=(m&&m.whenText&&String(m.whenText).trim())?{dose:String(m.dose||'').trim(),whenText:String(m.whenText).trim()}:splitRxDoseWhen(combinedRxDose(m)||m.dose);
    return `<tr><td>${i+1}</td><td><span class="rxPrintType">${esc(m.medicineType||'')}</span>${esc(m.name)}</td><td>${esc(dw.dose)}</td><td>${esc(dw.whenText)}</td><td>${esc(rxDaysForPrint(m.days))}</td></tr>`;
  }).join(''):'<tr><td colspan="5">No item selected</td></tr>';
  closeModal();
  professionalDirectMedicalPrint(p,title,`<div class="rxApprovedGrid" style="--clinic-watermark:url('${branchPrintLogoPath(p)}')"><aside class="rxComplaintHistory"><div class="anRxBot"><div class="rxPrintAdvice"><span><b>ADVICE:</b> Sitz Bath &mdash; 2 Times Daily</span></div><div class="anRxNext"><b>Next Follow-up Date</b><span>_______________</span></div></div></aside><section><div class="rxGridMark">&#8478;</div><table class="printTable finalPrintTable"><tr><th>SL</th><th>Medicine Name</th><th>Dose</th><th>When</th><th>Duration</th></tr>${list}</table></section></div>`);
}
