/* WEB APP . Prescription / Medicine Slip extra buttons, same as the native
   screen: Save & Print and Share as Text (the native screen has Save,
   Save & Print and Share as Text). */
function wlv1RxShare(id, type){
  const p = patientById(id) || {};
  const rows = (typeof medDraft!=='undefined' && medDraft) ? medDraft : [];
  if(!rows.length) return toast('No medicine added yet');
  const lines = rows.map((m,i)=>{
    const name = m.name||m.med||m.medicine||'';
    const dose = m.dose||'';
    const days = m.days||m.duration||'';
    const medType=m.medicineType||m.type||'';
    return (i+1)+'. '+(medType?(medType+' '):'')+name + (dose?(' — '+dose):'') + (days?(' — '+days+' days'):'');
  }).join('\n');
  const txt = String(type).toUpperCase()+'\n'+String(p.name||'').toUpperCase()+' \u00b7 '+shownMob(p.mobile||'')+'\n\n'+lines;
  try{
    if(navigator.share){ navigator.share({text:txt}); return; }
    navigator.clipboard.writeText(txt);
    toast('Copied \u2014 paste it in WhatsApp');
  }catch(e){ toast('Could not share on this browser'); }
}
window["wlv1RxShare"]=wlv1RxShare;
function wlv1RxSavePrint(id, type, printTitle){
  const rows = (typeof medDraft!=='undefined' && medDraft) ? medDraft : [];
  if(!rows.length) return toast('No medicine added yet');
  // NOTE (checked, not assumed): printSimple() builds the paper from what is on
  // screen and then closes the popup, so it must run BEFORE saveRx().
  try{ printSimple(id, printTitle); }catch(e){}
  try{ saveRx(id, type); }catch(e){}
}
