function rxOptionsCard(id){let o=rxOptions(id),tick=(k,l)=>`<label><input class="rxHistoryField" type="checkbox" value="${k}" ${o.fields.includes(k)?'checked':''}> ${l}</label>`;return `<div class="rxCompactOptions"><label class="rxSitzFixed"><input type="checkbox" checked disabled> Sitz Bath — 2 Times</label><span class="rxDietLbl">Diet</span><input id="rxDietOptional" class="input" value="${esc(o.diet||'')}" placeholder="Optional"><div class="rxHistoryChecks">${RX_HISTORY_SCREEN.map(x=>tick(x[0],x[1])).join('')}</div><button type="button" class="ghost rxMoreBtn" onclick="rxMoreInformation()">+&nbsp; Choose More Information</button><div id="rxMoreFields" class="rxHistoryChecks hidden">${RX_MORE_FIELDS.map(x=>tick(x[0],x[1])).join('')}</div></div>`}
function rxCommonPrescription(id){medDraft=RX_FIXED_COMMON.map(x=>Object.assign({},x));rxSaveOptions(id);medDraft.forEach(x=>rememberRxDefault(x.name,x.medicineType,combinedRxDose(x),x.days));printSimple(id,'PRESCRIPTION');saveMedicalRecord(id,'Prescription',medDraft.map(x=>x.name).join(', '),medDraft.map(x=>`${x.medicineType} ${x.name} — ${combinedRxDose(x)} — ${rxDaysForPrint(x.days)}`).join(' | '))}
window["rxMoreInformation"]=rxMoreInformation;window["rxCommonPrescription"]=rxCommonPrescription;
/* 🖥️🔵 B666 (১৫.০৮.২০২৬, TK-অনুমোদিত): Prescription ও Medicine Slip — পপ-আপ থেকে
   **পূর্ণ পাতা**। Android-এ দুটোই পূর্ণ পর্দা (`clinical/PrescriptionActivity.kt` ও
   `clinical/MedicineSlipActivity.kt`)। দুটো পর্দাই এই একটাই বডি ব্যবহার করে, তাই
   এখানে একবার ঠিক করলেই দুটোই ঠিক হয়।
   ⛔ ভিতরের কিচ্ছু বদলায়নি — শুধু ভিতরের `<h2>` বাদ, কারণ পাতার নিজের শিরোনামেই
      ওই একই লেখা বসে (নইলে একই নাম দুবার উঠত)। */
function rxModalBody(id,type,list,printTitle){let p=patientById(id),isRx=String(type)==='Prescription';return `${patientDetailsPanel(p)}${isRx?rxOptionsCard(id):''}${isRx?`<button type="button" class="rxCommonBtn" onclick="rxCommonPrescription('${id}')">⭐ Common</button>`:''}<label>Medicine</label>${medCheckList(list)}${customMedBox()}<div class="actions"><button onclick="addRxItem()">➕ Add Medicine</button><button class="ghost" onclick="${isRx?`rxSaveOptions('${id}');`:''}saveRx('${id}','${esc(type)}')">Save</button><button onclick="${isRx?`rxSaveOptions('${id}');`:''}wlv1RxSavePrint('${id}','${esc(type)}','${esc(printTitle)}')">Save &amp; Print</button><button class="ghost" onclick="wlv1RxShare('${id}','${esc(type)}')">Share as Text</button></div><div id="rxList" class="card mut">No medicine added yet</div>`}
window["rxModalBody"]=rxModalBody;
function prescription(id){let p=patientById(id);if(!p)return toast('Patient not found');rxDefaultsRefreshFromCloud(false,false);medDraft=[];page('Prescription',rxModalBody(id,'Prescription',AYURVEDIC_MEDICINES,'PRESCRIPTION'))}
window["prescription"]=prescription;
function patientDetailsPanel(p){
 if(!p)return '';
 let photoHtml=(p.photo)?`<img class="rxPatientPhoto" src="${esc(p.photo)}">`:`<div class="rxPatientPhoto blank">👤</div>`;
 let field=(label,value)=>`<div class="pdpField"><small>${esc(label)}</small><b>${esc(value||'-')}</b></div>`;
 return `<div class="patientDetailsPanel">
   ${photoHtml}
   <div class="pdpBody">
     <div class="pdpName">${esc(p.name||'-')}</div>
     <div class="pdpGrid">
       ${field('Age',p.age)}
       ${field('Mobile',normMob(p.mobile||''))}
       ${field('First Visit',fmtDate(p.registrationDate||p.visitDate||p.date||'-'))}
       ${field('Disease',p.disease)}
       ${field('Branch',p.branch)}
     </div>
     <div class="pdpAddress">${field('Address',p.address)}</div>
   </div>
 </div>`;
}
