function clearRxPick(){try{$$('.rxChk:checked').forEach(x=>x.checked=false);let m=$('#rxMed');if(m)m.value='';let t=$('#rxType');if(t)t.value='';let d=$('#rxDose');if(d)d.value='As advised';let days=$('#rxDays');if(days)days.value='5'}catch(e){}}
window["clearRxPick"]=clearRxPick;
function renderRxList(){let el=$('#rxList');if(!el)return;el.className='card rxSelectedList';el.innerHTML=medDraft.length?medDraft.map((x,i)=>`<div class="rxSelectedRow"><div><b>${i+1}. <span class="rxTypeBadge">${esc(x.medicineType||'')}</span> ${esc(x.name)}</b><br><small>${esc(x.dose)} · ${esc(rxDaysForPrint(x.days))}</small></div><div class="rxMiniActions"><button class="small ghost" onclick="editRxItem(${i})">Edit</button><button class="small ghost" onclick="deleteRxItem(${i})">Delete</button></div></div>`).join(''):'<div class="mut">No medicine selected</div>'}
window["renderRxList"]=renderRxList;
function addRxItem(){let checked=$$('.rxChk:checked').map(x=>x.value),custom=($('#rxMed')?.value||'').trim(),customType=($('#rxType')?.value||'').trim(),manualDose=($('#rxDose')?.value||'').trim(),days=($('#rxDays')?.value||'5').trim()||'5';let names=[...checked];if(custom)names.push(custom);names=[...new Set(names.filter(Boolean))];if(!names.length)return toast('Select or type medicine');let missing=names.filter(name=>{if(custom&&name===custom)return !customType;let inp=$$('.rxTypeInput').find(x=>x.getAttribute&&x.getAttribute('data-med')===name);return !(inp?.value||rxTypeFor(name))});if(missing.length)return toast('Please set Type for: '+missing.join(', '));names.forEach(name=>{
  // FIX: read this medicine's OWN edited dose input (data-med) if the user changed it,
  // instead of always falling back to the shared #rxDose field (which only worked
  // correctly when exactly one medicine was selected at a time).
  let ownDoseInput=$$('.rxDoseInput').find(inp=>inp.getAttribute&&inp.getAttribute('data-med')===name);
  let dose=ownDoseInput&&ownDoseInput.value&&ownDoseInput.value.trim()?ownDoseInput.value.trim():rxDoseFor(name);
  if(custom&&name===custom&&manualDose&&manualDose!=='As advised')dose=manualDose;
  /* 🔴 V425 (TK-নির্দেশ ১৭.০৮.২০২৬: "When এর যায়গা টা নেই কেন") — ফোনের
     MedicinePickerDialog-এর মতোই এই সারির নিজের When ঘরটা পড়া হয়। ঘরটা ফাঁকা
     থাকলে আগের নিয়মই চলে (ডোজের লেখা থেকে ভাগ) — কিছুই বদলায় না। */
  let ownWhenInput=$$('.rxWhenInput').find(inp=>inp.getAttribute&&inp.getAttribute('data-med')===name);
  let whenText=(ownWhenInput&&ownWhenInput.value)?ownWhenInput.value.trim():'';
  /* 🔴 V425 (TK-নির্দেশ: "এখানে Days কোথায় গেলো") — ফোনের মতোই এই সারির নিজের
     Days ঘরটা পড়া হয়। ঘরটা ফাঁকা থাকলে আগের নিয়মেই নিচের শেয়ার্ড "Duration
     Days" ঘরটা ধরা হয় — তাই পুরনো কোনো পথ ভাঙে না। */
  let ownDaysInput=$$('.rxDaysInput').find(inp=>inp.getAttribute&&inp.getAttribute('data-med')===name);
  let rowDays=(ownDaysInput&&ownDaysInput.value&&ownDaysInput.value.trim())?rxCleanDays(ownDaysInput.value):days;
  let type=(custom&&name===custom)?customType:(($$('.rxTypeInput').find(x=>x.getAttribute&&x.getAttribute('data-med')===name)?.value)||rxTypeFor(name));
  rememberRxDose(name,dose);rememberRxDefault(name,type,dose,rowDays,whenText);
  let existing=medDraft.findIndex(x=>String(x.name).toLowerCase()===String(name).toLowerCase());let row={name,medicineType:type,dose,whenText,days:rowDays};if(existing>-1)medDraft[existing]=row;else medDraft.push(row)});clearRxPick();renderRxList()}
window["addRxItem"]=addRxItem;
function editRxItem(i){let x=medDraft[i];if(!x)return;let m=$('#rxMed'),t=$('#rxType'),d=$('#rxDose'),days=$('#rxDays');if(m)m.value=x.name;if(t)t.value=x.medicineType||'';if(d)d.value=x.dose;if(days)days.value=x.days;medDraft.splice(i,1);renderRxList()}
window["editRxItem"]=editRxItem;
function deleteRxItem(i){medDraft.splice(i,1);renderRxList()}
