function wlv1InvDlgToggle(cb){
  const label=cb.closest('[data-wlv1invdlg]'); if(!label)return;
  const name=label.getAttribute('data-wlv1invdlg')||'';
  if(!name)return;
  if(cb.checked){window.__wlv1InvDlgChecked.add(name);label.classList.add('on');}
  else{window.__wlv1InvDlgChecked.delete(name);label.classList.remove('on');}
}
