+'.gold li b{color:#8A6116;position:absolute;left:0}.gold li i{font-style:normal;color:#54615A}'
+'.warn{margin-top:1.6mm;border:.9px solid #F0B7B0;background:#FDECEA;border-radius:1.8mm;padding:1.2mm 3mm;font-size:7.3pt;color:#8E2A1E;line-height:1.25}'+'.warn.rem{border-color:#C7D3CB;background:#F7FAF8;color:#15231C}'
+'.sign{margin-top:1.6mm;display:grid;grid-template-columns:1fr auto 1fr;align-items:end;gap:6mm}'
