/* V267 SELECTIVE FINAL RULE STABILIZATION
   Scope: final locked rules only. No print layout/patient ID/public design changes. */
(function(){
  try{
    // Global date display final lock: DD/MM/YYYY.


    // Next follow-up is optional everywhere; blank is allowed, past date blocked when provided.


    // Patient by follow-up robust link repair.
    function v267PatientByFollow(x){
      if(!x)return null;
      let mm=mob(x.mobile);
      let c=_getFollowLookupCache();
      let found=(x.patientDbId&&c.patientsById.get(x.patientDbId))||(x.refId&&c.patientsById.get(x.refId))||(x.convertedPatientId&&c.patientsById.get(x.convertedPatientId))||(x.patientId&&c.patientsById.get(x.patientId))||(mm&&c.patientsByMobile.get(mm))||null;
      // Rare legacy case: a patient record whose own .patientId field (not .id)
      // matches this follow-up row's .patientId. Not worth indexing for every
      // render since it's uncommon; fall back to a direct scan only when the
      // fast lookups above found nothing, so this stays just as correct as
      // before without slowing down the common case.
      if(!found && x.patientId) found = c.patients.find(p=>p.patientId===x.patientId)||null;
      return found;
    }
window["v267PatientByFollow"]=v267PatientByFollow;

    // Enquiry form final lock: next follow-up optional and no mandatory star.
    let oldEnquiryForm=window.enquiryForm||enquiryForm;
    window.enquiryForm=function(){
      oldEnquiryForm();
      setTimeout(()=>{
        try{
          let n=$('#eNext'); if(n){n.removeAttribute('required'); n.value=''; n.min=today();}
          document.querySelectorAll('.enqLabel').forEach(l=>{if((l.textContent||'').includes('Next Follow-up'))l.innerHTML=l.innerHTML.replace(/<span class="req">\*<\/span>/g,'').replace(/\s*\(\)/g,'')});
        }catch(e){}
      },30);
    };

    // Registration fee final lock: mandatory amount, separate from treatment payment.
    let oldSavePatient=window.savePatient||savePatient;
    window.savePatient=async function(evt){
      let raw=String($('#regFee')?.value||'').trim(), fee=Number(raw||0);
      if(!(fee>0))return toast('Registration Fee mandatory');
      return oldSavePatient(evt);
    };

    // Visit advance robust: if follow-up link exists but patient id is missing, repair using mobile.


    // Follow-up card final display: slash date and print in Patient tab.
    let oldFu=window.fuCard||fuCard;
    window.fuCard=function(x){
      let p=v267PatientByFollow(x)||{};
      let fixed={...x,patientDbId:p.id||x.patientDbId||'',visitDate:x.visitDate||p.visitDate||p.registrationDate||p.date||x.date||''};
      let html=oldFu(fixed);
      try{
        html=html.replace(/Visit Date:\s*([^<]+)/g,(_,d)=>'Visit Date: '+esc(fmtDate(String(d||'').trim())));
        html=html.replace(/⏰\s*(\d{4}-\d{2}-\d{2})/g,(_,d)=>'⏰ '+fmtDate(d));
        html=html.replace(/➜\s*Next Follow-up/g,'Next Follow-up').replace(/➜\s*Next Call/g,'Next Call');
        let pid=p.id||fixed.patientDbId||'';
        if(String(fixed.stage||'')==='Treatment' && pid && !html.includes('openPrintMenu')){
          html=html.replace('</div></div></div>',`<button class="small ghost" onclick="openPrintMenu('${esc(pid)}');event.stopPropagation();">Print</button></div></div></div>`)
        }
      }catch(e){}
      return html;
    };

    // Default password fallback stable.

  }catch(e){console.warn('V267 stabilization skipped',e)}
})();

