    function frNorm(v){try{return normMob(v)}catch(e){return frMobile(v)}}
window["frNorm"]=frNorm;
    function frIsActiveEnq(x){let st=String(x?.status||'').toLowerCase(), sg=String(x?.stage||'').toLowerCase();return !(st.includes('registered')||st.includes('closed')||st.includes('cancel')||st.includes('reject')||sg.includes('registered')||sg.includes('closed')||x?.convertedPatientId)}
window["frIsActiveEnq"]=frIsActiveEnq;
    function frStageName(x){let s=String(x?.stage||x?.status||'').toLowerCase(); if(s==='inquiry'||s==='enquiry')return 'Enquiry'; if(s==='patient'||s==='visit'||s==='doctor queue')return 'Visit'; if(s==='treatment'||s.includes('treatment'))return 'Patient'; if(x?.kind)return x.kind; return x?.stage||x?.status||'-'}
window["frStageName"]=frStageName;
    function frAllRecordsByMobile(mm){mm=frMobile(mm);let out=[];frArr('enquiries').forEach(x=>{if(frMobile(x.mobile)===mm)out.push({...x,kind:'Enquiry'})});frArr('followups').forEach(x=>{if(frMobile(x.mobile)===mm)out.push({...x,kind:frStageName(x)})});frArr('patients').forEach(x=>{if(frMobile(x.mobile)===mm)out.push({...x,kind:frStageName(x)||'Patient'})});return out}
window["frAllRecordsByMobile"]=frAllRecordsByMobile;
    window.finalRecordsByMobile=frAllRecordsByMobile;

