      let f=frArr('followups').find(x=>frMobile(x.mobile)===mm&&String(x.stage||'')==='Inquiry')||{};
      let pref={...e,...f,id:f.id||'',refId:e.id||f.refId||'',mobile:frNorm(mm),name:e.name||f.name||'',branch:e.branch||f.branch||user?.branch||'',address:e.address||f.address||'',disease:e.disease||f.disease||'',remarks:e.remarks||f.lastRemark||''};
      closeModal();
