/* V277 FINAL RULE CANONICAL OVERRIDES - no design/print changes */
/* 🖥️🔵 Follow-up Calendar — পপ-আপ থেকে **পূর্ণ পাতা** (TK-অনুমোদিত প্রুফ, ১৫.০৮.২০২৬,
   "খুব সাবধানে")। Android-এর `activity_follow_calendar.xml` + `FollowCalendarActivity.kt`
   পুরো পড়ে হুবহু মিলিয়ে: ← Back · Branch পিল (শুধু Master) · ◀ Month YYYY ▶ ·
   "📞 Today Pending Call — N" ব্যানার (শুধু আজ থাকলে) · Su–Sa সহ পূর্ণ মাসের গ্রিড ·
   যেদিন কল আছে সেই ঘরে সংখ্যা, আর শুধু সেই ঘরেই চাপা যায় (Android-এর হুবহু নিয়ম)।
   ⛔ **ওয়েবে ক্যালেন্ডারের তিনটে আলাদা পুরনো কোড আছে** (লাইন ~৩২৪৪ · ~৭০৯৪ · ~৭২২৪) —
      কিন্তু আসলে চলে **এই একটাই**, কারণ নিচে ও পরে `window.openRealFollowCalendar` /
      `window.openFollowCalendar` দুটোই এটাকেই বসানো হয় (৭৪৪৭-৭৪৪৮ · ৭৫২২ · ৭৬৭৮)।
      তাই **শুধু এটাই বদলানো হলো**, বাকি দুটোয় এক অক্ষরও হাত পড়েনি (চাপা পড়া কোড
      বদলালে পর্দায় কিছুই বদলাত না — যাচাই করে নিশ্চিত হওয়া গেছে)।
   ⛔ **তথ্য আনার লাইনটা হুবহু আগের** (`mergeFollow(scoped(arr('followups')))` + একই stage
      ফিল্টার + `!isClosed(x)` + তারিখের একই ক্রম) — শুধু মাস ও ব্রাঞ্চের ছাঁকনি যোগ।
   ⛔ ব্রাঞ্চের ছাঁকনি Follow-up পর্দার **হুবহু একই নিয়ম ও একই চলক** (`wlv1FuBranch`,
      লাইন ৩১৮৮/৩১৯৩) — নতুন কোনো নিয়ম বানানো হয়নি।
   ⛔ দিনের ঘরের ডিজাইন **নতুন ক্লাসে** (`wlv1Cal*`) — পুরনো `.calCell`/`.realCalendarGrid`
      ছোঁয়া হয়নি, তাই অন্য কোথাও কিছু ভাঙে না।
   ⛔ দিনে চাপলে আগের মতোই `openFollowCalendarDate(stage, iso)` — ওই তালিকা অপরিবর্তিত।  */
var wlv1CalY=null, wlv1CalM=null, wlv1CalStage='Inquiry';
function wlv1CalMonthName(y,m){try{return new Date(y,m,1).toLocaleString('en',{month:'long'})+' '+y}catch(e){return y+'-'+(m+1)}}
function wlv1CalIso(y,m,d){return y+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0')}
function wlv1CalCounts(){
  var rows=(typeof mergeFollow==='function'?mergeFollow(scoped(arr('followups'))):scoped(arr('followups')))
    .filter(function(x){return String(x.stage||'Inquiry')===String(wlv1CalStage||'Inquiry')&&!isClosed(x)});
  /* 🟢🔒 V398: Follow-up পর্দার হুবহু একই মনে-রাখা ব্রাঞ্চ। বাছা না-থাকলে
     ক্যালেন্ডারে কোনো সংখ্যা দেখাবে না — নিচে "Branch বাছুন" বার্তা আসে। */
  try{ var __cg=wlv1BranchGate(rows); rows=(__cg===null)?[]:__cg; }catch(e){}
  var counts={};
  rows.forEach(function(x){var d=String(x.nextFollow||x.visitDate||x.recordDate||x.date||'').slice(0,10);if(d)counts[d]=(counts[d]||0)+1});
  return counts;
}
