window["wlv1SearchCard"]=wlv1SearchCard;

function wlv1SearchRun(q){
  const box = $('#wlv1SResults'); if(!box) return;
  q = String(q||'').trim();
  if(q.length < 2){ box.innerHTML = '<div class="card mut">Type a name or mobile number to search.</div>'; return; }
  const qd = q.replace(/\D/g,'');
  const isHit = row => {
    const d = mob(row.mobile); if(!d) return false;
    const name = String(row.name||'');
    const hitName = q.length>=2 && name.toLowerCase().includes(q.toLowerCase());
    const hitMob  = qd.length>=3 && d.includes(qd);
    return hitName || hitMob;
  };
  // TK-REQUESTED (2026-07-27), "ছ'টা পর্দা এক নিয়মে" step 1 of 6. Two ways this
  // screen disagreed with the phone:
  //  (1) it pushed Enquiry rows first and then blocked the same number from
  //      being replaced, so a number that is already a registered Patient still
  //      showed the old "Enquiry" card. The phone lets the higher stage win.
  //  (2) with two patients rows for one person (a duplicate registration) it
  //      took whichever row came first, while the payment screen, Patient
  //      Details and the Report Card all use wlv1PickPatientRow. Now Search
  //      uses that same rule: current branch -> row with a real bill -> first.
  // With one row per person (the normal case) results are exactly as before.
  const byMobile = new Map();
  load('enquiries').forEach(r=>{
    if(!isHit(r)) return;
    const d = mob(r.mobile); if(!d || byMobile.has(d)) return;
    byMobile.set(d,{name:String(r.name||''), mobile:d, branch:r.branch||'', stage:'Enquiry'});
  });
  const patRows = new Map();
  load('patients').forEach(r=>{
    if(!isHit(r)) return;
    const d = mob(r.mobile); if(!d) return;
    if(!patRows.has(d)) patRows.set(d,[]);
    patRows.get(d).push(r);
  });
  patRows.forEach((rows,d)=>{
    const p = wlv1PickPatientRow(rows,(typeof user!=='undefined'&&user&&user.branch)||'') || rows[0];
    byMobile.set(d,{name:String(p.name||''), mobile:d, branch:p.branch||'', stage:'Patient'});
  });
  const out = Array.from(byMobile.values());
  box.innerHTML = out.length ? out.map(wlv1SearchCard).join('')
                             : '<div class="card mut">No records found</div>';
}
window["wlv1SearchRun"]=wlv1SearchRun;

function globalSearchScreen(){
  page('Search', `<div class="wlv1Search">
    <input id="wlv1SQuery" class="input" placeholder="Search by name or mobile"
      autocomplete="off" data-nocaps="1" oninput="wlv1SearchRun(this.value)">
    <div id="wlv1SResults"><div class="card mut">Type a name or mobile number to search.</div></div>
  </div>`, true);
  setTimeout(()=>{ const el=$('#wlv1SQuery'); if(el) el.focus(); }, 60);
}
window["globalSearchScreen"]=globalSearchScreen;

/* ============================================================================
   WEB APP . PATIENT TIMELINE table, matched to the native item_timeline row
   (TK's paper "Patient Progress Report" register):
       Visit# | Date | Progress (title + note) | Paid | Due
   Same widths on every row, note in its own line under the title, rupee
   amounts, newest entries at the bottom (a real journey, oldest first).
   ========================================================================== */
/* 🔒 ONE rule for "is this remark the app's own automatic text?" — mirrors the
   phone's PaymentModel.isAutoPaymentRemark (TK-reported 27.07.2026, SADDAM). */
function wlv1IsAutoPayRemark(remark,label){
  const r=String(remark||'').trim();
  if(!r) return true;
  const l=String(label||'').trim();
  if(l&&r.toLowerCase()===l.toLowerCase()) return true;
  const fixed=['advance','advance payment','visit fee','registration fee','treatment payment','marked arrived','marked expected'];
  if(fixed.includes(r.toLowerCase())) return true;
  return /^\d+(st|nd|rd|th)( payment)?$/i.test(r);
}
window["wlv1IsAutoPayRemark"]=wlv1IsAutoPayRemark;
function wlv1TimelineRows(p){
  const m = mob(p.mobile);
  const out = [];
  const d10 = v => String(v||'').slice(0,10);

  const reg = d10(p.registrationDate || p.date);
  if(reg) out.push({date:reg, title:'Registration', note:[p.disease,p.branch].filter(Boolean).join(' · '), paid:0});

  load('followups').filter(f=>mob(f.mobile)===m).forEach(f=>{
    (f.history||[]).forEach(h=>{
      out.push({date:d10(h.date), title:(f.stage||'Follow-up')+' Call',
                note:String(h.remark||''), paid:0});
    });
  });

  /* 🔵🔒 V520: `payOwnedBy` নিজেই এখন মোবাইল-fallback সামলায় ও দুই রোগীর টাকা আলাদা রাখে — তাই এখানকার বাড়তি কাঁচা মোবাইল-মিলটা সরানো হয়েছে (নইলে ওই সুরক্ষা ফাঁকি দিয়ে যেত)। ⛔ এক রোগী হলে ফলাফল অবিকল আগের মতোই, কারণ payOwnedBy ওই ক্ষেত্রে মোবাইল মিললেই true বলে। */
  wlv1MergeDailyTreatmentRows(load('payments').filter(x=>payOwnedBy(x,p))).forEach(x=>{
    const amt = Number(x.amount||0);
    if(!(amt>0)) return;
    /* 🚨 TK-REPORTED, LIVE (27.07.2026, SADDAM — TK's photo): the PROGRESS box was
       being filled with the app's OWN payment text ("Advance Payment — ₹10,000 ·
       CASH · …"), three lines tall, while a visit with nothing written correctly
       showed "—". A payment with no typed remark stores its own label as the
       remark, so that label was being printed as if a person had written it.
       wlv1IsAutoPayRemark() below is the ONE rule for "this is the app's own text",
       matching the phone (PaymentModel.isAutoPaymentRemark). A remark a person
       really typed is never matched, so nothing real can be hidden. The audit line
       an amount-correction appends is cut off too. */
    const rawRem=String(x.remarks||'');
    const lbl=String(x.payLabel||x.paymentLabel||'');
    const typed=wlv1IsAutoPayRemark(rawRem,lbl)?'':rawRem.split('| Audit:')[0].split('Audit:')[0].trim();
    const sp=wlv1PaymentSplit(x),modeText=sp.cash>0&&sp.online>0?'Cash + Online':(sp.online>0?'Online':'Cash');
    out.push({date:d10(x.date), title:collectionPaymentLabel?collectionPaymentLabel(x):'Payment',
              note:[modeText, typed].filter(Boolean).join(' · '),
              typed:typed,
              paid:amt,
              // 🔒 V217 (§B216): দেখানোর জন্য `paid` (আসল, positive, Android-এর
              // paymentAmount-এর মতোই অক্ষত) — হিসাবের জন্য আলাদা signed মান,
              // approved refund-এ ঋণাত্মক, pending/rejected-এ ০।
              payEffect:wlv1PayEffect(x)});
  });

  load('medical').filter(x=>x.patientId===p.id).forEach(x=>{
    out.push({date:d10(x.date), title:String(x.type||'Record'),
              note:String(x.decision||x.selected||x.details||''), paid:0});
  });

  /* ⛔ এই ফাংশনটা **পুরনো→নতুন** ক্রমেই ফেরত দেয় — Report Card ও শেয়ার-লেখা
     এই ক্রম ধরেই চলতি "জমা/বাকি" হিসাব করে, তাই এটা বদলানো যাবে না।
     পর্দায় নতুনটা আগে দেখানোর কাজটা `wlv1TimelineTable()`-এ করা হয়েছে। */
  return out.filter(r=>r.date).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
}
window["wlv1TimelineRows"]=wlv1TimelineRows;

/* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — ফোনের রোগী-পর্দায় ঘটনাগুলো **নতুনটা
   আগে** সাজানো (PatientTimelineRepository.kt:1073 "Newest first"); ওয়েবে
   পুরনোটা আগে ছিল, তাই একই রোগীর পর্দা দুই জায়গায় উল্টো পড়ত।
   ⛔ নম্বর ও "জমা/বাকি"-র চলতি যোগ আগের মতোই **পুরনো→নতুন** ক্রমেই হিসাব
      হয়, শুধু দেখানোটা উল্টে যায় — তাই একটা টাকার অঙ্কও বদলায়নি। */
function wlv1TimelineTable(p,t){
  const asc = wlv1TimelineRows(p);
  if(!asc.length) return '<div class="card mut">No updates yet</div>';
  const bill = Number((t&&t.bill)||0);
  let paidSoFar = 0;
  const numbered = asc.map((r,i)=>{
    paidSoFar += Number(r.payEffect||0);
    return {r:r, no:i+1, due: bill>0 ? Math.max(0, bill - paidSoFar) : 0};
  });
  const rows = numbered.slice().reverse();
  const body = rows.map((__x)=>{
    const r = __x.r, due = __x.due;
    return `<div class="wlv1TlRow">
      <div class="wlv1TlNo">${__x.no}</div>
      <div class="wlv1TlDate">${esc(fmtDate(r.date))}</div>
      <div class="wlv1TlMid"><div class="wlv1TlTitle">${esc(r.title)}</div>
        ${r.note?`<div class="wlv1TlNote">${esc(r.note)}</div>`:''}</div>
      <div class="wlv1TlPaid">${r.paid>0?money(r.paid):''}</div>
      <div class="wlv1TlDue">${(r.paid>0&&bill>0)?money(due):''}</div></div>`;
  }).join('');
  return `<div class="wlv1TlTable">
    <div class="wlv1TlRow wlv1TlHeadRow"><div class="wlv1TlNo">#</div><div class="wlv1TlDate">Date</div>
      <div class="wlv1TlMid">Progress</div><div class="wlv1TlPaid">Paid</div><div class="wlv1TlDue">Due</div></div>
    ${body}</div>`;
}
window["wlv1TimelineTable"]=wlv1TimelineTable;

/* ============================================================================
   WEB APP . REPORT CARD, matched to the native ReportCardActivity (TK's paper
   "Patient Progress Report"):
     . NAME in capitals, then AGE / ID / MOB on the left and
       DATE / SEX / DISEASE / ADDRESS on the right
     . three totals boxes: TOTAL BILL (blue), PAID (green), DUE (red)
     . table: VISIT | DATE | PROGRESS | PAID
     . Print button (the browser's own print, which is how printing works here)
   ========================================================================== */
function wlv1ReportCard(idOrMobile){
  const list = load('patients');
  /* 🔵🔒 V522 (২২.০৮.২০২৬): আইডি দিয়ে পাওয়া গেলে সেটাই — সব ডাকার জায়গা
     `p.id`-ই পাঠায়, তাই রোজকার পথে কিছুই বদলায় না। শুধু পুরোনো মোবাইল-ভিত্তিক
     fallback-টা এখন **নয়টা পর্দার সেই একই নিয়ম** (`wlv1PickPatientRow`, V143)
     মানে — আগে সে তালিকার **প্রথম** সারিটা তুলে নিত, তাই এক নম্বরে দুজন
     রোগী থাকলে ফোন ও কম্পিউটার আলাদা রোগী দেখাতে পারত।
     ⛔ এক রোগী হলে ফলাফল অবিকল আগের মতোই · কোনো নতুন পড়া নেই। */
  const p = list.find(x=>x.id===idOrMobile)
    || wlv1PickPatientRow(list.filter(x=>mob(x.mobile)===mob(idOrMobile)),
                          (typeof user!=='undefined'&&user&&user.branch)||'');
  if(!p) return page('Report Card','<div class="card redP">Patient not found</div>');
  if(typeof searchCanSee==='function' && !searchCanSee(p))
    return page('Report Card','<div class="card redP">This patient is outside your branch access.</div>');

  const t = treatmentTotals(p);
  const rows = wlv1TimelineRows(p);
  const addr = [p.village,p.po,p.ps,p.district,p.pin,p.address].filter(Boolean).join(', ');
  const line = (k,v)=>`<div class="wlv1RcLine"><small>${k}</small><b>${esc(v||'—')}</b></div>`;
  /* TK-REQUESTED (2026-07-26): the native Report Card table is
     VISIT . DATE . PROGRESS . PAID . DUE . the web was missing the DUE
     column, so the running balance TK reads out to the patient was not
     visible here. Same running calculation the native uses. */
  let n = 0, paidSoFar = 0;
  const rcBill = Number(t.bill||0);
  const body = rows.map(r=>{
    n++;
    paidSoFar += Number(r.payEffect||0);
    const due = rcBill>0 ? Math.max(0, rcBill - paidSoFar) : 0;
    return `<div class="wlv1RcRow"><div class="wlv1RcVisit">${n}</div>
      <div class="wlv1RcDate">${esc(fmtDate(r.date))}</div>
      <div class="wlv1RcProg"><b>${esc(r.title)}</b>${r.typed?`<span>${esc(wlv1PrintEn(r.typed))}</span>`:''}</div>
      <div class="wlv1RcPaid">${r.paid>0?money(r.paid):''}</div>
      <div class="wlv1RcDue">${rcBill>0?money(due):''}</div></div>`;
  }).join('') || '<div class="wlv1RcRow"><div class="wlv1RcProg mut">No update yet</div></div>';

  page('Report Card', `<div class="wlv1Rc">
    <div class="wlv1RcTop" id="wlv1RcTopWrap">
      <div class="wlv1RcTitle">📋 Report Card</div>
      <button class="small ghost noPrint" onclick="webPdfShare()">📄 PDF / Share</button>
      <button class="small ghost noPrint" onclick="wlv1Share('Report Card', wlv1ReportCardText('${esc(p.id||mob(p.mobile))}'))">📤 Text</button>
      <button class="small ghost noPrint" onclick="window.print()">🖨 Print</button>
    </div>
    <div class="card wlv1RcCard">
      <div class="wlv1RcClinic"><b>${esc(clinicPrintTitle(p))}</b>
        <span>${esc(branch(p.branch).address||'')} · Mob: ${esc(normMob(branch(p.branch).mobile||''))}</span></div>
      <div class="wlv1RcPatientRow">
        ${p.photo?`<img class="wlv1RcPhoto" src="${p.photo}">`:`<div class="wlv1RcPhoto blank">👤</div>`}
        <div class="wlv1RcPatientInfo">
          <div class="wlv1RcName">${esc(String(p.name||p.mobile).toUpperCase())}</div>
          <div class="wlv1RcCols">
            <div>${line('AGE',p.age)}${line('ID',p.patientId)}${line('MOB','+91'+mob(p.mobile))}</div>
            <div>${line('DATE',fmtDate(today()))}${line('SEX',p.sex)}${line('DISEASE',p.disease)}${line('ADDRESS',addr)}</div>
          </div>
        </div>
      </div>
      <div class="wlv1RcTotals">
        <div class="wlv1RcBox blue"><small>TOTAL BILL</small><b>${t.bill>0?money(t.bill):money(0)}</b></div>
        <div class="wlv1RcBox green"><small>PAID</small><b>${money(t.paid)}</b></div>
        <div class="wlv1RcBox red"><small>DUE</small><b>${t.bill>0?money(t.due):money(0)}</b></div>
      </div>
      <div class="wlv1RcTable">
        <div class="wlv1RcRow wlv1RcHead"><div class="wlv1RcVisit">VISIT</div><div class="wlv1RcDate">DATE</div>
          <div class="wlv1RcProg">PROGRESS</div><div class="wlv1RcPaid">PAID</div>
          <div class="wlv1RcDue">DUE</div></div>
        ${body}
      </div>
    </div></div>`, true);
  setTimeout(function(){
    try{
      if(window.innerWidth>=900){
        var slot=document.getElementById('wlv1RcTopSlot');
        var tw=document.getElementById('wlv1RcTopWrap');
        if(slot&&tw)slot.appendChild(tw);
      }
    }catch(e){}
  },0);
}
window["wlv1ReportCard"]=wlv1ReportCard;

/* ============================================================================
   WEB APP . TODAY CALL banner, same as the native Dashboard:
   "📞 N calls pending today — tap to call" appears only when N is above zero,
   and tapping it opens Follow-up on the Enquiry tab with the Today filter,
   so the number on the banner and the number of cards always match.
   ========================================================================== */
/* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — **সংখ্যাটা ভুল ছিল।** TK-এর নিজেরই
   ২৯.০৭.২০২৬-এর নিয়ম (খাতার সারি B61): *"টুডে পেন্ডিং কল — এখানে শুধুমাত্র
   এনকোয়ারি সেকশনের নাম্বার আসলে হবে না। ভিজিট সেকশন এবং পেসেন্ট সেকশন —
   অর্থাৎ ফলো আপের তিন জায়গা থেকেই এখানে আসতে হবে।"* ফোনে তিনটেই যোগ হয়
   (DashboardActivity.kt:425, 456-459), কিন্তু ওয়েবে শুধু Enquiry গোনা হত —
   তাই ব্যানারের সংখ্যা কম দেখাত আর খুললে তালিকার সঙ্গে মিলত না।
   ⛔ ফলো-আপের তিন ভাগের ভিতরের নাম: 👥 Enquiry = "Inquiry" · 👣 Visit =
      "Patient" · 👤 Patient = "Treatment" (কোড দেখে মিলিয়ে নেওয়া, আন্দাজ নয়)।
   ⛔ গোনার নিয়ম আগের মতোই — Next Follow-up তারিখ = আজ। */
function wlv1TodayCallCount(){
  /* 🔴🔒 V512 — গোনা ও তালিকা এখন **একই** উৎস (`wlv1TodayCallRows`), তাই
     ব্যানারের সংখ্যা আর ভিতরের তালিকা আর কখনো আলাদা হতে পারে না।
     ঐ ফাংশনটাই তারিখ-ছাঁকনি সরিয়ে, ব্রাঞ্চ-গেট বসিয়ে, এক-মানুষ-একবার
     করে হিসাব করে (কারণগুলো ওখানে পুরো লেখা আছে)। */
  try{ return wlv1TodayCallRows().length; }catch(e){ return 0; }
}
window["wlv1TodayCallCount"]=wlv1TodayCallCount;
function wlv1TodayCallBanner(){
  // \ud83d\udd35 B614 parity (10.08.2026, TK-\u09a8\u09bf\u09b0\u09cd\u09a6\u09c7\u09b6): \u09a1\u09be\u0995\u09cd\u09a4\u09be\u09b0 \u09ab\u09b2\u09cb-\u0986\u09aa \u0995\u09b2 \u0995\u09b0\u09c7\u09a8 \u09a8\u09be \u2014 \u09a4\u09be\u0987
  // \u09a4\u09be\u0981\u09b0 \u09a1\u09cd\u09af\u09be\u09b6\u09ac\u09cb\u09b0\u09cd\u09a1\u09c7 "calls pending" banner \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u09b9\u09af\u09bc \u09a8\u09be (\u0995\u09b2 \u0995\u09b0\u09c7\u09a8 \u09b8\u09cd\u099f\u09be\u09ab)\u0964
  if(typeof user!=='undefined' && user && user.role==='doctor') return '';
  const n = wlv1TodayCallCount();
  if(!n) return '';
  return `<button class="wlv1CallBanner" onclick="wlv1OpenTodayCalls()">\u{1F4DE} ${n} calls pending today \u2014 tap to call</button>`;
}
window["wlv1TodayCallBanner"]=wlv1TodayCallBanner;
function wlv1OpenTodayCalls(){
  /* 🔴 V430 — ব্যানারে তিন ভাগের কল গোনা হয়, তাই খুললে যে ভাগে আজ কল আছে
     সেই ভাগটাই আগে খোলে — নইলে ব্যানারে ৫ দেখিয়ে তালিকায় ২ দেখাত। */
  const r = followFilterRange('Today');
  /* 🔴 V511 — `callsOnly` চিহ্নটাই ঠিক করে দেয় যে এই তালিকায় শুধু "আজ কল
     করার কথা" যাঁদের, তাঁরাই থাকবেন (উপরে applySharedFollowDateFilter দেখুন)।
     ⛔ উপরের ফিল্টার বোতাম (`wlv1FollowFilter`) এই চিহ্ন বসায় না, তাই
        মেনু থেকে Today খুললে আগের আচরণ এক অক্ষরও বদলায়নি। */
  __followDateFilter = {mode:'Today', from:r[0], to:r[1], callsOnly:true};
  /* 🔴🔴🔒 V512 (TK-নির্দেশ) — আগে এখানে **একটা ভাগ** খোলা হতো, তাই ব্যানারে
     ৮ দেখিয়ে পর্দায় ৩ জন থাকত (বাকিরা অন্য ট্যাবে)। এখন ফোনের মতোই
     তিনটে ভাগ **এক পর্দায় মিশে** দেখায় — ব্যানারের সংখ্যা = পর্দার সংখ্যা,
     আর সবাইকে এখান থেকেই কল করা যায়।
     ⛔ উপরের তিনটে ট্যাব ও ছাঁকনির বোতাম আগের মতোই আছে; যেকোনোটায় চাপলেই
        মিশ্র-মোড শেষ হয়ে পুরোনো এক-ভাগের পর্দা ফিরে আসে (ফোনের switchTab-এর মতো)।
     ⛔ `_followupCore()` সরাসরি ডাকা হয় (`followup()` নয়), কারণ `followup()`
        ইচ্ছে করেই চিহ্নটা নিভিয়ে দেয়। */
  __wlv1FuAllSections = true;
  try{
    if(typeof window._invalidateFollowLookupCache==='function')window._invalidateFollowLookupCache();
    _followupCore('Inquiry');
  }catch(e){
    __wlv1FuAllSections = false;
    followup('Inquiry');           /* কিছু ভাঙলে পুরোনো পথেই ফিরে যায় */
  }
}
window["wlv1OpenTodayCalls"]=wlv1OpenTodayCalls;

/* ============================================================================
   WEB APP . APPOINTMENT screen, same as the native AppointmentActivity:
   the booking form on top ("Add Appointment") and "Upcoming Appointments"
   below it. Exactly the native rule for the list: every enquiry that has an
   appointmentDate of today or later, inside the person's branch, earliest
   first. Nothing new is stored . the same enquiries row the native app uses.
   ========================================================================== */
function wlv1UpcomingAppointments(){
  const br = user && user.branch ? user.branch : 'All';
  return load('enquiries')
    .filter(r=>{
      const ad = String(r.appointmentDate||'').slice(0,10);
      if(!ad || ad < today()) return false;
      if(br !== 'All' && String(r.branch||'') && String(r.branch||'') !== br) return false;
      return true;
    })
    .sort((a,b)=>String(a.appointmentDate).localeCompare(String(b.appointmentDate)));
}
window["wlv1UpcomingAppointments"]=wlv1UpcomingAppointments;

function appointmentScreen(){
  const list = wlv1UpcomingAppointments().map(r=>`<div class="wlv1ApRow">
      <div class="wlv1ApDate">\u{23F0} ${esc(fmtDate(r.appointmentDate))}</div>
      <div class="wlv1ApName">${esc(String(r.name||'').toUpperCase())}</div>
      <div class="wlv1ApMeta">${esc(shownMob(r.mobile))}${r.branch?' \u00b7 '+esc(r.branch):''}</div>
      ${r.remarks?`<div class="wlv1ApRem">${esc(r.remarks)}</div>`:''}
      <div class="actions" style="margin-top:8px"><button class="ghost small" onclick="wlv1ApptEdit('${esc(r.id)}')">✏️ Edit</button></div>
    </div>`).join('') || '<div class="card mut">No upcoming appointments.</div>';
  page('Appointment', `<div class="card"><div class="sectionTitle miniTitle">Add Appointment</div>
      ${apptForm()}</div>
    <div class="sectionTitle">Upcoming Appointments</div>${list}`, true);
}
window["appointmentScreen"]=appointmentScreen;

/* ============================================================================
   WEB APP . BLOOD TEST / INVESTIGATION ADVICE, matched to the native
   InvestigationAdviceActivity. The catalogue below is copied test by test out
   of the native ClinicalRepository.investigationCategories (8 categories,
   98 tests) . nothing invented, nothing dropped.
     . a category grid, each card showing how many tests it holds and how many
       are currently ticked
     . "Apply Common Blood Test" re-ticks the set saved last time (blank until
       a set has been saved once, exactly like the phone app)
     . SAVE and SAVE & PRINT
   ========================================================================== */
const WLV1_INVEST=[{"name": "Hematology", "emoji": "🩸", "tests": ["CBC", "Hemoglobin (HB)", "TLC", "DLC", "ESR", "RBC Count", "Reticulocyte Count", "Platelets Count", "BT-CT, PT, PTT", "Malaria Parasites", "Band Cell", "Toxic Granules", "Complete Hemogram (PCV, MCV, MCH, MCHC)"]}, {"name": "Bio-Chemistry", "emoji": "🧪", "tests": ["Blood Sugar", "Urea", "Creatinine", "Uric Acid", "Calcium", "Amylase", "Lipase", "BT-CT, PT, PTT", "Testosterone", "SGPT", "SGOT", "Bilirubin", "Alkaline P. Tase", "Cholestrol", "Lipid Profile", "Sodium", "Potassium", "Chloride & Bicarbonate", "Lithium", "Total Protein", "Albumin", "Ag Ration", "LFT", "KFT", "Creatinence", "Clearance", "Micro Albumin", "Cratine Ratio", "CPKMB", "Tripomine I"]}, {"name": "Immunology", "emoji": "🛡️", "tests": ["Blood Group ABO", "HBs AG (Slide/Elisa)", "HCV", "HIV", "MP KIT", "Widal", "VDRL (R, P, R)", "A.S.O. Titre", "RA Test", "C.R.P.", "Aldehyde", "Pregnancy Test", "Mantoux Test (5/10 TU)", "K-39 for kala-ajar (PF+PV Antigen)"]}, {"name": "Special Test", "emoji": "⭐", "tests": ["T3, T4, TSH, Free T3, T4", "Free T3, LH, FSH", "Prolactin", "Torch Test", "TB for Elisa IgG/IgmIgA", "Anti Cardiolipin", "ADA", "PAP Smear", "Allergy Profile", "CSF, Synovia Fluid (Pleural, Ascitic Fluid)", "Fluid Analysis", "Histopathology (Biopsy)", "FNAC", "Blood Culture", "Prepheral Blood Smear", "Toxoplasma, IgG, Igm", "Electrophoresis", "Pus Culture", "Indirect Coomb Test", "Micro Albumin (Tubi)", "CRP (Turbi)", "G-6 Pd", "Alpha Feto Protein", "B-HCG (Quantitative)", "PSA", "ANF", "DS DNA", "ANA", "CCP"]}, {"name": "Urine", "emoji": "🚻", "tests": ["R.E./M.E.", "Bile Salt/Pigment/Acetone", "Benz-Zone's Protein", "Culture & Sensitivity", "Detection"]}, {"name": "Stool", "emoji": "💩", "tests": ["R.E./M.E./Occult Blood", "Culture & Sensitivity (C/S)"]}, {"name": "Semen", "emoji": "🧬", "tests": ["Semen Analysis"]}, {"name": "Imaging", "emoji": "🖥️", "tests": ["USG Scrotal", "Whole Abdomen", "Lower Abdomen", "MRI Fistulogram"]}];
window["WLV1_INVEST"]=WLV1_INVEST;
let wlv1InvPick = {};      // test name -> true
let wlv1InvCat  = '';      // open category, '' = grid
function wlv1InvCommonGet(){
  try{ return JSON.parse(localStorage.getItem('wlv1CommonBloodTest')||'[]'); }catch(e){ return []; }
}
function wlv1InvCommonSet(list){
  try{ localStorage.setItem('wlv1CommonBloodTest', JSON.stringify(list||[])); }catch(e){}
}
window["wlv1InvCommonGet"]=wlv1InvCommonGet;
// ⛔ 04.08.2026: এখন আর কোথাও ডাকা হয় না — wlv1InvOpenPrevious()-এর
// ইন্টারেক্টিভ (tick/untick পপ-আপসহ) সংস্করণ এর জায়গা নিয়েছে, ফোনের
// নিয়মের সাথে মিলিয়ে। TK-কে না জানিয়ে কোড মোছা হয় না বলে dead code
// হিসেবে রাখা হলো (প্রজেক্টের চালু নিয়ম, B206-এর মতো)।
function wlv1InvApplyCommon(){
  const remembered = wlv1InvCommonGet();
  if(!remembered.length) return toast('No common set saved yet — select tests and Save once first.');
  remembered.forEach(t=>{ wlv1InvPick[t]=true; });
  toast(remembered.length+' tests applied');
  wlv1InvRender();
}
window["wlv1InvApplyCommon"]=wlv1InvApplyCommon;
function wlv1InvToggle(name){
  if(wlv1InvPick[name]) delete wlv1InvPick[name]; else wlv1InvPick[name]=true;
  wlv1InvRender();
}
window["wlv1InvToggle"]=wlv1InvToggle;
function wlv1InvOpen(cat){ wlv1InvCat=cat; wlv1InvRender(); }
window["wlv1InvOpen"]=wlv1InvOpen;
function wlv1InvRender(){
  const box=document.getElementById('wlv1InvBox'); if(!box) return;
  if(!wlv1InvCat){
    box.innerHTML = '<div class="wlv1InvGrid">' + WLV1_INVEST.map(c=>{
      const sel=c.tests.filter(t=>wlv1InvPick[t]).length;
      return `<button class="wlv1InvCard" onclick="wlv1InvOpen('${c.name.replace(/'/g,"\\'")}')">
        <span class="wlv1InvIco">${c.emoji}</span><b>${c.name}</b>
        <small>${sel? (sel+' / '+c.tests.length+' selected') : (c.tests.length+' tests')}</small></button>`;
    }).join('') + '</div>';
    return;
  }
  const c = WLV1_INVEST.find(x=>x.name===wlv1InvCat);
  if(!c){ wlv1InvCat=''; return wlv1InvRender(); }
  box.innerHTML = `<button class="small ghost" onclick="wlv1InvOpen('')">All Categories</button>
    <div class="sectionTitle miniTitle">${c.emoji} ${c.name}</div>` +
    c.tests.map(t=>`<label class="wlv1InvItem ${wlv1InvPick[t]?'on':''}">
      <input type="checkbox" ${wlv1InvPick[t]?'checked':''} onchange="wlv1InvToggle('${t.replace(/'/g,"\\'")}')">
      <span>${t}</span></label>`).join('');
}
window["wlv1InvRender"]=wlv1InvRender;
function wlv1InvSave(id, alsoPrint){
  const picked = Object.keys(wlv1InvPick);
  if(!picked.length) return toast('Select at least one test');
  wlv1InvCommonSet(picked);                       // same memory rule as the phone app
  const rem = (document.getElementById('btRem')||{}).value || '';
  const selected = picked.join(', ');
  // NOTE (checked, not assumed): printBlood() reads the ticked boxes straight
  // out of the open popup and then closes it, while saveMedicalRecord() needs
  // no popup at all. So printing must happen FIRST, saving after . otherwise
  // "SAVE & PRINT" would print nothing.
  if(alsoPrint){
    const box = document.getElementById('wlv1InvHidden');
    if(box) box.innerHTML = picked.map(t=>`<input type="checkbox" class="bt" value="${t}" checked>`).join('');
    try{ printBlood(id); }catch(e){}
    saveMedicalRecord(id,'Blood Test',selected,rem);
    return;
  }
  saveMedicalRecord(id,'Blood Test',selected,rem);
  closeModal();
  summary(id);
}
window["wlv1InvSave"]=wlv1InvSave;

/* 🔴 V430 (TK-সিদ্ধান্ত ১৮.০৮.২০২৬: "ফোনের মতো তিনটা করুন") — Blood Test
   পর্দায় ফোনের মতোই তিনটে বোতাম: Save · Share · Print
   (res/layout/activity_investigation_advice.xml:73,88,104)। ওয়েবে Share
   ছিল না, তাই WhatsApp-এ পাঠানোর উপায়ও ছিল না।
   ⛔ সেভ ও ছাপার পুরনো পথ একটুও বদলায়নি — শুধু একটা নতুন বোতাম যোগ হলো। */
function wlv1InvShare(id){
  const picked = Object.keys(wlv1InvPick||{});
  if(!picked.length) return toast('Select at least one test');
  const p = (typeof patientById==='function' ? (patientById(id)||{}) : {});
  const rem = (document.getElementById('btRem')||{}).value || '';
  const b = (typeof branch==='function' ? (branch(p.branch)||{}) : {});
  const txt = '*BLOOD TEST / INVESTIGATION ADVICE*'
    + '\nPatient : ' + String(p.name||'')
    + (p.patientId ? '\nPatient ID : ' + p.patientId : '')
    + '\nDate : ' + wlv1Dot(today())
    + '\n\nTests :\n' + picked.map(function(x){ return '• ' + x; }).join('\n')
    + (rem ? '\n\nAdvice / Remarks : ' + rem : '')
    + '\n\n' + (typeof clinicPrintTitle==='function' ? clinicPrintTitle(p) : 'PILES CLINIC')
    + (b.address ? '\n' + b.address : '');
  wlv1Share('Blood Test / Investigation Advice', txt);
}
window["wlv1InvShare"]=wlv1InvShare;

