function wlv1PrintCheckup(id){
  const p = patientById(id);
  if(!p) return toast('Patient not found');
  const rec = load('medical')
    .filter(x=>(x.patientId===id||mob(x.mobile)===mob(p.mobile)) &&
               String(x.type||'').toLowerCase().includes('checkup'))
    .sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))[0];
  if(!rec) return toast('No doctor checkup saved for this patient yet');
  const line = (k,v)=> v ? `<tr><td><b>${esc(k)}</b></td><td>${esc(v)}</td></tr>` : '';
  const rows = line('Date', fmtDate(rec.date))
             + line('Diagnosis', rec.diagnosis || rec.details)
             + line('Decision', rec.decision)
             + line('Doctor Note', rec.doctorFullNote);
  professionalMedicalPrint(id, 'DOCTOR CHECKUP', `<table class="printTable">${rows}</table>`, '');
}
window["wlv1PrintCheckup"]=wlv1PrintCheckup;

/* ============================================================================
   WEB APP . BRIEFING: the Master-only approval sections the native Briefing
   screen has (Backdate Payment requests and Payment Edit requests). They live
   in the same Supabase tables the phone app uses
   (payment_backdate_requests / payment_edit_requests), so both sides always
   see the same pending list.
   Read only for now . approving/rejecting is still done in the phone app,
   and the screen says so, so nobody is left guessing.
   ========================================================================== */
async function wlv1LoadApprovals(){
  const box = document.getElementById('wlv1Approvals');
  if(!box) return;
  if(typeof isMaster!=='function' || !isMaster()){ box.innerHTML=''; return; }
  if(typeof sb==='undefined' || !sb){ box.innerHTML=''; return; }
  box.innerHTML = '<div class="card mut">Loading...</div>';
  const grab = async (table)=>{
    try{
      const {data,error} = await sb.from(table).select('*').eq('status','pending').limit(200);
      return (!error && Array.isArray(data)) ? data : [];
    }catch(e){ return []; }
  };
  const [back, edit, refedit] = await Promise.all([
    grab('payment_backdate_requests'),
    grab('payment_edit_requests'),
    grab('referral_edit_requests')
  ]);
  let html = '';
  if(back.length){
    html += '<details><summary class="sectionTitle">Backdate Payment Requests ('+back.length+')</summary>' + back.map(r=>`
      <div class="card wlv1AppRow"><b>${esc(String(r.name||'').toUpperCase())}</b>
        <div class="wlv1AppMeta">${esc(shownMob(r.mobile||''))}${r.branch?' \u00b7 '+esc(r.branch):''}</div>
        <div class="wlv1AppMeta">${esc(fmtDate(r.requestedDate))} \u00b7 ${money(Number(r.amount||0))} \u00b7 ${esc(r.mode||'')}</div>
        ${r.remarks?`<div class="wlv1AppMeta">${esc(r.remarks)}</div>`:''}
        <div class="wlv1AppBy">Asked by ${esc(r.requestedByName||r.requestedBy||'')}</div>
        <div class="actions">
          <button onclick="wlv1ApproveBackdate('${esc(r.id)}')">✅ Approve</button>
          <button class="ghost" onclick="wlv1RejectRequest('payment_backdate_requests','${esc(r.id)}')">Reject</button>
        </div></div>`).join('') + '</details>';
  }
  if(edit.length){
    html += '<details><summary class="sectionTitle">Payment Edit Requests ('+edit.length+')</summary>' + edit.map(r=>`
      <div class="card wlv1AppRow"><b>${esc(String(r.name||'').toUpperCase())}</b>
        <div class="wlv1AppMeta">${esc(shownMob(r.mobile||''))}${r.branch?' \u00b7 '+esc(r.branch):''}</div>
        <div class="wlv1AppMeta">${money(Number(r.oldAmount||0))} \u2192 ${money(Number(r.newAmount||0))} \u00b7 ${esc(fmtDate(r.paymentDate))}</div>
        ${r.reason?`<div class="wlv1AppMeta">${esc(r.reason)}</div>`:''}
        <div class="wlv1AppBy">Asked by ${esc(r.requestedByName||r.requestedBy||'')}</div>
        <div class="actions">
          <button onclick="wlv1ApproveEdit('${esc(r.id)}','${esc(r.paymentId)}',${Number(r.newAmount||0)},'${esc(r.requestedBy||'')}')">Approve</button>
          <button class="ghost" onclick="wlv1RejectRequest('payment_edit_requests','${esc(r.id)}')">Reject</button>
        </div></div>`).join('') + '</details>';
  }
  /* 🟢 B628 (11.08.2026): Referral Income এডিট/ডিলিটের অনুরোধ — Master এখানেই Approve/Reject করবেন
     (ফোনের BriefingActivity.approveReferralEditRequest-এর হুবহু ওয়েব-সংস্করণ)। */
  if(refedit.length){
    html += '<details><summary class="sectionTitle">Referral Income Edit Requests ('+refedit.length+')</summary>' + refedit.map(r=>`
      <div class="card wlv1AppRow"><b>${esc(String(r.docName||'').toUpperCase())}</b>
        <div class="wlv1AppMeta">${esc(r.patient||'')}${r.branch?' · '+esc(r.branch):''}</div>
        <div class="wlv1AppMeta">${r.isDelete?('🗑 Delete · '+money(Number(r.oldAmount||0))+' · '+esc(r.oldStatus||'')):(money(Number(r.oldAmount||0))+' → '+money(Number(r.newAmount||0))+' · '+esc(r.oldStatus||'')+' → '+esc(r.newStatus||''))}</div>
        ${r.reason?`<div class="wlv1AppMeta">${esc(r.reason)}</div>`:''}
        <div class="wlv1AppBy">Asked by ${esc(r.requestedByName||r.requestedBy||'')}</div>
        <div class="actions">
          <button onclick="wlv1ApproveReferralEdit('${esc(r.id)}')">Approve</button>
          <button class="ghost" onclick="wlv1RejectRequest('referral_edit_requests','${esc(r.id)}')">Reject</button>
        </div></div>`).join('') + '</details>';
  }
  box.innerHTML = html;
}
window["wlv1LoadApprovals"]=wlv1LoadApprovals;

/* ============================================================================
   WEB APP . EXPORT DATA (CSV), same as the native ExportDataActivity:
   Master only, and the same four tables the phone app offers
   (patients / enquiries / payments / followups). Each ticked table downloads
   as its own .csv file, which is what the phone app also produces.
   Read only . nothing is written or changed anywhere.
   ========================================================================== */
function wlv1CsvCell(v){
  if(v===null||v===undefined) return '';
  let s = (typeof v==='object') ? JSON.stringify(v) : String(v);
  s = s.replace(/"/g,'""');
  return /[",\n]/.test(s) ? '"'+s+'"' : s;
}
function wlv1CsvOf(rows){
  if(!rows.length) return '';
  const cols = [...rows.reduce((set,r)=>{Object.keys(r||{}).forEach(k=>set.add(k));return set;}, new Set())];
  return cols.join(',') + '\n' +
    rows.map(r=>cols.map(c=>wlv1CsvCell(r ? r[c] : '')).join(',')).join('\n');
}
window["wlv1CsvOf"]=wlv1CsvOf;
function wlv1ExportScreen(){
  if(!isMaster()) return toast('Only Master Admin');
  /* 🖥️🔵 B667: Export Data — পপ-আপ থেকে পূর্ণ পাতা। Android-এ পূর্ণ পর্দা
     (`ExportDataActivity.kt`)। ⛔ কী কী export হবে · CSV বানানো — কিচ্ছু বদলায়নি। */
  page('\u{1F4E4} Export Data', `
    <div class="card mut tiny">Choose what to export. Each one downloads as its own CSV file, which opens in Excel.</div>
    <label class="check"><input type="checkbox" class="wlv1Exp" value="patients" checked> <span>Patients</span></label>
    <label class="check"><input type="checkbox" class="wlv1Exp" value="enquiries" checked> <span>Enquiries</span></label>
    <label class="check"><input type="checkbox" class="wlv1Exp" value="payments" checked> <span>Payments</span></label>
    <label class="check"><input type="checkbox" class="wlv1Exp" value="followups" checked> <span>Follow-ups</span></label>
    <div class="actions"><button onclick="wlv1ExportRun()">Export CSV</button></div>`);
}
window["wlv1ExportScreen"]=wlv1ExportScreen;
function wlv1ExportRun(){
  const picked = [...document.querySelectorAll('.wlv1Exp:checked')].map(x=>x.value);
  if(!picked.length) return toast('Select at least one');
  let done = 0;
  picked.forEach((t,i)=>{
    const rows = load(t) || [];
    if(!rows.length) return;
    const csv = wlv1CsvOf(rows);
    setTimeout(()=>{
      try{
        const blob = new Blob(['\uFEFF'+csv], {type:'text/csv;charset=utf-8;'});
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = t + '_' + today() + '.csv';
        document.body.appendChild(a); a.click();
        setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); }, 1000);
      }catch(e){}
    }, i*400);          // small gap so the browser allows several downloads
    done++;
  });
  toast(done ? (done+' file(s) downloading') : 'Nothing to export yet');
}
window["wlv1ExportRun"]=wlv1ExportRun;

/* WEB APP . Master approval actions, writing EXACTLY the same fields the
   native app writes (PaymentRepository.approvePaymentEditRequest /
   rejectPaymentEditRequest / rejectBackdateRequest), so a decision taken on
   the computer is identical to one taken on the phone.

   Deliberately NOT done here: approving a BACKDATE request. On the phone that
   also creates a whole real payment (bill handling, follow-up updates and so
   on). Copying that money logic into the web would be risky, so that one
   button stays phone only and the screen says so.                          */
async function wlv1RejectRequest(table, id){
  if(!isMaster()) return toast('Only Master Admin');
  if(typeof sb==='undefined' || !sb) return toast('No internet connection');
  if(!confirm('Reject this request?')) return;
  const now = new Date().toISOString();
  try{
    const {error} = await sb.from(table).update({
      status:'rejected', approvedBy:user.mobile, approvedAt:now, updatedAt:now
    }).eq('id', id);
    if(error) return toast('Could not reject . try again');
    toast('Request rejected');
    wlv1LoadApprovals();
  }catch(e){ toast('Could not reject . try again'); }
}
window["wlv1RejectRequest"]=wlv1RejectRequest;

async function wlv1ApproveEdit(reqId, paymentId, newAmount, requestedBy){
  if(!isMaster()) return toast('Only Master Admin');
  if(typeof sb==='undefined' || !sb) return toast('No internet connection');
  if(!confirm('Approve this amount change?')) return;
  const now = new Date().toISOString();
  try{
    // 1) the real payment row . same fields the phone app writes
    const {error:e1} = await sb.from('payments').update({
      amount:Number(newAmount||0), editedAt:now, editedBy:user.mobile,
      editRequestedBy:requestedBy||'', editApprovedBy:user.mobile, updatedAt:now
    }).eq('id', paymentId);
    if(e1) return toast('Could not update the payment . try again');
    // 2) mark the request approved
    await sb.from('payment_edit_requests').update({
      status:'approved', approvedBy:user.mobile, approvedAt:now, updatedAt:now
    }).eq('id', reqId);
    // 3) keep this device's copy in step so the screens show the new amount at once
    try{ upd('payments', paymentId, {amount:Number(newAmount||0), editedAt:now, editedBy:user.mobile,
      editRequestedBy:requestedBy||'', editApprovedBy:user.mobile, updatedAt:now}); }catch(e){}
    toast('Approved');
    wlv1LoadApprovals();
  }catch(e){ toast('Could not approve . try again'); }
}
window["wlv1ApproveEdit"]=wlv1ApproveEdit;

/* 🟢 B628: Master Referral-এডিট/ডিলিট Approve — আসল doctor_visits.referralPayments-এ প্রয়োগ
   (cloud থেকে টাটকা row এনে, ঠিক entryId-র সারিটা বদল/বাদ, paid/due আবার হিসাব), তারপর অনুরোধ
   approved মার্ক। ⛔ কোনো নতুন টাকা তৈরি হয় না — বিদ্যমান প্রমাণিত পথ (addReferralEntry-র মতোই হিসাব)। */
async function wlv1ApproveReferralEdit(reqId){
  if(!isMaster()) return toast('Only Master Admin');
  if(typeof sb==='undefined' || !sb) return toast('No internet connection');
  const now = new Date().toISOString();
  try{
    const {data:reqs,error:er} = await sb.from('referral_edit_requests').select('*').eq('id',reqId).limit(1);
    if(er || !Array.isArray(reqs) || !reqs.length) return toast('Request not found');
    const req = reqs[0];
    if(!confirm(req.isDelete?'Approve delete of this referral entry?':'Approve this referral change?')) return;
    const {data:docs,error:ed} = await sb.from('doctor_visits').select('*').eq('id',req.docId).limit(1);
    if(ed || !Array.isArray(docs) || !docs.length) return toast('Doctor row not found');
    const doc = docs[0];
    let arr = Array.isArray(doc.referralPayments) ? doc.referralPayments.slice() : [];
    let idx = arr.findIndex(e=>String(e.id)===String(req.entryId));
    if(idx<0) return toast('That entry no longer exists');
    if(req.isDelete){ arr.splice(idx,1); }
    else { arr[idx] = {...arr[idx], amount:Number(req.newAmount||0), status:req.newStatus||'Unpaid', editedAt:now, editedBy:user.mobile}; }
    let inc = doctorReferralTotals([{referralPayments:arr}]);
    const {error:e1} = await sb.from('doctor_visits').update({
      referralPayments:arr, referralPaid:inc.paid, referralDue:inc.due, updatedAt:now
    }).eq('id', req.docId);
    if(e1) return toast('Could not apply . try again');
    await sb.from('referral_edit_requests').update({
      status:'approved', approvedBy:user.mobile, approvedAt:now, updatedAt:now
    }).eq('id', reqId);
    try{ upd('doctor_visits', req.docId, {referralPayments:arr, referralPaid:inc.paid, referralDue:inc.due, updatedAt:now}); }catch(e){}
    toast('Approved');
    wlv1LoadApprovals();
  }catch(e){ toast('Could not approve . try again'); }
}
window["wlv1ApproveReferralEdit"]=wlv1ApproveReferralEdit;

/* 🔵🔒 TK-অনুমোদিত (09.08.2026, শটলিস্ট #২): কম্পিউটার/ওয়েবেও মাস্টার Refund/Reopen
   অনুরোধ Approve/Reject করতে পারবেন (আগে শুধু ফোনে হতো)। ⛔ ফোনের হুবহু একই লজিক:
   Refund approve = ওই refund payments-সারির refundApprovalStatus='approved' (তখনই মোট থেকে কমে;
   বাকি সব হিসাব আগে থেকেই wlv1IsApprovedRefund মানে)। Reopen approve = chamber_close সারিটা (BRANCH|date)
   মুছে ফেলা (=খোলা)। কোনো নতুন টাকা/হিসাব তৈরি হয় না — শুধু বিদ্যমান প্রমাণিত পথ। */
function wlv1NoticeField(msg,key){var L=String(msg||'').split('\n');var pre=(key+' :').toLowerCase();for(var i=0;i<L.length;i++){var t=L[i].trim();if(t.toLowerCase().indexOf(pre)===0)return t.substring(pre.length).trim();}return '';}
window["wlv1NoticeField"]=wlv1NoticeField;
function wlv1CloseNotice(id,replyText){try{var all=briefings();var i=all.findIndex(function(b){return b.id===id;});if(i>-1){if(replyText){all[i].replies=[].concat(all[i].replies||[],[{id:uid('breply'),by:user.mobile,text:replyText,at:new Date().toISOString(),deletedAt:'',deletedBy:''}]);}all[i].deletedAt=new Date().toISOString();all[i].deletedBy=user.mobile;all[i].updatedAt=new Date().toISOString();saveBriefings(all);cloudUpsertBriefing(all[i]);}}catch(_e){}}
window["wlv1CloseNotice"]=wlv1CloseNotice;
/* নোটিশ-কার্ডে ধরন বুঝে Approve/Reject বোতাম (master-এর briefingHome কার্ডে বসে)। */
function wlv1ApprovalButtons(b){var t=String(b&&b.title||'').toLowerCase();
  /* 🔵 B618 (11.08.2026): ছুটির অনুরোধ — Master অথবা ওই ব্রাঞ্চের Doctor (যেকোনো একজন)। */
  if(t.indexOf('leave request')>=0){if(!wlv1CanApproveLeave(b))return '';return `<button class="anBrApprove" onclick="wlv1ApproveLeaveNotice('${b.id}')">✅ Approve</button><button class="ghost" onclick="wlv1RejectLeaveNotice('${b.id}')">Reject</button>`;}
  if(typeof isMaster==='function'&&!isMaster())return '';/* নিচেরগুলো (refund/reopen/delete) শুধু Master — doctor-এর কার্ডেও যেন না আসে */
  if(t.indexOf('refund request')>=0)return `<button class="anBrApprove" onclick="wlv1ApproveRefundNotice('${b.id}')">✅ Approve</button><button class="ghost" onclick="wlv1RejectRefundNotice('${b.id}')">Reject</button>`;if(t.indexOf('reopen request')>=0)return `<button class="anBrApprove" onclick="wlv1ApproveReopenNotice('${b.id}')">✅ Approve</button><button class="ghost" onclick="wlv1RejectReopenNotice('${b.id}')">Reject</button>`;if(t.indexOf('delete request')>=0)return `<button class="anBrApprove" onclick="wlv1ApproveDeleteNotice('${b.id}')">✅ Approve &amp; Delete</button><button class="ghost" onclick="wlv1RejectDeleteNotice('${b.id}')">Reject</button>`;return '';}
window["wlv1ApprovalButtons"]=wlv1ApprovalButtons;
/* 🔵 B618: ছুটি-অনুমোদনের অধিকার — Master সবসময়; নইলে ওই ব্রাঞ্চের Doctor (message-এর Branch মিললে)। */
function wlv1CanApproveLeave(b){try{if(typeof isMaster==='function'&&isMaster())return true;var role=String((typeof user!=='undefined'&&user&&user.role)||'').toLowerCase();if(role!=='doctor')return false;var br=wlv1NoticeField(b&&b.message,'Branch');var mine=String((typeof user!=='undefined'&&user&&user.branch)||'').trim().toUpperCase();return !!br&&mine===String(br).trim().toUpperCase();}catch(_e){return false;}}
window["wlv1CanApproveLeave"]=wlv1CanApproveLeave;
/* ওই নোটিশের জন্য pending refund payments-সারি বের করা: ব্রিফিং id ('brief_'+refundId) থেকে সরাসরি,
   নইলে বার্তার Patient ID ধরে ওই রোগীর প্রথম pending refund (ফোনের confirmApproveRefund-এর মতোই)। */
function wlv1FindPendingRefundForNotice(b){try{var pcode=wlv1NoticeField(b.message,'Patient ID');var pend=load('payments').filter(function(x){return wlv1IsRefundRow(x)&&String(x.refundApprovalStatus||'').toLowerCase()==='pending'&&(!pcode||String(x.patientCode||'')===String(pcode));});if(String(b.id).indexOf('brief_')===0){var rid=String(b.id).slice(6);var byId=pend.find(function(x){return String(x.id)===rid;});if(byId)return byId;var any=load('payments').find(function(x){return String(x.id)===rid&&wlv1IsRefundRow(x)&&String(x.refundApprovalStatus||'').toLowerCase()==='pending';});if(any)return any;}return pend[0]||null;}catch(_e){return null;}}
async function wlv1ResolveRefundNotice(id,approve){if(!isMaster())return toast('Only Master Admin');var b=briefings().find(function(x){return x.id===id;});if(!b)return toast('Notice not found');var row=wlv1FindPendingRefundForNotice(b);if(!row){wlv1CloseNotice(id,'ℹ️ Pending refund not found — closed by '+(codeName(user.mobile)||user.mobile));toast('এখন আর কোনো Pending Refund নেই — নোটিশ বন্ধ করা হলো');briefingHome();return;}var now=new Date().toISOString();var st=approve?'approved':'rejected';try{if(typeof sb!=='undefined'&&sb){var r=await sb.from('payments').update({refundApprovalStatus:st,refundApprovedBy:user.mobile,updatedAt:now}).eq('id',row.id);if(r&&r.error)return toast('করা গেল না — আবার চেষ্টা করুন');}try{upd('payments',row.id,{refundApprovalStatus:st,refundApprovedBy:user.mobile,updatedAt:now});}catch(_e){}wlv1CloseNotice(id,(approve?'✅ Refund Approved':'❌ Refund Rejected')+' by '+(codeName(user.mobile)||user.mobile));toast(approve?'Refund Approved ✓':'Refund Rejected');briefingHome();}catch(e){toast('করা গেল না — আবার চেষ্টা করুন');}}
function wlv1ApproveRefundNotice(id){return wlv1ResolveRefundNotice(id,true);}
function wlv1RejectRefundNotice(id){return wlv1ResolveRefundNotice(id,false);}
window["wlv1ApproveRefundNotice"]=wlv1ApproveRefundNotice;window["wlv1RejectRefundNotice"]=wlv1RejectRefundNotice;
async function wlv1ApproveReopenNotice(id){if(!isMaster())return toast('Only Master Admin');var b=briefings().find(function(x){return x.id===id;});if(!b)return toast('Notice not found');var branch=wlv1NoticeField(b.message,'Branch');var date=wlv1NoticeField(b.message,'Date');if(!branch||!date)return toast('এই অনুরোধ থেকে Branch/Date চেনা গেল না');var closeId=String(branch).trim().toUpperCase()+'|'+String(date).trim();try{var gone=true;if(typeof sb!=='undefined'&&sb){gone=await wlv1CloudDeleteRow('chamber_close',closeId);}if(!gone)return toast('Cloud-এ reopen করা গেল না — আবার চেষ্টা করুন');try{save('chamber_close',(load('chamber_close')||[]).filter(function(r){return r&&String(r.id)!==closeId;}),{skipCloud:true,skipBackup:true});}catch(_e){}wlv1CloseNotice(id,'✅ Reopened by '+(codeName(user.mobile)||user.mobile));toast('Reopened ✓ — '+branch+' · '+date);briefingHome();}catch(e){toast('Reopen করা গেল না — আবার চেষ্টা করুন');}}
function wlv1RejectReopenNotice(id){if(!isMaster())return toast('Only Master Admin');wlv1CloseNotice(id,'❌ Reopen Rejected by '+(codeName(user.mobile)||user.mobile));toast('Reopen Rejected');briefingHome();}
window["wlv1ApproveReopenNotice"]=wlv1ApproveReopenNotice;window["wlv1RejectReopenNotice"]=wlv1RejectReopenNotice;
/* Delete-অনুমোদন: ওয়েবের নিজস্ব delete-রেসিপির হুবহু (trash upsert → wlv1CloudDeleteRow → local remove →
   wlv1MarkDeletedCloud)। Payment হলে বার্তার "Row ID" ধরে সঠিক সারি; Enquiry/Patient হলে মোবাইল (শেষ ১০)
   ধরে (ফোনের approveAndDelete-এর মতোই)। ⛔ followup cascade নয় — ওয়েব নিজে যেমন করে (ইতিহাস অক্ষত)। */
async function wlv1ApproveDeleteNotice(id){if(!isMaster())return toast('Only Master Admin');var b=briefings().find(function(x){return x.id===id;});if(!b)return toast('Notice not found');var type=(wlv1NoticeField(b.message,'Type')||'').toLowerCase();var table=type==='payment'?'payments':(type==='enquiry'?'enquiries':'patients');function last10(s){return String(s||'').replace(/\D/g,'').slice(-10);}var all=load(table)||[];var idx=-1;if(table==='payments'){var rowId=wlv1NoticeField(b.message,'Row ID');if(!rowId)return toast('এই অনুরোধ থেকে রেকর্ড চেনা গেল না');idx=all.findIndex(function(x){return String(x.id)===String(rowId);});}else{var mm=last10(wlv1NoticeField(b.message,'Mobile'));if(mm.length!==10)return toast('এই অনুরোধ থেকে মোবাইল চেনা গেল না');idx=all.findIndex(function(x){return last10(x.mobile)===mm;});}if(idx<0){wlv1CloseNotice(id,'ℹ️ Record already deleted — closed by '+(codeName(user.mobile)||user.mobile));toast('রেকর্ড পাওয়া গেল না — হয়তো আগেই মুছে গেছে; নোটিশ বন্ধ');briefingHome();return;}var row=all[idx];if(!confirm('Approve & Delete?\n\n'+(row.name||row.patientId||'')+'\n\nএই রেকর্ডটা Trash-এ যাবে (পরে Restore করা যাবে)।'))return;try{var t={id:wlv1TrashIdFor(table,row.id),table:table,record:row,deletedAt:new Date().toISOString(),deletedBy:(user&&user.mobile)||''};add('trash',t);var okT=true;try{okT=await directCloudUpsertRow('trash',t);}catch(_e){okT=false;}if(!okT)return toast('Trash-এ রাখা গেল না — কিছুই মোছা হয়নি');var gone=await wlv1CloudDeleteRow(table,row.id);if(!gone)return toast('Cloud-এ মোছা গেল না — কিছুই মোছা হয়নি, আবার চেষ্টা করুন');var all2=load(table)||[];var j=all2.findIndex(function(x){return String(x.id)===String(row.id);});if(j>-1){all2.splice(j,1);put(table,all2);}try{await wlv1MarkDeletedCloud(table,row.id);}catch(_e){}try{if(table!=='payments')wlv1CloseFollowUpsForDeletedMobile(mm)}catch(_e){}wlv1CloseNotice(id,'✅ Approved & deleted by '+(codeName(user.mobile)||user.mobile));toast('Approved — Deleted (Trash-এ আছে)');briefingHome();}catch(e){toast('মোছা গেল না — আবার চেষ্টা করুন');}}
function wlv1RejectDeleteNotice(id){if(!isMaster())return toast('Only Master Admin');wlv1CloseNotice(id,'❌ Delete Rejected by '+(codeName(user.mobile)||user.mobile));toast('Delete Rejected');briefingHome();}
window["wlv1ApproveDeleteNotice"]=wlv1ApproveDeleteNotice;window["wlv1RejectDeleteNotice"]=wlv1RejectDeleteNotice;

/* 🔵🔒 B618 (11.08.2026, TK-নির্দেশ): ছুটির অনুরোধ Approve/Reject (ওয়েব)। Master অথবা ওই
   ব্রাঞ্চের Doctor যেকোনো একজন। ডেটা wn schema-তে (module-auth), তাই MOD.autoSignIn()+MOD.client()
   দিয়ে wn.leave_requests আপডেট। Approve হলে notebook_days.is_leave + ব্রাঞ্চ-জুড়ে "Staff Leave"
   নোটিস (স্টাফের ফোন pending তারিখ দেখে confirmed পেলে WhatsApp জোর করে)। ⛔ Android-এর
   LeaveRepository-র হুবহু ধাপ; ব্যর্থ হলে কিছু ভাঙে না (try/catch, নোটিস অটুট থাকে)। */
async function wlv1ResolveLeaveNotice(id,approve){
  var b=briefings().find(function(x){return x.id===id;});
  if(!b)return toast('Notice not found');
  if(!wlv1CanApproveLeave(b))return toast('Only Master or Branch Doctor');
  var staff=wlv1NoticeField(b.message,'Staff');
  var date=wlv1NoticeField(b.message,'Leave date');
  var branch=wlv1NoticeField(b.message,'Branch');
  var reason=wlv1NoticeField(b.message,'Reason');
  if(!staff||!date)return toast('এই অনুরোধ থেকে Staff/তারিখ চেনা গেল না');
  try{
    try{await window.MOD.autoSignIn();}catch(_e){}
    var c=await window.MOD.client();
    if(!c)return toast('Net problem — try again');
    var now=new Date().toISOString();
    var st=approve?'confirmed':'rejected';
    var byMob=String((user&&user.mobile)||'').replace(/\D/g,'').slice(-10);
    var up=await c.schema('wn').from('leave_requests').update({status:st,decided_by:byMob,decided_at:now,updated_at:now}).eq('staff_code',staff).eq('leave_date',date);
    if(up&&up.error)return toast('করা গেল না — আবার চেষ্টা করুন');
    if(approve){
      try{
        var rr=await c.schema('wn').from('leave_requests').select('staff_mobile').eq('staff_code',staff).eq('leave_date',date).limit(1).maybeSingle();
        var smob=(rr&&rr.data&&rr.data.staff_mobile)||'';
        await c.schema('wn').from('notebook_days').upsert({staff_code:staff,staff_mobile:smob,work_date:date,is_leave:true,leave_reason:reason||'',updated_at:now},{onConflict:'staff_code,work_date'});
      }catch(_e){}
      try{
        var row={id:'brief_'+MOD.uuid().replace(/-/g,''),date:MOD.todayIST(),title:'Staff Leave',message:'Staff : '+staff+'\nBranch : '+branch+'\nLeave : '+date+'\nReason : '+(reason||''),targets:{branches:[branch]},seen:[],replies:[],hiddenFor:[],branch:branch,createdBy:byMob,createdAt:now,updatedAt:now};
        await cloudUpsertBriefing(row);
      }catch(_e){}
    }
    wlv1CloseNotice(id,(approve?'✅ Leave Approved':'❌ Leave Rejected')+' by '+(codeName(user.mobile)||user.mobile));
    toast(approve?'Leave Approved ✓':'Leave Rejected');
    briefingHome();
  }catch(e){toast('করা গেল না — আবার চেষ্টা করুন');}
}
function wlv1ApproveLeaveNotice(id){return wlv1ResolveLeaveNotice(id,true);}
function wlv1RejectLeaveNotice(id){return wlv1ResolveLeaveNotice(id,false);}
window["wlv1ApproveLeaveNotice"]=wlv1ApproveLeaveNotice;window["wlv1RejectLeaveNotice"]=wlv1RejectLeaveNotice;

/* 🔵🔒🔴 TK-অনুমোদিত (09.08.2026, শটলিস্ট #২-এর ৪র্থ অংশ, "সাবধানে"): Backdate পেমেন্ট
   অনুরোধ ওয়েবেও Approve — এটি **একটা নতুন পেমেন্ট (টাকা) তৈরি করে**, তাই ফোনের
   PaymentRepository.approveBackdateRequest-এর হুবহু ধাপ মিলিয়ে ওয়েবের নিজের payment-সেভ
   ঘর (saveTreatmentPayment লাইন 4590) ধরে বানানো হলো: (১) রোগী বের করা (patientRowId, নইলে
   মোবাইল শেষ-১০), (২) branch money-guard, (৩) বিল না থাকলে request.billAmount বসানো + stage,
   (৪) ওই backdate-তারিখে treatment payment তৈরি (payLabel = nextPaymentLabel(pid,date);
   backdateRequestedBy/backdateApprovedBy অডিট), (৫) ensureFollow, (৬) request='approved'।
   মোট/বকেয়া আগে থেকেই payments সারি গুনে বের হয়, তাই সারি যোগ হলেই ঠিক দেখাবে। */
async function wlv1ApproveBackdate(reqId){
  if(!isMaster())return toast('Only Master Admin');
  if(typeof sb==='undefined'||!sb)return toast('No internet connection');
  var req=null;
  try{var rr=await sb.from('payment_backdate_requests').select('*').eq('id',reqId).limit(1);if(rr&&rr.data&&rr.data[0])req=rr.data[0];}catch(e){}
  if(!req)return toast('অনুরোধ পাওয়া গেল না — আবার চেষ্টা করুন');
  if(String(req.status||'').toLowerCase()!=='pending')return toast('এই অনুরোধ আগেই প্রক্রিয়া হয়ে গেছে');
  function last10(s){return String(s||'').replace(/\D/g,'').slice(-10);}
  var p=load('patients').find(function(x){return String(x.id)===String(req.patientRowId);});
  if(!p)p=load('patients').find(function(x){return last10(x.mobile)===last10(req.mobile);});
  if(!p)return toast('রোগী পাওয়া গেল না — আগে সিঙ্ক করে আবার চেষ্টা করুন');
  if(typeof wlv1CanTakeMoney==='function'&&!wlv1CanTakeMoney(p))return toast(typeof wlv1MoneyBlockMsg==='function'?wlv1MoneyBlockMsg(p):'এই ব্রাঞ্চের টাকা নেওয়ার অনুমতি নেই');
  var amt=Number(req.amount||0);if(amt<=0)return toast('Amount ঠিক নেই');
  var billAmt=Number(req.billAmount||0);
  var payDate=String(req.requestedDate||'').slice(0,10)||today();
  if(!confirm('Approve backdated payment?\n\n'+(p.name||'')+'\n'+money(amt)+' · '+(req.mode||'CASH')+'\nDate: '+wlv1Dot(payDate)+'\n\n⚠️ ওই তারিখে টাকা আগে থাকলে সেটাতেই যোগ হবে; দ্বিতীয় payment row তৈরি হবে না।'))return;
  var now=new Date().toISOString();
  try{
    var patch={stage:p.stage||'Treatment Running',updatedAt:now};
    if(billAmt>0&&Number(p.bill||0)<=0)patch.bill=billAmt;
    var up=upd('patients',p.id,patch);
    var payLabel=nextPaymentLabel(p.id,payDate);
    var payRow=wlv1BuildTreatmentEventRow(p,amt,payMode(req.mode||'CASH'),payDate,payLabel,req.remarks||payLabel,{receivedBy:req.requestedBy||user.mobile,createdBy:req.requestedBy||user.mobile,backdateRequestedBy:req.requestedBy||'',backdateApprovedBy:user.mobile,updatedAt:now});
    var storedPay=wlv1UpsertDailyTreatmentLocal(payRow);
    var okP=true;try{okP=await directCloudUpsertRow('payments',storedPay||payRow);}catch(_e){okP=false;}
    if(!okP)return toast('Cloud-এ পেমেন্ট রাখা গেল না — আবার চেষ্টা করুন');
    try{ensureFollow(Object.assign({},p,up||{},{stage:'Treatment Running'}),'Treatment','','');}catch(_e){}
    try{await sb.from('payment_backdate_requests').update({status:'approved',approvedBy:user.mobile,approvedAt:now,updatedAt:now}).eq('id',reqId);}catch(_e){}
    toast('Approved — backdated payment created ✓');
    wlv1LoadApprovals();
  }catch(e){toast('Approve করা গেল না — আবার চেষ্টা করুন');}
}
window["wlv1ApproveBackdate"]=wlv1ApproveBackdate;

/* ==========================================================================
   TK-REQUESTED (2026-07-26): Chamber Attendance "Close Chamber (Save & Print
   Arrived)" for the web app, matching the native Android flow exactly:
     3 taps when an Arrived patient's Treatment box is empty ->
     branch pick (Master on "All Branch", when more than one branch has
     arrived patients, so the printed header belongs to ONE branch) ->
     REVIEW list -> Confirm & Print -> register print
     (SL | PATIENT | TREATMENT PROGRESS | VISIT | CASH | ONLINE + TOTAL).
   All names are wlv1-prefixed; no existing function is touched.
   ========================================================================== */
var wlv1CloseTapCount = 0, wlv1CloseTapAt = 0, wlv1ClosePrintBranch = '';

function wlv1ChamberArrivedRows(){
  const br = wlv1ChamberBranch || (user && user.branch==='All' ? 'All' : (user?user.branch:''));
  return wlv1ChamberRows(wlv1ChamberDate, br).filter(r=>r.arrived);
}
window["wlv1ChamberArrivedRows"]=wlv1ChamberArrivedRows;

function wlv1CloseChamber(){
  const arrived = wlv1ChamberArrivedRows();
  // 🔵 B607 parity (Android warn+allow): আগে Arrived 0 হলে একদম আটকাত। এখন
  // রোগীশূন্য দিনও দরকারে বন্ধ করা যায় — কিন্তু ভুলে বন্ধ ঠেকাতে নিশ্চিতকরণ।
  // ⛔ ফাঁকা রেজিস্টার প্রিন্ট নয় — শুধু বন্ধ-চিহ্ন (chamber_close) বসে।
  /* 🔴 V430 — লেখাটা ফোনের হুবহু ("Nobody arrived today (Arrived 0). Still
     close the chamber?") — আগে ওয়েবে "আজ" শব্দটা বাদ পড়ে গিয়েছিল। */
  if(!arrived.length){
    if(!confirm('Nobody arrived today (Arrived 0). Still close the chamber?')) return;
    const br = (wlv1ChamberBranch && wlv1ChamberBranch!=='All') ? wlv1ChamberBranch
      : (((user&&user.branch)&&user.branch!=='All') ? user.branch : C.defaultBranch);
    try{ wlv1MarkChamberClosed(br, wlv1ChamberDate); }catch(e){}
    toast('The chamber is closed');
    try{ chamberAttendance(); }catch(e){}
    return;
  }
  const now = Date.now();
  if(now - wlv1CloseTapAt > 60000) wlv1CloseTapCount = 0;
  const missing = arrived.find(r=>wlv1EffectivelyBlankRemark(r.treatment));
  if(missing && wlv1CloseTapCount < 2){
    wlv1CloseTapCount++; wlv1CloseTapAt = now;
    /* 🔴 V430 — ফোনের হুবহু লেখা, আর ফোনের মতোই সঙ্গে সঙ্গে লেখার বাক্সটাও
       খুলে যায় (ChamberAttendanceActivity.kt:2333-2340) — যাতে ওখানেই ঠিক
       করে নেওয়া যায়, খুঁজতে না হয়। */
    toast('⚠️ '+String(missing.name||missing.mobile)+"'s Treatment box is empty — tap Close "+(3-wlv1CloseTapCount)+' more time(s) to save anyway');
    try{ wlv1ChamberWriteTreatment(missing.mobile); }catch(e){}
    return;
  }
  wlv1CloseTapCount = 0;
  wlv1ClosePrintBranch = '';
  const branches = [...new Set(arrived.map(r=>String(r.branch||'').trim()).filter(Boolean))].sort();
  const onAll = (wlv1ChamberBranch||'All')==='All';
  if(!onAll || branches.length<=1){
    if(onAll && branches.length===1) wlv1ClosePrintBranch = branches[0];
    return wlv1CloseReview(arrived);
  }
  const list = branches.map(b=>{
    const n = arrived.filter(r=>String(r.branch||'').trim()===b).length;
    return `<button class="wlv1CbPickBranch" onclick="wlv1ClosePrintBranch='${esc(b)}';closeModal();wlv1CloseReview(wlv1ChamberArrivedRows().filter(r=>String(r.branch||'').trim()==='${esc(b)}'))"><b>${esc(b.toUpperCase())}</b><span>${n} people</span></button>`;
  }).join('');
  /* 🔴 V430 — শিরোনামটা ফোনের হুবহু, আর সংখ্যার পাশে ফোনের মতোই "people"। */
  modal(`<h2>Which branch's register will be printed?</h2><div class="wlv1CbPickWrap">${list}</div><button class="ghost" onclick="closeModal()">Cancel</button>`);
}
window["wlv1CloseChamber"]=wlv1CloseChamber;

function wlv1CloseReview(rows){
  if(!rows || !rows.length) return toast('Nobody has been marked Arrived yet');
  /* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — Review পর্দার সারিও ফোনের মতোই **যে যখন
     এসেছেন** সেই ক্রমে (ChamberAttendanceActivity.kt:2505)। তাই পর্দায় যে
     ক্রমে দেখছেন, ছাপা কাগজেও ঠিক সেই ক্রমেই যাবে। */
  rows = wlv1ByArrivalOrder(rows);
  const rupee = v => Number(v||0)>0 ? '₹'+Number(v).toLocaleString('en-IN') : '—';
  /* 🔴 V429 (TK-নির্দেশ: ওয়েব হুবহু অ্যান্ড্রয়েডের মতো) — ফোনের Review পর্দায়
     সারিগুলো **৫ কলামের গ্রিড**: PATIENT · TREATMENT PROGRESS · FEES · CASH ·
     ONLINE (ChamberAttendanceActivity-র rvCell ধরে ধরে মেলানো: নাম-ঘর ৮২dp,
     টাকার তিনটে ৪০dp, মাঝেরটা বাকিটুকু; হেডার সবুজাভ #0E7C7B, সারি #EAF9F1)।
     ওয়েবে এতদিন দুই ভাগের সারি ছিল — এখন মিলিয়ে দেওয়া হলো।
     ⛔ তথ্য/হিসাব একটুও বদলায়নি, শুধু সাজ। */
  const list = '<div class="cbRevGrid">' +
    '<div class="cbRevHd">PATIENT</div><div class="cbRevHd">TREATMENT PROGRESS</div>' +
    '<div class="cbRevHd">FEES</div><div class="cbRevHd">CASH</div><div class="cbRevHd">ONLINE</div>' +
    /* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — ফোনের Review পর্দায় ঘরগুলো **চাপা যায়**
       (ChamberAttendanceActivity.kt:2694-2735): নাম চাপলে রোগীর বিবরণ,
       চিকিৎসার ঘর চাপলে লেখা ঠিক করা, টাকার ঘর চাপলে টাকা ঠিক করা।
       ওয়েবে পাঁচটা ঘরই নিষ্ক্রিয় ছিল — Review ধাপটার মানেই থাকত না। */
    rows.map(r=>`<div class="cbRevNm" style="cursor:pointer" onclick="closeModal();wlv1ChamberPatientChoices('${esc(r.mobile)}')"><b>${esc(String(r.name||r.mobile).toUpperCase())}</b><span>&#128222; ${esc(shownMob(r.mobile))}</span>${r.patientId?`<span>&#127380; ${esc(r.patientId)}</span>`:''}</div>`
      /* 🔴 V429 — চিকিৎসার ঘরটা এখন হুবহু ফোনের মতো: কিছু লেখা না থাকলে "—",
         আর সিস্টেমের নিজের বসানো লেখা হলে "Nothing written — tap to add",
         দুটোই হালকা কমলা (#C47B00)। আগে ওয়েবে লাল "Progress not written"
         দেখাত — ফোনে কখনোই ওটা ছিল না। ⛔ ছাপা কাগজের লেখা অপরিবর্তিত। */
      /* 🔴 V430 — পর্দায় স্টাফের লেখা **হুবহু** দেখানো হয় (ফোনে
         ChamberAttendanceActivity.kt:2719)। ইংরেজি করার নিয়মটা ফোনে শুধু
         **ছাপা কাগজে** চলে, পর্দায় নয় — ওয়েবে ভুল করে পর্দাতেও চলছিল। */
      + `<div class="cbRevTr${wlv1EffectivelyBlankRemark(r.treatment)?' cbRevTrEmpty':''}" style="cursor:pointer" onclick="closeModal();wlv1ChamberWriteTreatment('${esc(r.mobile)}')">${
          !wlv1EffectivelyBlankRemark(r.treatment) ? esc(String(r.treatment||'').trim())
          : (String(r.treatment||'').trim() ? 'Nothing written &#8212; tap to add' : '&#8212;')}</div>`
      + `<div class="cbRevF" style="cursor:pointer" onclick="closeModal();wlv1ChamberFixPayment('${esc(r.mobile)}')">${rupee(r.fee)}</div><div class="cbRevC" style="cursor:pointer" onclick="closeModal();wlv1ChamberFixPayment('${esc(r.mobile)}')">${rupee(r.cash)}</div><div class="cbRevO" style="cursor:pointer" onclick="closeModal();wlv1ChamberFixPayment('${esc(r.mobile)}')">${rupee(r.online)}</div>`
    ).join('') + '</div>';
  /* 🔴🔒 V426 (TK-নির্দেশ ১৭.০৮.২০২৬: "review পর্দাতে উপরে যে ডেমি লেখা আছে সেগুলি
     থাকবে না · সেখানে কত পরিমান টাকা জমা হয়েছে সেগুলো থাকবে") — নির্দেশ-লাইনটা
     তুলে দেওয়া হলো, জায়গায় আজকের টাকার হিসাব। TOTAL = Fees + Cash + Online
     (TK-অনুমোদিত)। ⛔ সংখ্যাগুলো নিচের সারির **ঠিক সেই একই ঘর** (r.fee/r.cash/
     r.online) থেকেই যোগ হয়, তাই সারি আর মোট কখনো আলাদা হবে না। ফোনের
     ChamberAttendanceActivity.showCloseReview-এর হুবহু একই হিসাব। */
  const __fT=rows.reduce((a,r)=>a+Number(r.fee||0),0), __cT=rows.reduce((a,r)=>a+Number(r.cash||0),0),
        __oT=rows.reduce((a,r)=>a+Number(r.online||0),0), __gT=__fT+__cT+__oT;
  const rs = v => '₹'+Number(v||0).toLocaleString('en-IN');
  modal(`<h2>REVIEW — ${rows.length} arrived</h2>
    <div class="wlv1CbRevSum"><div><span>Fees</span><b>${rs(__fT)}</b></div><div><span>Cash</span><b class="c">${rs(__cT)}</b></div><div><span>Online</span><b class="o">${rs(__oT)}</b></div><div class="tot"><span>TOTAL</span><b>${rs(__gT)}</b></div></div>
    <div class="wlv1CbRevWrap">${list}</div>
    <div class="actions"><button class="ghost" onclick="closeModal()">Back</button>
    <button onclick="closeModal();wlv1ChamberRegisterPrint()">&#9989; Confirm &amp; Print</button></div>`);

  /* 🔴🔒 V426/V427 (TK-নির্দেশ ১৭.০৮.২০২৬) — RMP কমিশন ও "আজ কত দিলাম"।
     ⛔ হিসাব পুরোটাই সার্ভারে (`fin.rmp_day_commission` · `fin.rmp_day_paid`) —
        ফোনের ChamberAttendanceActivity-র সঙ্গে হুবহু একই সংখ্যা।
     ⛔ পর্দা আগেই দেখানো হয়ে গেছে; তথ্য এলে শুধু **যোগ** হয়। ডাক ব্যর্থ হলে বা
        RMP-রোগী না থাকলে পর্দা হুবহু আগের মতোই — কিছুই ভাঙে না।
     ⛔ TK-এর সিদ্ধান্ত "ক": **NET TOTAL থেকে বাদ যায় শুধু আজকের প্রাপ্য কমিশন**।
        "PAID TO RMP TODAY" শুধু জানার জন্য, কোনো মোট থেকে বাদ যায় না। */
  (async function(){
    try{
      /* 🔴 V430 — ফোনের মতোই: চেম্বারে "All Branch" বাছা থাকলে **নিজের
         ব্রাঞ্চ** ধরে কমিশন দেখানো হয় (ChamberAttendanceActivity.kt:2803)।
         আগে ওয়েবে All Branch-এ কমিশনের ঘরটাই আসত না, আর কাগজের নিচের
         লাইনেও RMP Commission / NET চুপচাপ হারিয়ে যেত। */
      var br = (typeof wlv1ChamberBranch!=='undefined' && wlv1ChamberBranch) ? wlv1ChamberBranch : '';
      if(!br || br==='All') br = (user&&user.branch)||'';
      if(!br || br==='All') return;
      if(typeof window.wlv1RmpDayCommission!=='function') return;
      var dt = String(wlv1ChamberDate||'').slice(0,10);
      var comm = await window.wlv1RmpDayCommission(br, dt);
      var paid = await window.wlv1RmpDayPaid(br, dt);
      comm = (comm||[]).filter(function(x){ return Number(x.commission_today||0) > 0; });
      paid = (paid||[]).filter(function(x){ return Number(x.total_paid||0) > 0; });
      window.__wlv1DayCommission = comm.reduce(function(a,x){ return a+Number(x.commission_today||0); },0);
      window.__wlv1DayPaidRmp   = paid.reduce(function(a,x){ return a+Number(x.total_paid||0); },0);
      var box = document.querySelector('.wlv1CbRevSum'); if(!box) return;
      var html='';
      if(comm.length){
        // 🔴🔒 V484 (20.08.2026, Android V473-এর সাথে ওয়েব মেলাতে — TK-নির্দেশ
        // "Android ও ওয়েব দুটোতেই মিলিয়ে দেখুন") — RMP Commission-এর প্রতি-লাইন
        // ও NET TOTAL আগে `rs()` (পূর্ণসংখ্যায় গোল করা) ব্যবহার করত, তাই ₹2.50
        // কমিশন ₹3 দেখাত — ঠিক Android-এ যে বাগ ছিল সেটাই। এখন দশমিকসহ নতুন
        // `rs2()` — শুধু এই দুই জায়গায়; Fees/Cash/Online/TOTAL (উপরের `rs()`)
        // এক অক্ষরও বদলায়নি (আগের মতোই পূর্ণসংখ্যা)।
        var rs2 = v => '₹'+Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
        var byRmp={}; comm.forEach(function(x){
          var k=String(x.rmp_name||x.rmp_id||''); if(!byRmp[k]) byRmp[k]={n:0,a:0};
          byRmp[k].n++; byRmp[k].a+=Number(x.commission_today||0); });
        html += '<div class="cbRevHead cbRevRed">RMP COMMISSION</div>';
        Object.keys(byRmp).forEach(function(k){
          html += '<div><span>'+esc(k)+' ('+byRmp[k].n+')</span><b class="r">− '+rs2(byRmp[k].a)+'</b></div>'; });
        html += '<div class="tot"><span>NET TOTAL</span><b>'+rs2(__gT - window.__wlv1DayCommission)+'</b></div>';
      }
      if(paid.length){
        html += '<div class="cbRevHead">PAID TO RMP TODAY</div>';
        paid.forEach(function(x){
          html += '<div><span>'+esc(String(x.rmp_name||x.rmp_id||''))+'</span><b>'+rs(x.total_paid)+'</b></div>'; });
      }
      if(html) box.insertAdjacentHTML('beforeend', html);
      // RMP-র রোগীর সারিতে ছোট্ট "RMP" চিহ্ন (TK-নির্দেশ)
      var marks={}; (comm||[]).forEach(function(x){
        marks[String(x.patient_mobile||'').replace(/\D/g,'').slice(-10)]=1; });
      document.querySelectorAll('.cbRevNm').forEach(function(cell){
        var t=(cell.innerText||'').replace(/\D/g,'');
        Object.keys(marks).forEach(function(m){
          if(m && t.indexOf(m)>=0 && !cell.querySelector('.cbRmpTag')){
            var b=cell.querySelector('b'); if(b) b.insertAdjacentHTML('beforebegin','<span class="cbRmpTag">RMP</span> ');
          }
        });
      });
    }catch(_e){}
  })();
}
window["wlv1CloseReview"]=wlv1CloseReview;

/* TK'S RULE (2026-07-27): the phone now reminds a staff from 7 PM until the
   chamber is closed. So closing it here, on the computer, must switch that
   reminder off for the whole branch too -- it writes the same one small row
   (chamber_close) the phone writes. Printing itself is untouched, and if the
   line is down the print still happens exactly as before. */
/* 🔴🔒 V425 (TK-নির্দেশ ১৭.০৮.২০২৬: *"আমি মাস্টার আবার আমাকে কেন অনুমতি নিতে হবে"*)
   ফোনে Master এখন নিজেই চেম্বার খোলেন। ওয়েবে এতদিন **খোলার কোনো পথই ছিল না** —
   একমাত্র উপায় ছিল স্টাফের পাঠানো "reopen request" নোটিশে Approve চাপা।
   ⛔ এখানে নতুন কোনো নিয়ম বানানো হয়নি — নিচের কাজটা `wlv1ApproveReopenNotice`
      ভিতরে যা করে **হুবহু সেই একই তিনটে ধাপ**: (১) ক্লাউড থেকে chamber_close
      সারিটা মোছা, (২) ফোনের/ব্রাউজারের নিজের কপি থেকেও বাদ, (৩) পর্দা রিফ্রেশ।
   ⛔ শুধু Master — স্টাফ/ডাক্তারের জন্য আগের নিয়ম (অনুরোধ → অনুমোদন) অটুট।
   ⛔ ক্লাউডে মুছতে না পারলে **লোকাল কপিতেও হাত পড়ে না** — নইলে এক জায়গায় খোলা
      আর আরেক জায়গায় বন্ধ হয়ে হিসাব গোলমাল হতে পারত। */
async function wlv1MasterReopenChamber(){
  if(!isMaster())return toast('Only Master Admin');
  var br=(typeof wlv1ChamberBranch!=='undefined'&&wlv1ChamberBranch)?wlv1ChamberBranch:((user&&user.branch)||'');
  var date=String(wlv1ChamberDate||'').slice(0,10);
  if(!br||br==='All'||!date)return toast('Branch/Date পাওয়া গেল না');
  if(!confirm('এই দিনের ('+wlv1Dot(date)+', '+br+') চেম্বার আবার খুলবেন?'))return;
  var closeId=String(br).trim().toUpperCase()+'|'+date;
  try{
    var gone=true;
    if(typeof sb!=='undefined'&&sb){gone=await wlv1CloudDeleteRow('chamber_close',closeId);}
    if(!gone)return toast('Cloud-এ reopen করা গেল না — আবার চেষ্টা করুন');
    try{save('chamber_close',(load('chamber_close')||[]).filter(function(r){return r&&String(r.id)!==closeId;}),{skipCloud:true,skipBackup:true});}catch(_e){}
    toast('চেম্বার আবার খোলা হলো ✓');
    chamberAttendance();
  }catch(e){ toast('খোলা গেল না — আবার চেষ্টা করুন'); }
}
window["wlv1MasterReopenChamber"]=wlv1MasterReopenChamber;
async function wlv1MarkChamberClosed(branch, date){
  try{
    if(!branch || !date) return;
    const closeId = String(branch).trim().toUpperCase()+'|'+date;
    // 🔴 B303 (02.08.2026): শুধু ক্লাউডে লিখলে **এই কম্পিউটারও** সেটা সাথে
    // সাথে জানতে পারে না (Delete-বোতামের চেক লোকাল ক্যাশ পড়ে) — তাই এখানেও
    // লোকালে সেভ করা হলো, ঠিক প্রজেক্টের বাকি সব লেখার মতোই। অন্য
    // কম্পিউটার/ফোন থেকে বন্ধ করলে সেটা এখনো এই ডিভাইসে সাথে সাথে জানা
    // যাবে না (নেট-কল ছাড়া) — সেটা এই ছোট ফিক্সের বাইরে, আলাদা কাজ লাগবে।
    try{
      const local = load('chamber_close')||[];
      if(!local.some(r=>r && String(r.id)===closeId)){
        local.push({id:closeId, branch:String(branch).trim().toUpperCase(), date:date,
          closedBy:(user&&user.mobile)||'', closedByName:(user&&user.name)||'',
          closedAt:new Date().toISOString(), createdAt:new Date().toISOString(), updatedAt:new Date().toISOString()});
        save('chamber_close', local, {skipCloud:true, skipBackup:true});
      }
    }catch(_e){}
    if(typeof sb==='undefined' || !sb) return;
    const now = new Date().toISOString().slice(0,19).replace('T',' ');
    await sb.from('chamber_close').upsert({
      id: closeId,
      branch: String(branch).trim().toUpperCase(),
      date: date,
      closedBy: (user&&user.mobile)||'',
      closedByName: (user&&user.name)||'',
      closedAt: now, createdAt: now, updatedAt: now
    });
  }catch(e){ /* never block the print */ }
}
window["wlv1MarkChamberClosed"]=wlv1MarkChamberClosed;

function wlv1ChamberRegisterPrint(){
  let rows = wlv1ChamberArrivedRows();
  const pickBr = wlv1ClosePrintBranch;
  if(pickBr) rows = rows.filter(r=>String(r.branch||'').trim()===pickBr);
  if(!rows.length) return toast('Nobody has been marked Arrived yet');
  /* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — কাগজের ক্রম এখন ফোনের মতোই **যে যখন
     এসেছেন** (ChamberAttendanceActivity.kt:3300-3302)। আগে ওয়েবে নামের
     অক্ষর-ক্রমে ছাপা হত, তাই কাগজটা আসল খাতার মতো পড়া যেত না। */
  rows = wlv1ByArrivalOrder(rows);
  const brName = pickBr || String(rows[0].branch||(user?user.branch:'')||'');
  try{ wlv1MarkChamberClosed(brName, wlv1ChamberDate) }catch(e){}
  const rupee = v => Number(v||0)>0 ? '₹'+Number(v).toLocaleString('en-IN') : '—';
  const dateLabel = wlv1Dot(wlv1ChamberDate);
  let dayLabel = '';
  try{ dayLabel = new Date(wlv1ChamberDate+'T00:00:00').toLocaleDateString('en-US',{weekday:'long'}); }catch(e){ dayLabel=''; }
  let tFee=0,tCash=0,tOnline=0;
  const body = rows.map((r,i)=>{
    tFee+=Number(r.fee||0); tCash+=Number(r.cash||0); tOnline+=Number(r.online||0);
    /* 🔴 V430 (TK-নির্দেশ) — ফোনের হুবহু নিয়ম:
       · ফি জমা পড়লে সেই ঘরে **কোন উপায়ে** জমা পড়েছে তাই লেখা হয় —
         নগদে হলে CASH, অনলাইনে হলে UPI (আগে ওয়েবে সবসময় CASH লেখা হত)।
       · ফি না থাকলে **কত নম্বর ভিজিট** সেটা লেখা হয় (আগে সবসময় OLD)। */
    const visitCell = Number(r.fee||0)>0
      ? `${Number(r.feeOnline||0)>0 && !(Number(r.feeCash||0)>0) ? 'UPI' : 'CASH'}<br>${rupee(r.fee)}`
      : esc(wlv1ChamberVisitLabel(r, wlv1ChamberDate));
    /* 🔴 V430 — নতুন রোগীর সারি হালকা সবুজ, পুরনো হালকা ধূসর (ফোনের কাগজের
       মতোই), আর মোবাইল-লাইন নীল ও আইডি-লাইন ধূসর — দুটো আলাদা রং। */
    return `<tr class="${r.isNewToday?'cbRowNew':'cbRowOld'}"><td class="cbSl">${i+1}</td>
      <td class="cbPat"><b>${esc(String(r.name||r.mobile).toUpperCase())}</b>
        <div class="cbSub">Mob: ${esc(shownMob(r.mobile))}</div>
        ${r.patientId?`<div class="cbSubId">ID: ${esc(r.patientId)}</div>`:''}</td>
      <td class="cbTreat">${!wlv1EffectivelyBlankRemark(r.treatment)?esc(wlv1PrintEn(r.treatment)):'⚠️ PROGRESS PENDING'}</td>
      <td class="cbVisit">${visitCell}</td>
      <td class="cbMoney">${rupee(r.cash)}</td>
      <td class="cbMoney">${rupee(r.online)}</td></tr>`;
  }).join('');
  app().innerHTML = `<div class="noPrint printReturnBar"><button class="ghost" onclick="chamberAttendance()">← Chamber</button><button class="ghost" onclick="webPdfShare()">📄 PDF / Share</button><button class="ghost" onclick="wlv1Share('Chamber Register', wlv1ChamberRegisterText())">Text</button><button onclick="doPrintNow()">Print</button></div>`
    + printHead({branch:brName}, '')
    /* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — ফোনের কাগজে "CHAMBER REGISTER — তারিখ"
       নামে চওড়া কোনো ব্যান্ড নেই; শুধু **উপরে ডান কোণে ছোট করে সবুজ তারিখ ও
       বার** থাকে (ChamberRegisterPdfBuilder.kt:162-166)। ওয়েবের বাড়তি
       ব্যান্ডটা তুলে দিয়ে ফোনের মতোই বসানো হলো। */
    + `<div class="cbRegDateDay">${esc(dateLabel)}${dayLabel?'  ('+esc(dayLabel)+')':''}</div>
       <table class="wlv1CbRegTable"><thead><tr>
         <th>SL</th><th>PATIENT</th><th>TREATMENT PROGRESS</th><th>VISIT</th><th>CASH</th><th>ONLINE</th>
       </tr></thead><tbody>${body}
       <tr class="cbTotal"><td></td><td>TOTAL</td><td></td><td>${rupee(tFee)}</td><td>${rupee(tCash)}</td><td>${rupee(tOnline)}</td></tr>
       </tbody></table>
       <!-- 🔴🔒 V426 (TK-নির্দেশ ১৭.০৮.২০২৬: "প্রিন্ট আউট হয়ে যাওয়ার পরে একদম নিচে
            থাকবে · সব গুলি একলাইনে থাকতে হবে") — কাগজের একদম নিচে একটাই লাইনে পুরো
            হিসাব। TOTAL = Fees + Cash + Online (TK-অনুমোদিত)। ⛔ উপরের TOTAL সারি ও
            কলামের অঙ্ক একটুও বদলায়নি; ফোনের ChamberRegisterPdfBuilder-এর একই লাইন। -->
       <div class="cbRegOneLine">${(function(){
          var g=Number(tFee||0)+Number(tCash||0)+Number(tOnline||0);
          var cm=Number(window.__wlv1DayCommission||0), pd=Number(window.__wlv1DayPaidRmp||0);
          var n=v=>'₹'+Number(v||0).toLocaleString('en-IN');
          /* 🔴 V426/V427: Review পর্দায় দেখানো ঠিক সেই সংখ্যাগুলোই কাগজে যায় —
             আলাদা করে আবার হিসাব করা হয় না, তাই পর্দা ও কাগজ কখনো আলাদা হবে না।
             ⛔ NET থেকে বাদ যায় শুধু আজকের প্রাপ্য কমিশন; "Paid to RMP today"
                শুধু জানার জন্য, কোনো মোট থেকে বাদ যায় না। ০ হলে লেখাই হয় না। */
          var t = 'Fees '+n(tFee)+' &nbsp;·&nbsp; Cash '+n(tCash)+' &nbsp;·&nbsp; Online '+n(tOnline)+' &nbsp;·&nbsp; TOTAL '+n(g);
          if(cm>0) t += ' &nbsp;·&nbsp; RMP Commission − '+n(cm)+' &nbsp;·&nbsp; NET '+n(g-cm);
          if(pd>0) t += ' &nbsp;·&nbsp; Paid to RMP today '+n(pd);
          return t+'/-';
        })()}</div>
       </div>`;
  /* 🔴 V430 — ফোনে কাগজ তৈরি হলে কোনো কালো বার্তা দেখায় না, সোজা প্রিভিউ খোলে।
     TK-এর নিয়ম "পর্দায় নির্দেশ-লাইন থাকবে না" — তাই বার্তাটা তুলে দেওয়া হলো। */
}
window["wlv1ChamberRegisterPrint"]=wlv1ChamberRegisterPrint;

/* TK-REQUESTED (2026-07-26): web parity with the native "Payment Amount Edit"
   approval workflow. A staff member who tries to correct an entry older than
   yesterday is no longer only blocked . they can send the correction to the
   Master, exactly like on the phone (PaymentRepository.requestPaymentEdit).
   The Master already approves/rejects these on the Briefing screen. */
function wlv1AskMasterPaymentEdit(id){
  const x = load('payments').find(p=>p.id===id);
  if(!x) return toast('Payment not found');
  modal(`<h2>Ask Master to correct this payment</h2>
    <b>${esc(x.name||'')}</b><br><span class="mut">${esc(normMob(x.mobile||''))} · ${esc(x.branch||'')} · ${esc(fmtDate(x.date||''))}</span>
    <div class="tiny mut">Only Master can edit entries older than yesterday. Send the correction for approval.</div>
    <label>Current Amount</label><input class="input" value="${Number(x.amount||0)}" readonly>
    <label>Correct Amount</label><input id="wlv1ReqAmt" class="input" inputmode="numeric" value="${Number(x.amount||0)}">
    <label>Reason</label><textarea id="wlv1ReqWhy" placeholder="Why does this need correcting?"></textarea>
    <button onclick="wlv1SendPaymentEditRequest('${esc(id)}')">Send to Master</button>`);
}
window["wlv1AskMasterPaymentEdit"]=wlv1AskMasterPaymentEdit;

async function wlv1SendPaymentEditRequest(id){
  const x = load('payments').find(p=>p.id===id);
  if(!x) return toast('Payment not found');
  const amt = Number((document.getElementById('wlv1ReqAmt')||{}).value||0);
  const why = String((document.getElementById('wlv1ReqWhy')||{}).value||'').trim();
  if(!(amt>0)) return toast('Enter the correct amount');
  if(typeof sb==='undefined' || !sb) return toast('No internet connection');
  const nowIso = new Date().toISOString();
  const row = {
    id:'editreq_'+Math.random().toString(36).slice(2)+Date.now().toString(36),
    paymentId:x.id, patientRowId:x.patientRowId||'', patientCode:x.patientId||'',
    mobile:normMob(x.mobile||''), name:x.name||'', branch:x.branch||'',
    oldAmount:Number(x.amount||0), newAmount:amt, mode:payMode(x.mode)||'CASH',
    paymentDate:x.date||'', reason:why,
    requestedBy:(user&&user.mobile)||'', requestedByName:(user&&user.name)||((user&&user.mobile)||''),
    requestedAt:nowIso, status:'pending', createdAt:nowIso, updatedAt:nowIso
  };
  try{
    const {error} = await sb.from('payment_edit_requests').insert(row);
    if(error) return toast('Could not send — try again');
    closeModal();
    toast('Sent to Master for approval');
  }catch(e){ toast('Could not send — try again'); }
}
window["wlv1SendPaymentEditRequest"]=wlv1SendPaymentEditRequest;

/* ==========================================================================
   TK-REQUESTED (2026-07-26): "Full Journey" table for the web app, matched to
   the native Patient Timeline: Date/Time | Type / By | Note, with a call
   logged outside 9am-6pm shown in red (native isUnexpectedHour: hour < 9 ||
   hour >= 18; payments are never flagged). Oldest first, like the register.
   The existing "Patient Progress" table is left untouched.
   ========================================================================== */
function wlv1IsUnexpectedHour(iso){
  const s = String(iso||'');
  const m = s.match(/T(\d{2}):(\d{2})/);
  if(!m) return false;
  const h = parseInt(m[1],10);
  if(isNaN(h)) return false;
  return h < 9 || h >= 18;
}
window["wlv1IsUnexpectedHour"]=wlv1IsUnexpectedHour;

function wlv1JourneyRows(p){
  const m = mob(p.mobile);
  const d10 = v => String(v||'').slice(0,10);
  const out = [];
  const reg = d10(p.registrationDate || p.date);
  if(reg) out.push({date:reg, time:'', type:'Registration',
                    by:p.registeredBy||p.createdBy||'', note:[p.disease,p.branch].filter(Boolean).join(' · '), pay:false});
  load('enquiries').filter(e=>mob(e.mobile)===m).forEach(e=>{
    out.push({date:d10(e.date), time:e.createdAt||'', type:'Enquiry',
              by:e.callReceivedBy||e.createdBy||'', note:String(e.remarks||''), pay:false});
  });
  load('followups').filter(f=>mob(f.mobile)===m).forEach(f=>{
    (f.history||[]).forEach(h=>{
      out.push({date:d10(h.date), time:h.at||h.createdAt||h.date||'',
                type:(f.stage||'Follow-up')+' Call', by:h.staff||'',
                note:String(h.remark||''), pay:false});
    });
  });
  /* 🔵🔒 V520: `payOwnedBy` নিজেই এখন মোবাইল-fallback সামলায় ও দুই রোগীর টাকা আলাদা রাখে — তাই এখানকার বাড়তি কাঁচা মোবাইল-মিলটা সরানো হয়েছে (নইলে ওই সুরক্ষা ফাঁকি দিয়ে যেত)। ⛔ এক রোগী হলে ফলাফল অবিকল আগের মতোই, কারণ payOwnedBy ওই ক্ষেত্রে মোবাইল মিললেই true বলে। */
  wlv1MergeDailyTreatmentRows(load('payments').filter(x=>payOwnedBy(x,p))).forEach(x=>{
    const amt = Number(x.amount||0);
    if(!(amt>0)) return;
    const sp=wlv1PaymentSplit(x),modeText=sp.cash>0&&sp.online>0?'Cash + Online':(sp.online>0?'Online':'Cash');
    out.push({date:d10(x.date), time:x.createdAt||'',
              type:(typeof collectionPaymentLabel==='function'?collectionPaymentLabel(x):'Payment'),
              by:x.receivedBy||x.createdBy||'',
              note:[money(amt), modeText, x.remarks||''].filter(Boolean).join(' · '),
              pay:true});
  });
  load('medical').filter(x=>p.id && x.patientId===p.id).forEach(x=>{
    out.push({date:d10(x.date), time:x.createdAt||'', type:String(x.type||'Record'),
              by:x.createdBy||'', note:String(x.decision||x.selected||x.details||''), pay:false});
  });
  /* 🟢🔒 B681 (১৫.০৮.২০২৬, TK-অনুমোদিত) — **একই কথা আর দু'বার উঠবে না** (কম্পিউটারেও)।
     ফোনে সারানো হয়েছে (B680); কম্পিউটারেও হুবহু একই দোষ ছিল — Enquiry-র `remarks` আর
     Follow-up-এর `history`-র একই লেখা দুটো আলাদা সারিতে উঠত, এখানে কোনো মেলানোই ছিল না।
     **নিয়ম (ফোনের মতোই):** একই তারিখে একই লেখা হলে একবারই; যেটায় সময় আছে সেটাই থাকে।
     ⛔ টাকার সারি (pay:true) কখনো মেলানো হয় না — একই দিনে একই অঙ্কের দুটো সত্যিকারের
        পেমেন্ট থাকতেই পারে, সেগুলো আলাদাই থাকবে।
     ⛔ লেখা ফাঁকা হলে মেলানো হয় না (নইলে "Registration" সারিটাই হারাত)। */
  const seenNote = {};
  const deduped = [];
  out.forEach(function(r){
    const note = String(r.note||'').trim();
    if(r.pay || !note){ deduped.push(r); return; }
    const key = String(r.date||'').slice(0,10) + '|' + note.toLowerCase();
    const at = seenNote[key];
    if(at === undefined){ seenNote[key] = deduped.length; deduped.push(r); return; }
    if(!deduped[at].time && r.time) deduped[at] = r;
  });
  return deduped.filter(r=>r.date).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
}
window["wlv1JourneyRows"]=wlv1JourneyRows;

function wlv1StaffNameOf(mobileOrName){
  const v = String(mobileOrName||'').trim();
  if(!v) return '';
  const d = mob(v);
  if(!d) return v;
  try{
    const u = (typeof allUsers==='function'? allUsers(): []).find(x=>mob(x.mobile)===d);
    if(u && u.name) return String(u.name);
  }catch(e){}
  return v;
}
window["wlv1StaffNameOf"]=wlv1StaffNameOf;

function wlv1FullJourneyTable(p){
  const rows = wlv1JourneyRows(p);
  if(!rows.length) return '<div class="card mut">No update yet</div>';
  const body = rows.map(r=>{
    const t = r.time ? wlv1Ampm(String(r.time).slice(11,16)) : '';
    const red = !r.pay && wlv1IsUnexpectedHour(r.time);
    const by = wlv1StaffNameOf(r.by);
    return `<div class="wlv1FjRow">
      <div class="wlv1FjCell wlv1FjWhen"><b>${esc(fmtDate(r.date))}</b>
        ${t?`<span class="${red?'wlv1FjRed':''}">${esc(t)}</span>`:''}</div>
      <div class="wlv1FjCell wlv1FjType"><b>${esc(r.type)}</b>
        <span>By: ${esc(by||'—')}</span></div>
      <div class="wlv1FjCell wlv1FjNote">${esc(r.note||'—')}</div></div>`;
  }).join('');
  return `<div class="wlv1Fj"><div class="wlv1FjHead">
      <div class="wlv1FjCell wlv1FjWhen">Date/Time</div>
      <div class="wlv1FjCell wlv1FjType">Type / By</div>
      <div class="wlv1FjCell wlv1FjNote">Note</div></div>${body}</div>`;
}
window["wlv1FullJourneyTable"]=wlv1FullJourneyTable;

function wlv1FullJourney(idOrMobile){
  const list = load('patients');
  let p = list.find(x=>x.id===idOrMobile) || list.find(x=>mob(x.mobile)===mob(idOrMobile));
  if(!p){
    const f = load('followups').find(x=>mob(x.mobile)===mob(idOrMobile))
           || load('enquiries').find(x=>mob(x.mobile)===mob(idOrMobile));
    if(!f) return page('Full Journey','<div class="card redP">Patient not found</div>');
    p = {id:'', mobile:f.mobile, name:f.name, branch:f.branch, disease:f.disease, date:f.date};
  }
  page('Full Journey', `<div class="card wlv1FjCard">
    <div class="wlv1FjTop"><b>${esc(String(p.name||'').toUpperCase()||shownMob(p.mobile))}</b>
      <span class="mut">${esc(shownMob(p.mobile))}${p.patientId?' · '+esc(p.patientId):''}${p.branch?' · '+esc(p.branch):''}</span></div>
    ${wlv1FullJourneyTable(p)}
    <div class="tiny mut">Red time = call logged outside 9 am – 6 pm.</div></div>`, true);
}
window["wlv1FullJourney"]=wlv1FullJourney;

/* ==========================================================================
   TK-REQUESTED (2026-07-26): the web app is also used on a TABLET, where the
   goal is often WhatsApp, not paper. Android has its own Share sheet; a
   browser can do the same through the Web Share API. Falls back to copying
   the text, then to WhatsApp Web. Extra buttons only . no Print button was
   changed or removed.
   ========================================================================== */
function wlv1Share(title, text){
  const payload = String(text||'').trim();
  if(!payload) return toast('Nothing to share');
  try{
    if(navigator && typeof navigator.share === 'function'){
      navigator.share({title:String(title||'PILES CLINIC'), text:payload}).then(()=>{}).catch(()=>{});
      return;
    }
  }catch(e){}
  try{
    if(navigator && navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(payload)
        .then(()=>toast('Copied — now paste it in WhatsApp'))
        .catch(()=>window.open('https://wa.me/?text='+encodeURIComponent(payload),'_blank'));
      return;
    }
  }catch(e){}
  window.open('https://wa.me/?text='+encodeURIComponent(payload),'_blank');
}
window["wlv1Share"]=wlv1Share;

function wlv1ChamberRegisterText(){
  let rows = wlv1ChamberArrivedRows();
  if(wlv1ClosePrintBranch) rows = rows.filter(r=>String(r.branch||'').trim()===wlv1ClosePrintBranch);
  if(!rows.length) return '';
  rows = wlv1ByArrivalOrder(rows);   /* 🔴 V430 — কাগজের মতোই আসার ক্রমে */
  const brName = wlv1ClosePrintBranch || String(rows[0].branch||'');
  const b = branch(brName);
  const rupee = v => Number(v||0)>0 ? '₹'+Number(v).toLocaleString('en-IN') : '-';
  let tFee=0,tCash=0,tOnline=0;
  const lines = rows.map((r,i)=>{
    tFee+=Number(r.fee||0); tCash+=Number(r.cash||0); tOnline+=Number(r.online||0);
    return (i+1)+'. '+String(r.name||r.mobile).toUpperCase()+' ('+normMob(r.mobile)+')'
      + (r.patientId?' ID '+r.patientId:'')
      + '\n   ' + (wlv1EffectivelyBlankRemark(r.treatment) ? '⚠️ PROGRESS PENDING'
                   : (wlv1PrintEn(r.treatment).trim() || '⚠️ PROGRESS PENDING'))
      + '\n   FEES '+rupee(r.fee)+' | CASH '+rupee(r.cash)+' | ONLINE '+rupee(r.online);
  }).join('\n');
  return (isKishanganjBranchName(brName)?'TK BISWAS PILES CLINIC':'MAA AYURVED PILES CLINIC')
    + '\n' + String(brName||'').toUpperCase() + ' — ' + (b.address||'')
    + '\nCHAMBER REGISTER — ' + wlv1Dot(wlv1ChamberDate)
    + '\n\n' + lines
    + '\n\nTOTAL  FEES '+rupee(tFee)+' | CASH '+rupee(tCash)+' | ONLINE '+rupee(tOnline)
    + '\nPATIENTS: ' + rows.length;
}
window["wlv1ChamberRegisterText"]=wlv1ChamberRegisterText;

function wlv1ReportCardText(idOrMobile){
  const list = load('patients');
  /* 🔵🔒 V522 (২২.০৮.২০২৬): আইডি দিয়ে পাওয়া গেলে সেটাই — সব ডাকার জায়গা
     `p.id`-ই পাঠায়, তাই রোজকার পথে কিছুই বদলায় না। শুধু পুরোনো মোবাইল-ভিত্তিক
     fallback-টা এখন **নয়টা পর্দার সেই একই নিয়ম** (`wlv1PickPatientRow`, V143)
     মানে — আগে সে তালিকার **প্রথম** সারিটা তুলে নিত, তাই এক নম্বরে দুজন
     রোগী থাকলে ফোন ও কম্পিউটার আলাদা রোগী দেখাতে পারত।
     ⛔ এক রোগী হলে ফলাফল অবিকল আগের মতোই · কোনো নতুন পড়া নেই। */
  const p = list.find(x=>x.id===idOrMobile)
    || wlv1PickPatientRow(list.filter(x=>mob(x.mobile)===mob(idOrMobile)),
                          (typeof user!=='undefined'&&user&&user.branch)||'');
  if(!p) return '';
  const t = treatmentTotals(p);
  const rows = wlv1TimelineRows(p);
  const rupee = v => '₹'+Number(v||0).toLocaleString('en-IN');
  let paidSoFar = 0;
  const bill = Number(t.bill||0);
  const lines = rows.map((r,i)=>{
    paidSoFar += Number(r.payEffect||0);
    const due = bill>0 ? Math.max(0, bill-paidSoFar) : 0;
    /* TK-REPORTED (27.07.2026, SADDAM): the shared/printed Report Card must show the
       same Progress as the screen — only what a person typed, never the app's own
       payment text. */
    return (i+1)+'. '+fmtDate(r.date)+' — '+r.title
      + (r.typed?(' ('+r.typed+')'):'')
      + (Number(r.paid||0)>0?('  PAID '+rupee(r.paid)+(bill>0?(' | DUE '+rupee(due)):'')):'');
  }).join('\n');
  return (isKishanganjBranchName(p.branch)?'TK BISWAS PILES CLINIC':'MAA AYURVED PILES CLINIC')
    + '\n' + String(p.branch||'').toUpperCase()
    + '\nREPORT CARD\n'
    + '\nName: ' + String(p.name||'').toUpperCase()
    + '\nID: ' + (p.patientId||'-')
    + '\nMobile: ' + normMob(p.mobile)
    + '\nTotal Bill: ' + rupee(bill) + ' | Paid: ' + rupee(t.paid) + ' | Due: ' + (bill>0?rupee(t.due):rupee(0))
    + '\n\n' + (lines || 'No update yet');
}
window["wlv1ReportCardText"]=wlv1ReportCardText;

/* TK-REQUESTED (2026-07-26): the native Trash Bin has BOTH Restore and
   "Delete Forever"; the web only had Restore, so a Master could never clear
   the bin from a computer/tablet. Master-only, with a clear confirmation. */
function wlv1TrashDeleteForever(id){
  if(!isMaster()) return toast('Only Master Admin');
  const tr = load('trash');
  const x = tr.find(a=>a.id===id);
  if(!x) return toast('Record not found');
  const who = String((x.record&&(x.record.name||x.record.mobile))||x.id);
  if(!confirm('Delete forever?\n\n'+who+'\n\nThis cannot be undone.')) return;
  save('trash', tr.filter(a=>a.id!==id));
  try{ if(typeof sb!=='undefined' && sb) sb.from('trash').delete().eq('id', id); }catch(e){}
  toast('Deleted forever');
  trashBin();
}
window["wlv1TrashDeleteForever"]=wlv1TrashDeleteForever;

/* =====================================================================
   🔒 খাতার সারি B116 — ⬇ Sheet (কম্পিউটারের অ্যাপ), TK পাশ 29.07.2026
   ফোনের `FollowUpSheetExporter`-এর কাজটাই এখানে — চলতি তালিকাটা CSV ফাইলে
   নামে, Excel/Google Sheet-এ খোলা যায়।
   ⛔ **ক্লাউডে একটাও অনুরোধ নেই** — যে সারিগুলো এই মুহূর্তে পর্দায় দেখা
      যাচ্ছে, শুধু সেগুলো থেকেই ফাইল বানানো হয় (কোটার নিয়ম মানা)।
   ⛔ **ডেটাবেসে কিছু লেখা হয় না**, কোনো সারি বদলায় না — শুধু পড়া।
   ⛔ ব্রাঞ্চের নিয়ম আগের মতোই — `scoped()` যা দেয় তার বাইরে কিছু যায় না,
      তাই স্টাফ কখনো অন্য ব্রাঞ্চের সারি নামাতে পারবেন না।
   ⛔ কিছু ভুল হলে শুধু একটা বার্তা দেখায়, কোথাও কিছু ভাঙে না।
   ===================================================================== */
function wlv1CsvCell(v){
  var t = String(v==null?'':v);
  return /[",\n]/.test(t) ? '"' + t.replace(/"/g,'""') + '"' : t;
}
window["wlv1CsvCell"]=wlv1CsvCell;
function wlv1DownloadSheet(stage){
  try{
    stage = stage || 'Inquiry';
    /* 🔴🔒 V512 — ব্যানার থেকে আসা মিশ্র পর্দায় (তিন ভাগ একসাথে) ফাইলেও
       তিন ভাগই থাকবে; নইলে পর্দায় ৮ জন অথচ ফাইলে শুধু Enquiry-র ৩ জন
       নামত। ⛔ সাধারণ এক-ভাগের পর্দায় আগের মতোই শুধু সেই ভাগ। */
    var __allSec = (stage === '__ALL__');
    var base = (typeof mergeFollow==='function')
      ? mergeFollow(window.scoped(frArr('followups')))
      : window.scoped(frArr('followups'));
    var rows = base.filter(function(x){
      var sg = String(x.stage||'');
      var stageOk = __allSec ? (sg==='Inquiry'||sg==='Patient'||sg==='Treatment') : (sg===String(stage));
      return stageOk && !isConvertedOrClosed(x);
    });
    /* ছাঁকনি চালু থাকলে ঠিক সেটাই মানা হয় — পর্দায় যা, ফাইলেও তাই। */
    try{
      var f = __followDateFilter;
      if(f && f.from && f.to){
        rows = rows.filter(function(x){
          var d = String(x.nextFollow||x.visitDate||x.recordDate||x.registrationDate||x.date||'').slice(0,10);
          return d && d>=f.from && d<=f.to;
        });
      }
    }catch(_e){}
    if(!rows.length) return toast('তালিকা ফাঁকা — নামানোর কিছু নেই');

    var head = ['SL','DATE','NAME','MOBILE','BRANCH','DISEASE','STAGE','PATIENT ID','LAST CALL','NEXT CALL','CALLS','LAST REMARK'];
    var lines = [head.join(',')];
    rows.forEach(function(x,i){
      var last = x.lastCallDate || '';
      if(!last){
        try{
          var h = x.history; if(typeof h==='string') h=JSON.parse(h);
          if(Array.isArray(h)) for(var k=h.length-1;k>=0;k--){ var d=(h[k]&&h[k].date)||''; if(String(d).trim()){ last=String(d).slice(0,10); break } }
        }catch(_e){}
      }
      lines.push([
        i+1,
        fmtDate(x.recordDate||x.date||''),
        String(x.name||''),
        normMob(x.mobile||''),
        String(x.branch||''),
        String(x.disease||''),
        String(x.stage||''),
        String(x.patientId||''),
        last?fmtDate(last):'',
        x.nextFollow?fmtDate(x.nextFollow):'',
        String(x.callCount||0),
        String(x.lastRemark||'')
      ].map(wlv1CsvCell).join(','));
    });

    /* \uFEFF = Excel-এ বাংলা/ইংরেজি লেখা যাতে ঠিকভাবে খোলে */
    var blob = new Blob(['\uFEFF'+lines.join('\n')], {type:'text/csv;charset=utf-8;'});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'FollowUp-' + stage + '-' + today() + '.csv';
    document.body.appendChild(a); a.click();
    setTimeout(function(){ try{ document.body.removeChild(a); URL.revokeObjectURL(url); }catch(_e){} }, 400);
    toast(rows.length + ' সারি নামানো হলো');
  }catch(e){
    try{ toast('Sheet বানানো গেল না — আবার চেষ্টা করুন'); }catch(_e){}
  }
}
window["wlv1DownloadSheet"]=wlv1DownloadSheet;

/* =====================================================================
   🔒 খাতার সারি B120 — 🔢 Serial No. (কম্পিউটারের অ্যাপ), TK পাশ
   TK-এর কথা (খাতার সারি B68): *"ফিল্টার by সিরিয়াল নাম্বার — সেখানে চাপ
   দিলে এক নম্বর থেকে সমস্ত পেশেন্টের ডিটেলস দেখা যাবে।"*

   কাজ: বোতামে চাপলে কত নম্বর চাই জিজ্ঞাসা করে। নম্বর দিলে ওই কার্ডটায়
   সোজা চলে যায় ও কিছুক্ষণ দাগ দিয়ে দেখায়। ফাঁকা রাখলে তালিকার একদম
   শুরুতে (১ নম্বরে) ফিরে যায়।

   ⛔ **কোনো সারি লুকায় না, বাদ দেয় না** — তাই কোনো ছাঁকনি বা হিসাব
      বদলায় না, কোনো রোগী তালিকা থেকে হারায় না।
   ⛔ **ক্লাউডে অনুরোধ নেই · ডেটাবেসে কিছু লেখা হয় না** — শুধু পর্দার
      ভিতরে চলাফেরা।
   ⛔ চালু ছাঁকনি বা তালিকার ক্রমে হাত পড়ে না।
   ⛔ নম্বর না মিললে শুধু একটা বার্তা, কোথাও কিছু ভাঙে না।
   ===================================================================== */
function wlv1SerialJump(){
  try{
    var host=document.getElementById('followRows');
    if(!host) return toast('তালিকা এখনো তৈরি হয়নি');
    var cards=host.querySelectorAll(':scope > .card');
    if(!cards.length) return toast('তালিকা ফাঁকা');
    var v=prompt('কত নম্বরে যেতে চান? (1 - '+cards.length+')','1');
    if(v===null) return;
    var n=parseInt(String(v).replace(/\D/g,''),10);
    if(!n||n<1||n>cards.length) return toast('1 থেকে '+cards.length+'-এর মধ্যে নম্বর দিন');
    var el=cards[n-1];
    try{ el.scrollIntoView({behavior:'smooth',block:'center'}) }catch(_e){ el.scrollIntoView() }
    var old=el.style.boxShadow, old2=el.style.transition;
    el.style.transition='box-shadow .25s';
    el.style.boxShadow='0 0 0 3px #16a36d';
    setTimeout(function(){ try{ el.style.boxShadow=old; el.style.transition=old2 }catch(_e){} }, 2200);
    toast(n+' নম্বর দেখানো হলো');
  }catch(_e){
    try{ toast('যাওয়া গেল না — আবার চেষ্টা করুন') }catch(__e){}
  }
}
window["wlv1SerialJump"]=wlv1SerialJump;

/* =====================================================================
   🔒🔒 খাতার সারি B121 — টাকার সারি Delete (কম্পিউটারের অ্যাপ), TK পাশ
   ফোনের নিয়মের **হুবহু নকল** (খাতার সারি B111 · B112):
     · মাস্টার → সরাসরি মুছবে (Trash-এ যাবে, ফেরানো যাবে)
     · স্টাফ → **আজ ও গতকালের** এন্ট্রি নিজে মুছতে পারবেন
     · স্টাফ → ওই দিনের চেম্বার বন্ধ হয়ে গেলে **আর নয়** (মাস্টার হিসাব
       পেয়ে গেছেন) — তখন মাস্টারের ঘন্টায় অনুরোধ যায়
     · পুরনো এন্ট্রি → অনুমতি লাগবে

   ⛔ **কোনো সারি চিরতরে মোছা হয় না** — আগে `trash` টেবিলে নকল রেখে তবেই
      তালিকা থেকে সরে, তাই Trash Bin থেকে ফেরানো যায়। Trash-এ তুলতে না
      পারলে **কিছুই মোছা হয় না**।
   ⛔ **বিল ছোঁয়া হয় না** — শুধু ওই টাকার সারিটা ওঠে, তাই জমা/বকেয়া নিজে
      থেকেই ঠিক হয়ে যায়।
   ⛔ মাস্টারকে জানানোর জন্য **চালু briefings ব্যবস্থাই** ব্যবহার — নতুন
      টেবিল বা SQL লাগে না।
   ⛔ ব্রাঞ্চের টাকার নিয়ম আগের মতোই (`wlv1CanTakeMoney`-র মতোই ব্রাঞ্চ যাচাই)।
   ===================================================================== */
function wlv1ChamberClosedFor(branch,date){
  try{
    if(!branch||!date) return false;
    // 🔴 TK-REPORTED BUG FIX (02.08.2026, B303): এই ফাংশন এতদিন
    // 'close_'+branch+'_'+date নামে খুঁজত, কিন্তু wlv1MarkChamberClosed()
    // আসলে লেখে branch.toUpperCase()+'|'+date নামে — দুটো কখনো মেলেনি,
    // তাই এই ফাংশন কখনোই "বন্ধ" খুঁজে পেত না (সবসময় "খোলা" ধরে নিত)।
    // এখন লেখা-হওয়া id-এর সাথে হুবহু মিলিয়ে খোঁজা হচ্ছে।
    var id=String(branch).trim().toUpperCase()+'|'+String(date).slice(0,10);
    return (load('chamber_close')||[]).some(function(r){ return r && String(r.id)===id });
  }catch(_e){ return false }
}
function wlv1CanDeletePaymentNow(row,paid){
  try{
    if(isMaster()) return true;
    // 🆕 B467 (06.08.2026, TK-নির্দেশ): টাকা জমাই না পড়ে থাকলে (Enquiry/
    // Visit, এখনো Advance হয়নি) — যেকোনো দিন, কোনো অনুমতি ছাড়াই। কল-সাইট
    // paid না পাঠালে (পুরনো ব্যবহার/Payment-সারি) আগের মতোই কড়া ধরে নেওয়া
    // হয় (paid=true), কোনো ভুলে "ফ্রি" হয়ে যাওয়ার ঝুঁকি নেই।
    if(paid===false) return true;
    var d=String(row&&row.date||'').slice(0,10);
    if(!d) return false;
    if(wlv1ChamberClosedFor(row.branch,d)) return false;
    // 🆕 B467 (06.08.2026): আগে আজ+গতকাল দুদিন চলত, এখন শুধু আজকের এন্ট্রি।
    // ⛔ ফোনের OUT TIME-চেকটা এখানে প্রযোজ্য না — Work Notebook (IN/OUT TIME)
    // শুধু নেটিভ অ্যাপে আছে, ওয়েবে এই ধারণাটাই নেই।
    return d===today();
  }catch(_e){ return false }
}
window["wlv1CanDeletePaymentNow"]=wlv1CanDeletePaymentNow;

/** 🔴 TK-নির্দেশ (02.08.2026, B303.1): অন্য কম্পিউটার/ফোন থেকে Chamber বন্ধ
 *  করা হলে, এই ডিভাইসও যেন জানতে পারে — কিন্তু Draft/Payment তালিকা খোলার
 *  সময় নয় (সেটা করলে TK-এর আগের অভিযোগ মতো তালিকা লোড আরও ধীর হয়ে যেত) —
 *  বরং শুধু আসল Delete চাপার মুহূর্তে (এই ফাংশন `wlv1DeleteDraftEntry`ও
 *  `wlv1DeletePayment`, দুটোতেই ব্যবহার হয়) একবার হালকা ক্লাউড-কল করে
 *  chamber_close-এর সাম্প্রতিক (গতকাল-আজ) সারি টেনে লোকাল ক্যাশে মিলিয়ে
 *  নেওয়া হয় — তারপর বিদ্যমান `wlv1ChamberClosedFor()`/`wlv1CanDeletePaymentNow()`
 *  সেই তাজা তথ্যই পড়ে, কোনো আলাদা লজিক লেখা লাগেনি। ব্যর্থ হলে (অফলাইন/এরর)
 *  চুপচাপ থেমে যায়, পুরনো লোকাল ক্যাশেই কাজ চলে — Delete বোতাম কখনো আটকে
 *  থাকে না। ছোট টেবিল (ব্রাঞ্চ প্রতি দিনে একটা সারি) — quota-খরচ নগণ্য। */
async function wlv1PullChamberCloseFromCloud(){
  try{
    let ok=await initCloudClientOnly(); if(!ok||!sb) return false;
    let y=new Date(); y.setDate(y.getDate()-1);
    let ymd=y.toISOString().slice(0,10);
    let {data,error}=await sb.from('chamber_close').select('*').gte('date',ymd).limit(200);
    if(error||!Array.isArray(data)) return false;
    let merged=mergeById(normalizeCloudRows(data), load('chamber_close')||[]);
    save('chamber_close', merged, {skipCloud:true, skipBackup:true});
    return true;
  }catch(_e){ return false; }
}
window["wlv1PullChamberCloseFromCloud"]=wlv1PullChamberCloseFromCloud;
/* ═══════════════════════════════════════════════════════════════════
   🖥️🔵 B668 (১৫.০৮.২০২৬, TK-অনুমোদিত) — "Chamber Close" (কোন কোন পুরনো দিনের
   চেম্বার বন্ধ করা বাকি)। এতদিন এটা **শুধু ফোনে** ছিল (`ChamberCloseActivity.kt`
   + `ChamberUnclosedRepository.kt`), কম্পিউটারে কোথাও ছিল না — তাই মাস্টার
   কম্পিউটারে বসে দেখতেই পারতেন না কোন দিন বন্ধ করা বাকি রয়ে গেছে।

   ⚡ **Supabase Free plan মাথায় রেখে (TK-এর শর্ত):**
     · টাকার সারি (`payments`) **ক্লাউড থেকে আনা হয় না** — ওয়েব এমনিতেই
       local-first, তাই ফোনে/ব্রাউজারে আগে থেকে জমা তথ্য থেকেই হিসাব হয়।
       ⇒ এই পর্দার জন্য payments-এ **শূন্য** নতুন খরচ।
     · শুধু `chamber_close` টেবিলের ৩টা ঘর (id · branch · date) একবার আনা হয় —
       ব্রাঞ্চ প্রতি দিনে একটা সারি, ৩০ দিনে সর্বোচ্চ ~১৫০ সারি (কয়েক KB)।
     · Android-এর মতোই **২ মিনিটের স্মৃতি** — পরপর খুললে আবার আনা হয় না।
   ⛔ কিছুই লেখা হয় না — শুধু পড়া। কোনো হিসাব/নিয়ম বদলায়নি।
   ⛔ হিসাবের নিয়ম `ChamberUnclosedRepository.kt`-এর **হুবহু নকল**:
     আজকের দিন বাদ (আজ তো চলছে) · `chamber_expected` সারি গোনা হয় না ·
     approved refund টাকা থেকে বিয়োগ, pending/rejected refund ০ ·
     কেউ আসেনি ও টাকাও ওঠেনি এমন দিন তালিকায় তোলা হয় না।
   ⛔ ব্রাঞ্চ-গোপনীয়তা প্রজেক্টের নিজস্ব `scoped()` দিয়েই (নতুন নিয়ম নয়)। */
let wlv1UncBranch='', wlv1UncPullAt=0;   /* 🟢🔒 V398: মনে-রাখা মানের প্রতিচ্ছবি */
function wlv1UncDaysAgo(n){ let d=new Date(); d.setDate(d.getDate()-n); return d.toISOString().slice(0,10); }
async function wlv1PullChamberCloseRange(fromYmd){
  try{
    let ok=await initCloudClientOnly(); if(!ok||!sb) return false;
    let {data,error}=await sb.from('chamber_close').select('id,branch,date').gte('date',fromYmd).limit(500);
    if(error||!Array.isArray(data)) return false;
    save('chamber_close', mergeById(normalizeCloudRows(data), load('chamber_close')||[]), {skipCloud:true, skipBackup:true});
    return true;
  }catch(_e){ return false; }
}
window["wlv1PullChamberCloseRange"]=wlv1PullChamberCloseRange;
function wlv1FindUnclosed(branchFilter, days){
  let from=wlv1UncDaysAgo(days), to=wlv1UncDaysAgo(1);
  if(from>to) return [];
  let closed={};
  (load('chamber_close')||[]).forEach(function(r){ if(r&&r.id) closed[String(r.id)]=1; });
  let only=String(branchFilter||'').trim();
  if(!only || only.toLowerCase()==='all') only='';
  let people={}, money={}, label={};
  scoped(load('payments')).forEach(function(p){
    if(!p) return;
    let dt=String(p.date||'').slice(0,10); if(!dt || dt<from || dt>to) return;
    let br=String(p.branch||'').trim(); if(!br) return;
    if(only && br.toLowerCase()!==only.toLowerCase()) return;
    if(String(p.payType||'')==='chamber_expected') return;   // "আসার কথা" = আসা নয়
    let key=br.toUpperCase()+'|'+dt;
    label[key]=[dt,br];
    let m=String(p.mobile||'').replace(/\D/g,'').slice(-10);
    if(m){ people[key]=people[key]||{}; people[key][m]=1; }
    let amt=Number(p.amount||0)||0;
    let eff = wlv1IsApprovedRefund(p) ? -amt : (wlv1IsRefundRow(p) ? 0 : amt);
    money[key]=(money[key]||0)+eff;
  });
  let out=[];
  Object.keys(label).forEach(function(key){
    if(closed[key]) return;
    let arrived=Object.keys(people[key]||{}).length, amt=money[key]||0;
    if(arrived<=0 && amt<=0) return;                          // কেউ আসেনি, টাকাও ওঠেনি
    out.push({date:label[key][0], branch:label[key][1], arrived:arrived, money:amt});
  });
  return out.sort(function(a,b){ return a.date<b.date?1:(a.date>b.date?-1:0); });
}
window["wlv1FindUnclosed"]=wlv1FindUnclosed;
function wlv1UncOpenDay(date,branch){
  /* 🟢🔒 V398: এখান থেকে যে ব্রাঞ্চে ঢোকা হচ্ছে সেটাই মনে রাখা ব্রাঞ্চ হবে। */
  try{ wlv1ChamberDate=String(date).slice(0,10); wlv1BranchSet(String(branch||'All')); wlv1ChamberBranch=wlv1BranchGet(); }catch(_e){}
  chamberAttendance();                                        // চেম্বার বন্ধ করার আগের পর্দাটাই খোলে
}
window["wlv1UncOpenDay"]=wlv1UncOpenDay;
async function wlv1ChamberCloseList(){
  if(!isMaster()) return toast('Only Master Admin');
  const days=30;
  const draw=function(){
    /* 🟢🔒 V398: মনে-রাখা ব্রাঞ্চ — এক জায়গা থেকে। বাছা না-থাকলে তালিকা নয়, বার্তা। */
    wlv1UncBranch=wlv1BranchGet();
    let __uncAsk=!wlv1UncBranch;
    let rows=__uncAsk?[]:wlv1FindUnclosed(wlv1UncBranch, days);
    let pick=`<div id="uncBranchWrap" class="wlv1HdrPick">${wlv1BranchSelectHtml('wlv1ChamberCloseList()',{cls:'wlv1UncSel'})}</div>`;
    let list=rows.map(function(r){
      return `<div class="card wlv1UncRow">
        <div class="wlv1UncL"><b>${esc(fmtDate(r.date))}</b><small>${esc(r.branch)}</small></div>
        <div class="wlv1UncM"><span>${r.arrived} arrived</span><span>${esc(money(r.money))}</span></div>
        <button class="wlv1UncBtn" onclick="wlv1UncOpenDay('${esc(r.date)}','${esc(r.branch)}')">Close it</button>
      </div>`;
    }).join('') || (__uncAsk?wlv1BranchAskCard():`<div class="card mut" style="text-align:center">✅ All closed — no pending day in the last ${days} days.</div>`);
    page('Chamber Close', `<div class="wlv1UncTop">${pick}
        <div class="tiny mut">Last ${days} days · today is not counted (it is still running)</div></div>
      ${rows.length?`<div class="card wlv1UncCount">⚠️ ${rows.length} day${rows.length>1?'s':''} not closed yet</div>`:''}
      ${list}
      <div class="tiny mut" style="text-align:center;margin-top:10px">Counted from the data already on this computer (last sync). Tap "Sync Now" in the menu for the newest.</div>`, true);
  };
  draw();
  if(Date.now()-wlv1UncPullAt > 120000){                      // ২ মিনিটের স্মৃতি — Android-এর মতোই
    wlv1UncPullAt=Date.now();
    let ok=await wlv1PullChamberCloseRange(wlv1UncDaysAgo(days));
    if(ok) draw();
  }
}
window["wlv1ChamberCloseList"]=wlv1ChamberCloseList;

/* ═══════════════════════════════════════════════════════════════════════
   🟢🔒 B676 (১৫.০৮.২০২৬, TK-অনুমোদিত) — **"কাল কারা আসবেন"** (Expected Tomorrow)।
   ফোনে ছিল (`ExpectedTomorrowActivity.kt`), কম্পিউটারে ছিল না — তাই কাল কাকে ফোন
   করতে হবে সেটা কম্পিউটারে বসে দেখা যেত না।

   ⛔ নিয়মটা ফোনের কোডের **হুবহু নকল** (`ExpectedTomorrowActivity.kt:106-118`):
     · `payments`-এর যে সারির `payType = chamber_expected`
     · আর `date` = আগামীকাল
     · একই মোবাইল একবারই (দু'বার উঠবে না)
   ⚡ **Free plan: শূন্য খরচ** — ওয়েব local-first, টাকার সারি এমনিতেই কম্পিউটারে
      জমা থাকে, তাই এই পর্দার জন্য **একটাও ক্লাউড-অনুরোধ যায় না**।
   ⛔ ব্রাঞ্চ-গোপনীয়তা প্রজেক্টের নিজস্ব `scoped()` দিয়েই — নতুন নিয়ম বানানো হয়নি।
   ═══════════════════════════════════════════════════════════════════════ */
function wlv1TomorrowIso(){ let d=new Date(); d.setDate(d.getDate()+1); return d.toISOString().slice(0,10); }
function wlv1ExpectedTomorrowRows(){
  let t=wlv1TomorrowIso(), seen={}, out=[];
  scoped(load('payments')).forEach(function(p){
    if(!p) return;
    if(String(p.payType||'')!=='chamber_expected') return;
    if(String(p.date||'').slice(0,10)!==t) return;
    let key=String(p.mobile||'').replace(/\D/g,'').slice(-10) || String(p.id||'');
    if(!key || seen[key]) return;
    seen[key]=1;
    out.push({name:String(p.name||''), mobile:String(p.mobile||''), branch:String(p.branch||'')});
  });
  return out;
}
window["wlv1ExpectedTomorrowRows"]=wlv1ExpectedTomorrowRows;
function wlv1ExpectedTomorrow(){
  let t=wlv1TomorrowIso(), rows=wlv1ExpectedTomorrowRows();
  let list=rows.map(function(r){
    let m=String(r.mobile||'').replace(/\D/g,'').slice(-10);
    return `<div class="card wlv1EtRow">
      <div class="wlv1EtL"><b>${esc(r.name||normMob(r.mobile)||'-')}</b><small>${esc(normMob(r.mobile))}${r.branch?' · '+esc(r.branch):''}</small></div>
      <div class="wlv1EtBtns">
        <button class="wlv1EtCall" onclick="contact('${esc(m)}','call')">📞 Call</button>
        <button class="wlv1EtWa" onclick="contact('${esc(m)}','wa')">💬 WhatsApp</button>
        <button class="wlv1EtJ" onclick="wlv1FullJourney('${esc(m)}')">🧭 History</button>
      </div></div>`;
  }).join('') || `<div class="card mut" style="text-align:center">Nobody is expected tomorrow (${esc(fmtDate(t))}).</div>`;
  page('Expected Tomorrow', `<div class="card wlv1EtTop"><b>Tomorrow · ${esc(fmtDate(t))}</b>`
    + `<span>${rows.length} patient${rows.length===1?'':'s'}</span></div>${list}`
    + `<div class="tiny mut" style="text-align:center;margin-top:10px">From the data already on this computer (last sync).</div>`, true);
}
window["wlv1ExpectedTomorrow"]=wlv1ExpectedTomorrow;


/** 🆕 (03.08.2026, TK-অনুমোদনে) — Android-এর `BackdatePaymentGrant` ফিচারের
 *  ওয়েব-সংস্করণ। Master Briefing/ঘন্টা স্ক্রিন থেকে (ফোনে) কোনো স্টাফকে
 *  নির্দিষ্ট দিন/সময়ের জন্য ব্যাকডেট-পেমেন্ট Edit/Delete-এর সাময়িক অনুমতি
 *  দিলে, সেটা এখন কম্পিউটার থেকেও কাজ করে — একই `backdate_payment_grants`
 *  টেবিল, নতুন কোনো SQL লাগে না। ⛔ **ওয়েবে পেমেন্ট "তোলা"-র তারিখ সবসময়
 *  আজকের (readonly)** — তাই Grant এখানে শুধু Edit ও Delete-এই প্রযোজ্য,
 *  Android-এর মতো নতুন পেমেন্ট নেওয়ার backdated-date প্রশ্নই ওঠে না।
 *  ঠিক `wlv1PullChamberCloseFromCloud()`-এর একই প্রমাণিত প্যাটার্নে —
 *  লোকাল ক্যাশে টেনে রাখা হয়, ব্যর্থ/অফলাইন হলে চুপচাপ থেমে যায়, পুরনো
 *  ক্যাশেই কাজ চলে (Delete/Edit বোতাম কখনো আটকে থাকে না)। */
async function wlv1PullBackdateGrantsFromCloud(){
  try{
    if(!user||!user.mobile) return false;
    let ok=await initCloudClientOnly(); if(!ok||!sb) return false;
    let digits=String(user.mobile).replace(/\D/g,'').slice(-10);
    if(digits.length!==10) return false;
    let {data,error}=await sb.from('backdate_payment_grants').select('*')
      .eq('staffMobile',digits).eq('active',true).order('grantedAt',{ascending:false}).limit(50);
    if(error||!Array.isArray(data)) return false;
    save('bpg_grants', data, {skipCloud:true, skipBackup:true});
    return true;
  }catch(_e){ return false; }
}
window["wlv1PullBackdateGrantsFromCloud"]=wlv1PullBackdateGrantsFromCloud;
function wlv1IsBackdateGranted(date){
  try{
    if(!user||!user.mobile||!date) return false;
    /* 🔴 V444: startDate/endDate = permission ACTIVE window, transaction-date
       range নয়। Permission আজ active থাকলে Staff historical payment date যত
       পুরনোই হোক, existing branch/payment guards মেনে কাজ করতে পারবে। */
    var permissionDay=today();
    return (load('bpg_grants')||[]).some(function(g){
      return g && g.active && g.startDate<=permissionDay && g.endDate>=permissionDay;
    });
  }catch(_e){ return false; }
}
window["wlv1IsBackdateGranted"]=wlv1IsBackdateGranted;

/* =====================================================================
   V217 (§B216, Master Fix Order §14 — কম্পিউটারে, TK-এর ডিজাইন-প্রুফ পাশ
   করার পরে, 31.07.2026) — Enquiry/Patient Same-Day Delete → Trash।
   ⛔ হুবহু wlv1DeletePayment()-এর সেই একই, পরীক্ষিত প্যাটার্ন — নতুন কোনো
      আলাদা নিয়ম বানানো হয়নি: same-day check → না হলে Master-এর ঘন্টায়
      অনুরোধ, কিছু মোছে না → হলে Trash-এ (id record-ধরে বাঁধা) → cloud-এ
      সত্যিই মুছলে তবেই local থেকে মোছা → DeletedGuard চিহ্ন → Master-কে
      briefings-এ খবর। শুধু টেবিল payments-এর বদলে enquiries/patients।
   ⛔ Draft-এর বাতিল তালিকা ছাড়া অন্য কোথাও এই বোতাম দেখানো হয় না (B113/
      B124-এর সেই একই নিয়ম — চালু কার্ডে ডিলিট কখনো না)।
   ===================================================================== */
var wlv1DeleteInFlight = wlv1DeleteInFlight || new Set();
async function wlv1DeleteDraftEntry(table, recId, mobile, branch, entryDate, displayName, paid, noConfirm){
  // 🔒 B334-এর মতোই আসল-দুর্ঘটনার পুনরাবৃত্তি ঠিক করে রাখা: browser-এর confirm()
  // মূলত blocking হলেও, confirm() পপ-আপ ওঠার আগের await-গুলোর সময় দ্রুত দুইবার
  // চাপলে দুটো আলাদা কল শুরু হতে পারে (Android-এ যা সত্যিই হয়েছিল, ঠিক সেই
  // ক্লাসের ঝুঁকি) — একই recId-এর জন্য দ্বিতীয় কল সঙ্গে সঙ্গে বাদ।
  if(wlv1DeleteInFlight.has(recId)) return false;
  wlv1DeleteInFlight.add(recId);
  try{
    // 🔵 R7 — noConfirm শুধু "একসাথে-বাছাই" থেকে আসে; তখন পপ-আপ দুটো একবারই
    // আগে দেখানো হয়ে গেছে। ⛔ একটা-একটা Delete-এ noConfirm কখনো পাঠানো হয় না,
    // তাই পুরনো পথ (দুটো confirm সহ) হুবহু আগের মতোই আছে।
    return await wlv1DeleteDraftEntryImpl(table, recId, mobile, branch, entryDate, displayName, paid, noConfirm);
  } finally {
    wlv1DeleteInFlight.delete(recId);
  }
}
window["wlv1DeleteDraftEntry"]=wlv1DeleteDraftEntry;
async function wlv1DeleteDraftEntryImpl(table, recId, mobile, branch, entryDate, displayName, paid, noConfirm){
  try{
    var mm=mob(mobile);
    // 🔒 V219 (§2, 31.07.2026): ভুল রোগী যেন কখনো Delete না হয় — সারিটা এখন
    // **মোবাইল নম্বর দিয়ে নয়, ঠিক Record ID দিয়ে** খোঁজা হয়। আগে
    // `findIndex(x=>mob(x.mobile)===mm)` একই মোবাইলের প্রথম সারিটা ধরত, তাই
    // এক নম্বরে একাধিক enquiry থাকলে (রিপিট কল/পরিবারে এক নম্বর) ভুল সারিটা
    // মুছে যেতে পারত। recId = enquiry হলে enquiry-র id, patient হলে patient-এর id
    // (caller ঠিক id পাঠায়)। id ফাঁকা/না মিললে নিরাপদে "not found"।
    if(!recId) return toast('Record not found — please reopen the list and try again');
    var all=load(table), i=all.findIndex(function(x){ return String(x.id)===String(recId); });
    if(i<0) return toast('Record not found — it may already be deleted');
    var row=all[i];
    var label=displayName||row.name||normMob(mm);

    // 🔴 B303.1: অন্য ডিভাইস থেকে Chamber বন্ধ করা থাকলেও এখানে ধরা পড়ে —
    // ব্যর্থ/ধীর নেট হলেও চুপচাপ এগিয়ে যায় (পুরনো লোকাল ক্যাশে ফলব্যাক)।
    await wlv1PullChamberCloseFromCloud();

    if(!wlv1CanDeletePaymentNow({date:entryDate, branch:branch}, paid)){
      // 🔵 R7 — একসাথে-বাছাইয়ে এই সারিগুলো আগেই বাদ দেওয়া হয়েছে; তবু দ্বিতীয়
      // স্তরের সুরক্ষা হিসেবে এখানে চুপচাপ থেমে যায় (কিছুই মোছে না)।
      if(noConfirm) return false;
      if(!confirm(label+'\n\n⛔ এখনই কিছুই মুছবে না।\nMaster-এর ঘন্টায় অনুরোধ যাবে; তিনি অনুমোদন দিলে তবেই ডিলিট হবে।\n\nঅনুরোধ পাঠাব?')) return;
      var req={id:uid('brief'),date:today(),title:'🗑️ Delete request — '+label,
        message:'Delete permission request\nType : '+(table==='enquiries'?'Enquiry':'Patient')+
                 '\nName : '+(row.name||'')+'\nMobile : '+normMob(mm)+
                 '\nPatient ID : '+(row.patientId||'')+'\nBranch : '+(row.branch||'')+
                 '\nRequested by : '+(codeName(user&&user.mobile)||''),
        targets:{roles:['master']},branch:row.branch||'',seen:[],replies:[],
        createdBy:(user&&user.mobile)||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
      add('briefings',req);
      try{ await cloudUpsertBriefing(req) }catch(_e){}
      return toast('Master notified');
    }

    if(!noConfirm && !confirm(label+'\n\nএই রেকর্ডটা Trash-এ যাবে (Master পরে Restore করতে পারবেন)।\nPayment/Follow-up ইতিহাস অক্ষত থাকবে।\n\nমুছবেন?')) return;

    var t={id:wlv1TrashIdFor(table,row.id),
           table:table,record:row,deletedAt:new Date().toISOString(),deletedBy:(user&&user.mobile)||''};
    add('trash',t);
    var okT=true; try{ okT=await directCloudUpsertRow('trash',t) }catch(_e){ okT=false }
    if(!okT) return toast('Trash-এ রাখা গেল না — কিছুই মোছা হয়নি');

    var gone=await wlv1CloudDeleteRow(table,row.id);
    if(!gone) return toast('Cloud-এ মোছা গেল না — কিছুই মোছা হয়নি, আবার চেষ্টা করুন');
    all.splice(i,1); put(table,all);
    try{ await wlv1MarkDeletedCloud(table,row.id) }catch(_e){}
    // 🔴 V448 — ওই মোবাইলের followups সারিগুলোও বন্ধ, নইলে ডিলিট করা নাম
    // followups-নির্ভর তালিকায় "ফিরে" দেখাতে পারে।
    try{ wlv1CloseFollowUpsForDeletedMobile(mm) }catch(_e){}

    try{
      var n={id:uid('brief'),date:today(),title:'🗑️ Deleted — '+label,
        message:(table==='enquiries'?'Enquiry':'Patient')+' · '+(row.branch||'')+
                 '\nDeleted by : '+(codeName(user&&user.mobile)||'')+'\nTrash Bin থেকে ফেরানো যাবে।',
        targets:{roles:['master']},branch:row.branch||'',seen:[],replies:[],
        createdBy:(user&&user.mobile)||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
      add('briefings',n); await cloudUpsertBriefing(n);
    }catch(_e){}

    // 🔵 R7 — bulk হলে প্রতিবার toast/পাতা-বদল নয়; সব শেষে একবারই হয়।
    if(noConfirm) return true;
    toast('Deleted — moved to Trash Bin');
    try{ draffHome('home') }catch(_e){}
    return true;
  }catch(e){ if(noConfirm) return false; toast('Could not delete — try again'); }
}
window["wlv1DeleteDraftEntry"]=wlv1DeleteDraftEntry;

/* =====================================================================
   V217 (§B216, Master Fix Order §14 — কম্পিউটারে Refund, TK-এর ডিজাইন-প্রুফ
   পাশ করার পরে, 31.07.2026)। ফোনের PaymentRepository.kt-এর `paidEffect`-এর
   হুবহু একই ধারণা — এক জায়গায় লেখা, সব হিসাব (paymentHistory, Report Card
   স্ক্রিন+টেক্সট) এখান থেকেই নেয়, যাতে refund-এর সাইন কোথাও ভুল না হয়
   (ফোনের সেশনে এই ভুলটাই প্রথমবার একাধিক জায়গায় ধরা পড়েছিল, তাই এখানে
   শুরু থেকেই এক জায়গায় রাখা হলো)। */
function wlv1IsRefundRow(x){ return String(x&&x.payType||'').toLowerCase()==='refund'; }
/** 🔴🔴🔒 খাতার সারি B453 (TK-নির্দেশ, 05.08.2026 — "চেকআপ করার আগে
 *  পেশেন্টের সম্পূর্ণ হিস্ট্রি দেখতে হবে")। Registration/Visit-এর Full
 *  Journey নোটে Complaint-এর সাথে Duration/Previous Treatment-ও জোড়া
 *  লাগানো হয় — Android-এর PatientTimelineRepository.kt-এর হুবহু একই
 *  নিয়ম। ⛔ শুধু দেখানোর জন্য — p.sinceWhen/p.previousTreatment (আসল
 *  Registration-এর মূল তথ্য) এখানে বদলায় না। */
function wlv1RegistrationNote(p){
  let parts=[];
  if(p.complaint) parts.push(p.complaint);
  if(p.sinceWhen) parts.push('Duration: '+p.sinceWhen);
  if(p.previousTreatment) parts.push('Previous Treatment: '+p.previousTreatment);
  return parts.join(' | ');
}
function wlv1IsApprovedRefund(x){ return wlv1IsRefundRow(x) && String(x&&x.refundApprovalStatus||'').toLowerCase()==='approved'; }
function wlv1PayEffect(x){
  var t=String(x&&x.payType||'treatment').toLowerCase();
  if(t==='visit_fee'||t==='attendance_mark') return 0;
  if(wlv1IsRefundRow(x)) return wlv1IsApprovedRefund(x) ? -Number(x.amount||0) : 0;
  return Number(x&&x.amount||0);
}
window["wlv1PayEffect"]=wlv1PayEffect;
window["wlv1IsApprovedRefund"]=wlv1IsApprovedRefund;

/** 🔴🔴 V509 (২১.০৮.২০২৬, TK-এর সিদ্ধান্ত — *"হ্যাঁ, সবাই পারবে — Visit Fee-ও
 *  ফেরতের সীমায় ধরা হবে"*): এই রোগীর **Visit Fee / Registration Fee**-এর যোগফল।
 *
 *  ⛔ ইচ্ছে করেই `wlv1PayEffect()`-এ হাত দেওয়া হয়নি — ওটা দিয়ে Bill/Due ও
 *     কালেকশনের হিসাব হয়, আর Visit Fee চিকিৎসার বিলের অংশ নয়। মিশিয়ে দিলে
 *     প্রত্যেক রোগীর Due ভুল হয়ে যেত। তাই Visit Fee **আলাদা** গোনা হয়, আর
 *     শুধু **Refund-এর সীমা** ঠিক করার সময় দুটো যোগ হয় — ফোনের অ্যাপে
 *     (`PatientBillInfo.refundableTotal`) হুবহু একই নিয়ম।
 *  ⛔ Refund সারি কখনো "Visit Fee জমা" নয় (টাকা আসছে না, যাচ্ছে) — তাই
 *     প্রথমেই `wlv1IsRefundRow()` বাদ। ফোনে ঠিক এই ফাঁদেই একটা টাকা-নষ্ট
 *     করা বাগ ধরা পড়েছিল (কেউ কারণ লেখেন "VISIT FEE REFUND")। */
function wlv1VisitFeePaidNow(patientRow){
  try{
    var rows=load('payments').filter(function(x){ return payOwnedBy(x,patientRow); });
    var sum=0;
    for(var i=0;i<rows.length;i++){
      var x=rows[i];
      if(wlv1IsRefundRow(x)) continue;                       // ফেরত কখনো জমা নয়
      var t=String(x&&x.payType||'').toLowerCase();
      if(t==='visit_fee'||t==='visitfee'||t==='registration') sum+=Number(x.amount||0);
    }
    return sum;
  }catch(_e){ return 0; }
}
window["wlv1VisitFeePaidNow"]=wlv1VisitFeePaidNow;

/** 🔴 V509 — সর্বোচ্চ কত টাকা ফেরত দেওয়া যায় (চিকিৎসার জমা + Visit Fee),
 *  অনুমোদিত ফেরত বাদ দিয়ে। ⛔ শুধু Refund-এর পাহারায়; Due-র হিসাবে কখনো নয়।
 *  ⛔ কখনো ঋণাত্মক নয় — তাই সীমা কখনো বেড়ে যেতে পারে না। */
function wlv1RefundableNow(patientRow){
  try{
    var paid=wlv1PatientPaidNow(patientRow);        // ফেরত ইতিমধ্যে বিয়োগ করা
    var vf=wlv1VisitFeePaidNow(patientRow);
    return Math.max(0, paid+vf);
  }catch(_e){ return 0; }
}
window["wlv1RefundableNow"]=wlv1RefundableNow;

/** এই মুহূর্তে রোগীর সত্যিকারের Paid (approved refund বিয়োগ করে) — Refund
 *  ফর্মে "জমার বেশি" আটকাতে ব্যবহার হয়। */
function wlv1PatientPaidNow(patientRow){
  try{
    var rows=load('payments').filter(function(x){ return payOwnedBy(x,patientRow); });
    var sum=0; for(var i=0;i<rows.length;i++) sum+=wlv1PayEffect(rows[i]);
    return sum;
  }catch(_e){ return 0; }
}
window["wlv1PatientPaidNow"]=wlv1PatientPaidNow;

/** 🔴 TK-নির্দেশ (02.08.2026, B302/B302.1 — ফোনের সাথে মিলিয়ে): Approved
 *  Refund আছে + নেট জমা ঠিক ₹0 হলে (আর `patients.refundRestoredBy` দিয়ে
 *  হাতে করে Restore করা না থাকলে) — এই মোবাইলগুলো Patient ট্যাব থেকে বাদ,
 *  Draft-এর নতুন "Refunded" ঘরে যাবে। ফোনের PaymentRepository/
 *  FollowUpRepository-র হুবহু একই যুক্তি, শুধু এখানে payments-এর মোট
 *  wlv1PayEffect + patients.refundRestoredBy দিয়ে হিসাব হয়। */
function wlv1RefundedMobilesSet(){
  try{
    var pay=load('payments')||[];
    var byMob={};
    pay.forEach(function(x){
      var m=mob(x.mobile); if(!m) return;
      if(!byMob[m]) byMob[m]={hasApprovedRefund:false, net:0};
      byMob[m].net += wlv1PayEffect(x);
      if(wlv1IsApprovedRefund(x)) byMob[m].hasApprovedRefund=true;
    });
    var restoredMobs={};
    (load('patients')||[]).forEach(function(p){
      if(p && String(p.refundRestoredBy||'').trim()!=='') { var m=mob(p.mobile); if(m) restoredMobs[m]=true; }
    });
    var out=new Set();
    Object.keys(byMob).forEach(function(m){
      var v=byMob[m];
      if(v.hasApprovedRefund && v.net<=0.5 && !restoredMobs[m]) out.add(m);
    });
    return out;
  }catch(_e){ return new Set(); }
}
window["wlv1RefundedMobilesSet"]=wlv1RefundedMobilesSet;

/** ইতিমধ্যে pending refund request (এখনো Master দেখেননি) — এটাও যোগ করে
 *  ধরা হয়, নইলে দুটো আলাদা ছোট request একসাথে জমার বেশি হয়ে যেতে পারত
 *  (ফোনের সেশনে এই ফাঁকটাও ধরা পড়েছিল)। */
function wlv1PendingRefundSum(patientRow,excludeId){
  try{
    var rows=load('payments').filter(function(x){
      // V219 (§1): একই Refund আবার চাপলে (deterministic id) সেটাকে দুবার গোনা হয় না।
      if(excludeId && String(x.id)===String(excludeId)) return false;
      return payOwnedBy(x,patientRow) && wlv1IsRefundRow(x) && String(x.refundApprovalStatus||'').toLowerCase()==='pending';
    });
    var sum=0; for(var i=0;i<rows.length;i++) sum+=Number(rows[i].amount||0);
    return sum;
  }catch(_e){ return 0; }
}
window["wlv1PendingRefundSum"]=wlv1PendingRefundSum;

/** 🔴🔴🔒 খাতার সারি B445 (TK-নির্দেশ, 05.08.2026, উদাহরণ দিয়ে বুঝিয়ে —
 *  "গতকালের জমা তো আমার পকেটে চলে গেছে, স্টাফ আজ সেটা ফেরত দেবে কোথা
 *  থেকে?")। আজ এই রোগী থেকে সত্যিই কত টাকা জমা পড়েছে (Refund বাদে) —
 *  Android-এর `paidTodayForPatient()`-এর হুবহু একই নিয়ম। */
function wlv1PaidTodayForPatient(patientRow){
  try{
    var d=today();
    var rows=load('payments').filter(function(x){
      return payOwnedBy(x,patientRow) && !wlv1IsRefundRow(x) && String(x.date||'')===d;
    });
    var sum=0; for(var i=0;i<rows.length;i++) sum+=Number(rows[i].amount||0);
    return sum;
  }catch(_e){ return 0; }
}
window["wlv1PaidTodayForPatient"]=wlv1PaidTodayForPatient;

/** আজ এই রোগীর ইতিমধ্যে approved Refund-এর যোগফল — আজকের জমা থেকে
 *  ইতিমধ্যে কতটা বাদ গেছে তা বাদ দেওয়ার জন্য। */
function wlv1RefundedTodayForPatient(patientRow,excludeId){
  try{
    var d=today();
    var rows=load('payments').filter(function(x){
      if(excludeId && String(x.id)===String(excludeId)) return false;
      return payOwnedBy(x,patientRow) && wlv1IsApprovedRefund(x) && String(x.date||'')===d;
    });
    var sum=0; for(var i=0;i<rows.length;i++) sum+=Number(rows[i].amount||0);
    return sum;
  }catch(_e){ return 0; }
}
window["wlv1RefundedTodayForPatient"]=wlv1RefundedTodayForPatient;

/** ⛔ B445 — Chamber খোলা থাকলেও, আজকের জমা থেকে আজকের approved-refund
 *  বাদ দিয়ে যা থাকে তার বেশি Refund হলে Staff-এর জন্য অটো-অ্যাপ্রুভ না —
 *  Android-এর saveRefund()-এর হুবহু একই নিয়ম, একই জায়গায় থেকে ডাকা হয়
 *  (openRefundFormWeb-এর বোতাম-লেবেল + saveRefundWeb-এর আসল সিদ্ধান্ত)। */
async function wlv1RefundAutoApprove(p, amt, excludeId){
  if(isMaster()) return true;
  var chamberOpen = await wlv1ChamberOpenTodayFailSafe(p.branch);
  if(!chamberOpen) return false;
  var available = Math.max(0, wlv1PaidTodayForPatient(p) - wlv1RefundedTodayForPatient(p, excludeId||''));
  return amt <= available + 0.5;
}
window["wlv1RefundAutoApprove"]=wlv1RefundAutoApprove;

/** V219 (§1, 31.07.2026) — Refund idempotency (Android PaymentModel.refundIdFor-এর
 *  হুবহু নিয়ম; Java String.hashCode মিলিয়ে দুই প্ল্যাটফর্মে একই id)। একই রোগী+টাকা+
 *  কারণ+আজকের তারিখ+যিনি করলেন → একই id, তাই cloud-এ না গিয়ে আবার চাপলে upsert
 *  পুরোনো row-ই overwrite করে — দ্বিতীয় Refund তৈরি হয় না। */
function wlv1JavaHash(s){ var h=0; for(var i=0;i<s.length;i++){ h=(Math.imul(31,h)+s.charCodeAt(i))|0; } return h; }
function wlv1RefundIdFor(p,amt,reason,req,nonce){
  var mob=String((p&&p.mobile)||'').replace(/\D/g,'').slice(-10);
  var amtCents=Math.round(Number(amt||0)*100);
  var d=today();
  var reqD=String(req||'').replace(/\D/g,'').slice(-10);
  // V220 (§4): nonce — একই ফর্মের retry একই id (double নয়); নতুন ফর্মে করা বৈধ
  // দ্বিতীয় Refund আলাদা id। nonce ফাঁকা হলে আগের V219 আচরণ।
  // V222 (§2): raw-এর সামনে patient.id — এক মোবাইলে দুই আলাদা রোগীর id কখনো মেলে না।
  // ⛔ Android PaymentModel.refundIdFor-এর raw-এর সঙ্গে হুবহু এক ক্রম (hashCode parity)।
  var raw=String((p&&p.id)||'')+'|'+mob+'|'+amtCents+'|'+String(reason||'').trim().toLowerCase()+'|'+d+'|'+reqD+'|'+String(nonce||'');
  var hex=(wlv1JavaHash(raw)>>>0).toString(16);
  return 'rfnd_'+mob+'_'+amtCents+'_'+String(d).replace(/-/g,'')+'_'+hex;
}
window["wlv1RefundIdFor"]=wlv1RefundIdFor;

/* 🔒 V221 (§3, 31.07.2026): Refund nonce persist — Android PaymentRepository-এর
   হুবহু একই নিয়ম (Android+Web parity)। আগে nonce ছিল শুধু memory-তে
   (window.__wlv1RefundNonce, ফর্ম-খোলায়); reload/crash-এ হারিয়ে গেলে একই
   অসম্পূর্ণ Refund আবার করলে আলাদা id হয়ে Duplicate হতে পারত। এখন nonce
   localStorage-এ draft-key ধরে রাখা হয় (রোগী+টাকা+কারণ+আজকের তারিখ):
     • একই অসম্পূর্ণ Refund আবার → একই persist-করা nonce → একই id (Duplicate নয়)।
     • cloud-এ সত্যিই বসলে (okC) তবেই মোছা হয় — তাই confirm-এর পরে করা বৈধ আলাদা
       Refund নতুন nonce → আলাদা id পায় (একই দিনে দুটি বৈধ আলাদা Refund অক্ষত)।
   ⛔ পুরোপুরি লোকাল — কোনো নতুন cloud read/write নয়। Refund total/approval/
      Visit Fee/branch/payment হিসাব কিছুই বদলায়নি। */
function wlv1RefundDraftKey(p,amt,reason){
  var mob=String((p&&p.mobile)||'').replace(/\D/g,'').slice(-10);
  var amtCents=Math.round(Number(amt||0)*100);
  // V222 (§2): key-এর সামনে patient.id — এক মোবাইলে দুই আলাদা রোগীর draft-key
  // কখনো মেলে না, তাই তাদের nonce ও Refund id আলাদা থাকে (Android-এর সঙ্গে সমান)।
  return String((p&&p.id)||'')+'|'+mob+'|'+amtCents+'|'+String(reason||'').trim().toLowerCase()+'|'+today();
}
function wlv1GetRefundNonce(key){
  try{
    var m=JSON.parse(localStorage.getItem('rk_refund_nonce')||'{}');
    if(m[key]) return m[key];
    var n=(wlv1JavaHash(key+'|'+Date.now()+'|'+Math.random())>>>0).toString(16);
    m[key]=n; localStorage.setItem('rk_refund_nonce',JSON.stringify(m)); return n;
  }catch(_e){ return ''; }
}
function wlv1ClearRefundNonce(key){
  try{
    var m=JSON.parse(localStorage.getItem('rk_refund_nonce')||'{}');
    if(key in m){ delete m[key]; localStorage.setItem('rk_refund_nonce',JSON.stringify(m)); }
  }catch(_e){}
}
window["wlv1RefundDraftKey"]=wlv1RefundDraftKey;
window["wlv1GetRefundNonce"]=wlv1GetRefundNonce;
window["wlv1ClearRefundNonce"]=wlv1ClearRefundNonce;

/* TK-নির্দেশ (02.08.2026): কম্পিউটারেও (ওয়েব) Refund-এর নিয়ম ফোনের সাথে
   মিলিয়ে — সেই ব্রাঞ্চের আজকের Chamber বন্ধ না হওয়া পর্যন্ত Staff নিজেই
   Refund করতে পারবেন (টাকা যেদিনই জমা হোক), Master লাগবে না। Chamber বন্ধ
   হয়ে গেলে Master-এর অনুমতি লাগবে। বিদ্যমান `chamber_close` টেবিল/id-ফরম্যাট
   (`wlv1MarkChamberClosed`-এর সাথে হুবহু মিলিয়ে — branch.toUpperCase()+'|'+
   date, "close_..." নয়, যেটা wlv1ChamberClosedFor ভুলভাবে ব্যবহার করে) ব্যবহার
   হয়েছে। ⛔ নিরাপত্তা: ক্লাউডে যাচাই করা না গেলে (অফলাইন/এরর) — নিরাপদ দিকেই
   "বন্ধ" ধরা হয় (Master চাওয়া হবে), "খোলা" ধরে ছেড়ে দেওয়া হয় না। */
async function wlv1ChamberOpenTodayFailSafe(branch){
  try{
    if(!branch) return true;
    var id=String(branch).trim().toUpperCase()+'|'+today();
    // ১. এই কম্পিউটারেই বন্ধ করা হয়ে থাকলে (লোকাল ক্যাশে) — নেট ছাড়াই নিশ্চিত বন্ধ।
    if((load('chamber_close')||[]).some(function(r){ return r && String(r.id)===id })) return false;
    // ২. ক্লাউডে সত্যিই যাচাই — ব্যর্থ হলে (অফলাইন/এরর/sb না থাকলে) নিরাপদ দিকেই "বন্ধ" ধরা হয়।
    if(typeof sb==='undefined' || !sb) return false;
    var res=await sb.from('chamber_close').select('id').eq('id',id).limit(1);
    if(res.error || !Array.isArray(res.data)) return false;
    return res.data.length===0; // সত্যিই কোনো সারি নেই — তখনই "খোলা"
  }catch(_e){ return false; }
}
window["wlv1ChamberOpenTodayFailSafe"]=wlv1ChamberOpenTodayFailSafe;

async function openRefundFormWeb(patientId){
  var p=load('patients').find(function(x){ return x.id===patientId; });
  if(!p) return toast('Patient not found');
  // 🔒 V220 (§4): ফর্ম একবার খোলার জন্য একটা nonce। cloud-fail-এ ফর্ম খোলা
  // থাকে → আবার Save চাপলে একই nonce = একই Refund (double নয়)। নতুন করে ফর্ম
  // খুললে নতুন nonce = একই দিনের বৈধ দ্বিতীয় Refund আলাদা।
  try{ window.__wlv1RefundNonce = ((wlv1JavaHash(patientId+'|'+Date.now()+'|'+Math.random())>>>0).toString(16)); }catch(_e){ window.__wlv1RefundNonce=''; }
  var paidNow=wlv1PatientPaidNow(p);
  // 🔴 V509 (TK-সিদ্ধান্ত): ঠিক কতটা ফেরত দেওয়া যাবে সেটা ফর্মেই দেখানো হয়,
  //    আর Visit Fee আলাদা থাকলে সেটাও ভেঙে বলা হয় — নইলে "Paid ₹0" দেখে
  //    মনে হত ফেরত দেওয়াই যাবে না। ফোনের অ্যাপে হুবহু একই লাইন।
  var refundableNow=wlv1RefundableNow(p);
  var vfNow=wlv1VisitFeePaidNow(p);
  var autoApprove = isMaster() || await wlv1ChamberOpenTodayFailSafe(p.branch);
  modal(`<h2>💸 Refund</h2>
   <div class="card"><b>${esc(String(p.name||'').toUpperCase())}</b> · ${esc(p.patientId||'')}<br>
   <small>Paid ₹${esc(numFmt(paidNow))}</small><br>
   <small style="color:#0A7A45;font-weight:700">Refundable now: ₹${esc(numFmt(refundableNow))}${vfNow>0?' (Visit Fee ₹'+esc(numFmt(vfNow))+' included)':''}</small></div>
   <label>Refund Amount (₹)</label>
   <input id="rfAmt" class="input" inputmode="numeric" placeholder="0">
   <label>Mode</label>
   <select id="rfMode" class="input"><option>CASH</option><option>ONLINE</option></select>
   <label>Reason</label>
   <input id="rfReason" class="input" placeholder="Refund reason">
   <div class="actions">
     <button class="ghost" onclick="closeModal()">Cancel</button>
     <button style="background:linear-gradient(135deg,#b23a2e,#d9534f)" onclick="saveRefundWeb('${esc(patientId)}')">${autoApprove?'Refund now':'Send refund request'}</button>
   </div>`);
}
window["openRefundFormWeb"]=openRefundFormWeb;

async function saveRefundWeb(patientId){
  try{
    var p=load('patients').find(function(x){ return x.id===patientId; });
    if(!p) return toast('Patient not found');
    var amt=Number(($('#rfAmt')&&$('#rfAmt').value||'').trim());
    if(!amt||amt<=0) return toast('Enter a valid refund amount');
    var mode=($('#rfMode')&&$('#rfMode').value)||'CASH';
    var reason=(($('#rfReason')&&$('#rfReason').value)||'').trim();
    var isM=isMaster();
    // V219 (§1): deterministic id — আবার চাপলে দ্বিতীয় Refund তৈরি হয় না।
    // V221 (§3): persist-করা nonce — crash/reload-এও একই অসম্পূর্ণ Refund একই id।
    var _rfKey=wlv1RefundDraftKey(p,amt,reason);
    var _rfNonce=wlv1GetRefundNonce(_rfKey);
    var rid=wlv1RefundIdFor(p,amt,reason,(user&&user.mobile)||'',_rfNonce);
    // 🔒 TK-নির্দেশ (02.08.2026): UI-তে দেখানো লেবেলের উপর ভরসা না করে এখানে
    // ফের সত্যিই যাচাই করা হয় (ফর্ম খোলা আর Save চাপার মাঝে Chamber বন্ধ হয়ে
    // যেতে পারে) — ঠিক Android-এর saveRefund()-এর মতোই একই ফাংশন পুনর্ব্যবহার।
    var autoApprove = await wlv1RefundAutoApprove(p, amt, rid);
    // 🔴 V509 (TK-সিদ্ধান্ত): সীমা এখন চিকিৎসার জমা **+ Visit Fee** — ফোনের
    //    অ্যাপের `refundableTotal`-এর হুবহু একই নিয়ম, তাই দুই জায়গায় এক ফল।
    var paidNow=wlv1RefundableNow(p);
    var pending=wlv1PendingRefundSum(p,rid); // এই একই refund বাদ দিয়ে (retry হলে যেন না আটকায়)
    var maxRefundable=Math.max(0,paidNow-pending);
    if(amt>maxRefundable+0.5) return toast('Refund ₹'+numFmt(amt)+' is more than the refundable amount ₹'+numFmt(maxRefundable));
    var row={id:rid,payType:'refund',payLabel:'Refund',paymentLabel:'Refund',
      patientId:p.id,patientCode:p.patientId||'',mobile:p.mobile,branch:p.branch,name:p.name,
      date:today(),amount:amt,mode:mode,remarks:reason||'Refund',
      refundReason:reason,refundApprovalStatus:autoApprove?'approved':'pending',
      refundRequestedBy:(user&&user.mobile)||'',refundApprovedBy:autoApprove?((user&&user.mobile)||''):'',
      receivedBy:(user&&user.mobile)||'',createdBy:(user&&user.mobile)||'',
      createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
    // V219 (§1): local-এও একই id-র পুরোনো row থাকলে সরিয়ে একটাই রাখা হয় (add
    // দুবার হলে দুটো local row হত), তারপর add — cloud upsert একই id-তে idempotent।
    try{ save('payments', load('payments').filter(function(x){ return String(x.id)!==String(rid); })); }catch(_e){}
    add('payments',row);
    var okC=true; try{ okC=await directCloudUpsertRow('payments',row) }catch(_e){ okC=false }
    if(!okC){ return toast('Could not save to cloud — check internet and try again'); }
    // 🔒 V221 (§3): cloud-এ সত্যিই বসল — এখন nonce মুছি, যাতে পরে করা বৈধ আলাদা
    // Refund নতুন nonce → আলাদা id পায়। (fail হলে উপরে return, nonce রেখে দেওয়া হয়।)
    try{ wlv1ClearRefundNonce(_rfKey); }catch(_e){}
    if(!autoApprove){
      try{
        // V219 (§1): request briefing-এরও deterministic id — retry-তে দ্বিতীয় ঘন্টা-notice হয় না।
        var req={id:'brief_'+rid,date:today(),title:'Refund request — '+(p.name||normMob(p.mobile||'')),
          message:'₹'+numFmt(amt)+' refund requested for '+(p.name||p.mobile||'')+
                   '\nPatient ID : '+(p.patientId||'')+'\nBranch : '+(p.branch||'')+
                   '\nReason : '+(reason||'—')+'\nRequested by : '+(codeName(user&&user.mobile)||'')+
                   '\nApprove/Reject from the bell.',
          targets:{roles:['master']},branch:p.branch||'',seen:[],replies:[],
          createdBy:(user&&user.mobile)||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
        // V219 (§1): local-এও একই briefing id থাকলে সরিয়ে একটাই রাখা হয়, তারপর add।
        try{ save('briefings', load('briefings').filter(function(x){ return String(x.id)!==('brief_'+rid); })); }catch(_e){}
        add('briefings',req); await cloudUpsertBriefing(req);
      }catch(_e){}
    }
    toast(autoApprove?('Refund saved ✓ — ₹'+numFmt(amt)+' reduced from collection'):'Refund request sent — will reduce the total once Master approves');
    closeModal();
    try{ paymentHistory(patientId) }catch(_e){}
  }catch(e){ toast('Could not save refund — try again'); }
}
window["saveRefundWeb"]=saveRefundWeb;
async function wlv1DeletePayment(payId){
  // 🔒 B334-এর মতোই আসল-দুর্ঘটনার পুনরাবৃত্তি ঠিক করে রাখা: confirm() পপ-আপ
  // ওঠার আগের await-গুলোর সময় দ্রুত দুইবার চাপলে দুটো আলাদা কল শুরু হতে
  // পারে — একই payId-এর জন্য দ্বিতীয় কল সঙ্গে সঙ্গে বাদ।
  if(wlv1DeleteInFlight.has(payId)) return;
  wlv1DeleteInFlight.add(payId);
  try{
    await wlv1DeletePaymentImpl(payId);
  } finally {
    wlv1DeleteInFlight.delete(payId);
  }
}
window["wlv1DeletePayment"]=wlv1DeletePayment;
async function wlv1DeletePaymentImpl(payId){
  try{
    var all=load('payments'), i=all.findIndex(function(x){ return String(x.id)===String(payId) });
    if(i<0) return toast('Payment row not found');
    var row=all[i];
    var amtT='₹'+numFmt(row.amount);
    var label=row.payLabel||row.paymentLabel||row.payType||'Payment';

    // 🔴 B303.1: Draft-Delete-এর সাথে একই ফিক্স — এখানেও একই গর্ত ছিল।
    await wlv1PullChamberCloseFromCloud();
    // 🆕 (03.08.2026, TK-অনুমোদনে): Master-এর দেওয়া ব্যাকডেট-Grant থাকলে
    // যেন এই মুহূর্তেই তা জানা যায় (একই "শুধু Delete চাপার সময়, লিস্ট-লোডে
    // না" নীতি, ফ্রি-প্ল্যান কোটা বাঁচাতে)।
    await wlv1PullBackdateGrantsFromCloud();

    if(!wlv1CanDeletePaymentNow(row, true) && !wlv1IsBackdateGranted(String(row.date||'').slice(0,10))){
      if(!confirm(amtT+' ('+label+')\n\n⛔ এখনই কিছুই মুছবে না।\nMaster-এর ঘন্টায় অনুরোধ যাবে; তিনি অনুমোদন দিলে তবেই ডিলিট হবে।\n\nঅনুরোধ পাঠাব?')) return;
      var req={id:uid('brief'),date:today(),title:'🗑️ Delete request — '+(row.name||normMob(row.mobile||'')),
        message:'Delete permission request\nType : Payment\nName : '+(row.name||'')+'\nMobile : '+normMob(row.mobile||'')+
                '\nPatient ID : '+(row.patientCode||'')+'\nBranch : '+(row.branch||'')+'\nRow ID : '+row.id+
                '\nRequested by : '+(codeName(user&&user.mobile)||'')+'\nReason : '+amtT+' ('+label+')',
        targets:{roles:['master']},branch:row.branch||'',seen:[],replies:[],
        createdBy:(user&&user.mobile)||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
      add('briefings',req);
      try{ await cloudUpsertBriefing(req) }catch(_e){}
      return toast('Master-কে অনুরোধ পাঠানো হয়েছে');
    }

    if(!confirm(amtT+' ('+label+')\n\nএই টাকার সারিটা Trash-এ যাবে (পরে ফেরানো যাবে)।\nরোগীর জমা/বকেয়ার হিসাব বদলাবে।\n\nমুছবেন?')) return;

    /* আগে Trash-এ নকল — না পারলে কিছুই মোছা হবে না */
    /* 🔒 খাতার সারি B168: আইডি আর এলোমেলো নয় — ফোনের হুবহু একই নিয়মে
       রেকর্ড ধরে বাঁধা (সারি B165), তাই বারবার চেষ্টা করলেও Trash-এ
       একটাই এন্ট্রি থাকে, আর ফোন-কম্পিউটার দুই জায়গা থেকে মুছলেও নয়। */
    var t={id:wlv1TrashIdFor('payments',row.id),
           table:'payments',record:row,deletedAt:new Date().toISOString(),deletedBy:(user&&user.mobile)||''};
    add('trash',t);
    var okT=true; try{ okT=await directCloudUpsertRow('trash',t) }catch(_e){ okT=false }
    if(!okT) return toast('Trash-এ রাখা গেল না — কিছুই মোছা হয়নি');

    /* 🔒🔒 খাতার সারি B168 (TK-এর ৫ নম্বর সন্দেহ): আগে ক্লাউডের ডিলিটের
       **ফল দেখাই হত না** — লাইন কেটে গেলেও পর্দায় "Payment deleted"
       দেখাত, অথচ সারিটা ক্লাউডে রয়ে যেত ও পরের merge-এ **টাকাটা আবার
       ফিরে আসত**। এখন ক্লাউডে সত্যিই মোছার পরেই এই কম্পিউটার থেকে মোছা
       হয়; না পারলে **কিছুই মোছা হয় না**, তাই হিসাব কখনো দুরকম হবে না। */
    var goneP=await wlv1CloudDeleteRow('payments',row.id);
    if(!goneP) return toast('Cloud-এ মোছা গেল না — কিছুই মোছা হয়নি, আবার চেষ্টা করুন');
    all.splice(i,1); put('payments',all);
    /* ডিলিটের চিহ্ন ক্লাউডে — নইলে কোনো ফোনে ওই সারির পুরনো কপি থাকলে
       সেটা আবার ক্লাউডে উঠে যেতে পারত (ফোনের সেই একই পাহারা, সারি B138)। */
    try{ await wlv1MarkDeletedCloud('payments',row.id) }catch(_e){}

    /* মাস্টারকে খবর — চালু briefings ব্যবস্থাতেই */
    try{
      var n={id:uid('brief'),date:today(),title:'🗑️ Payment deleted — '+(row.name||normMob(row.mobile||'')),
        message:amtT+' ('+label+') · '+(row.branch||'')+'\nDeleted by : '+(codeName(user&&user.mobile)||'')+'\nTrash Bin থেকে ফেরানো যাবে।',
        targets:{roles:['master']},branch:row.branch||'',seen:[],replies:[],
        createdBy:(user&&user.mobile)||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
      add('briefings',n); await cloudUpsertBriefing(n);
    }catch(_e){}

    toast('Payment deleted — Master informed');
    try{ closeModal() }catch(_e){}
  }catch(e){
    try{ toast('মোছা গেল না — আবার চেষ্টা করুন') }catch(_e){}
  }
}
window["wlv1DeletePayment"]=wlv1DeletePayment;

/* =====================================================================
   🔒 খাতার সারি B122 — ▤ Table ভিউ + ডান পাশে রোগীর প্যানেল (কম্পিউটার)
   TK-এর প্রুফে পাশ: বড় হসপিটাল CRM-এর মতো — মাঝে তালিকা টেবিল আকারে,
   ডানে নির্বাচিত রোগীর পুরো ছবি।

   🔒 কেন ঝুঁকিহীন:
   ⛔ **কার্ডের চেহারা ও কোড এক অক্ষরও বদলায়নি** — কার্ডই ডিফল্ট, টেবিল
      দেখতে হলে বোতামে চাপতে হয়। আবার চাপলে কার্ডে ফিরে আসে।
   ⛔ টেবিলটা **আলাদা একটা ঘরে** বানানো হয়, কার্ডের ঘরটা শুধু লুকিয়ে
      রাখা হয় — মোছা হয় না, তাই ফিরে আসতে কিছু হারায় না।
   ⛔ **ক্লাউডে একটাও অনুরোধ নেই · ডেটাবেসে কিছু লেখা হয় না** — যে সারি
      পর্দায় আছে সেগুলোই টেবিলে সাজানো হয় (কোটার নিয়ম)।
   ⛔ ব্রাঞ্চের নিয়ম অক্ষত — `scoped()` যা দেয় তার বাইরে কিছু নেই।
   ⛔ পুরনো বোতাম · ছাঁকনি · কোনো কাজের নিয়ম ছোঁয়া হয়নি; শুধু একটা
      বোতাম **যোগ**। কিছু ভুল হলে শুধু বার্তা, কার্ডের তালিকা অক্ষত থাকে।
   ===================================================================== */
function wlv1TableRowsFor(stage){
  var base=(typeof mergeFollow==='function')?mergeFollow(window.scoped(frArr('followups'))):window.scoped(frArr('followups'));
  var rows=base.filter(function(x){ return String(x.stage||'')===String(stage) && !isConvertedOrClosed(x) });
  try{
    var f=__followDateFilter;
    if(f&&f.from&&f.to){
      rows=rows.filter(function(x){
        var d=String(x.nextFollow||x.visitDate||x.recordDate||x.registrationDate||x.date||'').slice(0,10);
        return d&&d>=f.from&&d<=f.to;
      });
    }
  }catch(_e){}
  return rows;
}
function wlv1LastCallOf(x){
  var last=x.lastCallDate||'';
  if(!last){ try{ var h=x.history; if(typeof h==='string')h=JSON.parse(h);
    if(Array.isArray(h)) for(var k=h.length-1;k>=0;k--){ var d=(h[k]&&h[k].date)||''; if(String(d).trim()){ last=String(d).slice(0,10); break } } }catch(_e){} }
  return last;
}
function wlv1ToggleTable(stage){
  try{
    var host=document.getElementById('followRows');
    if(!host) return toast('তালিকা এখনো তৈরি হয়নি');
    var old=document.getElementById('wlv1TableWrap');
    if(old){ old.remove(); host.style.display=''; return toast('Card view'); }

    var rows=wlv1TableRowsFor(stage||'Inquiry');
    if(!rows.length) return toast('তালিকা ফাঁকা');

    window.__wlv1TableRows=rows;
    var body=rows.map(function(x,i){
      var lc=wlv1LastCallOf(x);
      return '<tr onclick="wlv1TablePick('+i+')" data-i="'+i+'">'
        + '<td>'+(i+1)+'</td>'
        + '<td><b>'+esc(x.name||frNorm(mob(x.mobile)))+'</b><br><small>'+esc(normMob(x.mobile||''))+'</small></td>'
        + '<td>'+esc(String(x.branch||'-'))+'</td>'
        + '<td>'+esc(String(x.disease||'-'))+'</td>'
        + '<td>'+(lc?esc(fmtDate(lc)):'—')+'</td>'
        + '<td>'+(x.nextFollow?esc(fmtDate(x.nextFollow)):'—')+'</td>'
        + '<td>'+esc(String(x.patientId||'—'))+'</td>'
        + '</tr>';
    }).join('');

    var wrap=document.createElement('div');
    wrap.id='wlv1TableWrap';
    wrap.className='wlv1TableWrap';
    wrap.innerHTML =
      '<div class="wlv1TableCard"><table class="wlv1Table"><thead><tr>'
      + '<th>#</th><th>রোগী</th><th>ব্রাঞ্চ</th><th>রোগ</th><th>শেষ কল</th><th>পরের কল</th><th>Patient ID</th>'
      + '</tr></thead><tbody>'+body+'</tbody></table></div>'
      + '<aside class="wlv1Panel" id="wlv1Panel"><div class="wlv1PanelHint">তালিকার একটা সারিতে চাপ দিন</div></aside>';
    host.style.display='none';
    host.parentNode.insertBefore(wrap, host.nextSibling);
    wlv1TablePick(0);
    toast(rows.length+' সারি — Table view');
  }catch(e){
    try{ var h=document.getElementById('followRows'); if(h)h.style.display=''; toast('Table দেখানো গেল না') }catch(_e){}
  }
}
window["wlv1ToggleTable"]=wlv1ToggleTable;
function wlv1TablePick(i){
  try{
    var rows=window.__wlv1TableRows||[]; var x=rows[i]; if(!x) return;
    var w=document.getElementById('wlv1TableWrap'); if(!w) return;
    Array.prototype.forEach.call(w.querySelectorAll('tbody tr'),function(tr){
      tr.classList.toggle('sel', String(tr.getAttribute('data-i'))===String(i));
    });
    var p=document.getElementById('wlv1Panel'); if(!p) return;
    var t={bill:0,paid:0,due:0};
    try{ var pt=load('patients').find(function(q){ return mob(q.mobile)===mob(x.mobile) }); if(pt) t=treatmentTotals(pt) }catch(_e){}
    var hist=[]; try{ var h=x.history; if(typeof h==='string')h=JSON.parse(h); if(Array.isArray(h)) hist=h.slice(-4).reverse() }catch(_e){}
    p.innerHTML =
      '<div class="wlv1PanelHead"><b>'+esc(x.name||normMob(x.mobile||''))+'</b>'
      + '<small>'+esc(normMob(x.mobile||''))+'</small>'
      + '<small>'+esc(String(x.branch||'-'))+' · '+esc(String(x.disease||'-'))+'</small>'
      + '<small>'+esc(String(x.patientId||''))+'</small></div>'
      + '<div class="wlv1PanelMoney"><div><small>বিল</small><b>'+(t.bill?money(t.bill):'—')+'</b></div>'
      + '<div><small>জমা</small><b>'+money(t.paid||0)+'</b></div>'
      + '<div><small>বাকি</small><b>'+(t.due?money(t.due):'—')+'</b></div></div>'
      + '<div class="wlv1PanelSec"><p>শেষ রিমার্ক</p>'+esc(x.lastRemark||'No remark')+'</div>'
      + '<div class="wlv1PanelSec"><p>সাম্প্রতিক</p>'
      + (hist.length?hist.map(function(h){ return '<div class="wlv1Tl"><b>'+esc(h.remark||'')+'</b><small>'+esc(fmtDate(h.date||''))+' · '+esc(codeName(h.staff||''))+'</small></div>' }).join(''):'<small class="mut">কিছু নেই</small>')
      + '</div>'
      + '<div class="wlv1PanelAct">'
      + '<button class="small" onclick="contact(\''+esc(x.mobile)+'\',\'call\')">📞 কল</button>'
      + '<button class="small ghost" onclick="contact(\''+esc(x.mobile)+'\',\'wa\')">💬 WhatsApp</button>'
      + '<button class="small ghost" onclick="viewFollow(\''+esc(x.id)+'\')">👁 View All</button>'
      + '<button class="small ghost" onclick="nextFollowDate(\''+esc(x.id)+'\')">⏰ পরের তারিখ</button>'
      + '</div>';
  }catch(_e){}
}
window["wlv1TablePick"]=wlv1TablePick;

