var WLV1_NOBN_MOBILES=['6207841890'];
var WLV1_NOBN_CODES=['KNE-KISHAN5'];
function wlv1NoBnActive(){
  try{
    if(typeof user==='undefined'||!user)return false;
    var ten=String(user.mobile||'').replace(/\D/g,'').slice(-10);
    var nm=String(user.name||'').trim().toUpperCase();
    var role=String(user.role||'').trim().toLowerCase();
    var br=String(user.branch||'').trim().toLowerCase();

    /* 🔒 V451 (19.08.2026, TK-approved): person-specific নয় — Kishanganj
       branch-এর সব Staff account, including KNE-BRANCH branch-number login,
       English-only display পাবে। Doctor/Master/Field ও অন্য branch অপরিবর্তিত। */
    if(role==='staff'&&br==='kishanganj')return true;

    /* পুরনো KNE-KISHAN5 fallback রাখা হয়েছে যাতে অসম্পূর্ণ legacy session-এও
       আগের নিরাপত্তা নষ্ট না হয়। */
    return WLV1_NOBN_MOBILES.indexOf(ten)>=0||WLV1_NOBN_CODES.indexOf(nm)>=0;
  }catch(_e){return false}
}
function wlv1HasBn(s){return /[\u0980-\u09FF]/.test(String(s||''))}
function wlv1NoBnFix(t){
  var s=String(t==null?'':t);
  if(!wlv1HasBn(s))return s;
  var k=s.trim();
  if(WLV1_NOBN_WHOLE[k]!==undefined)return WLV1_NOBN_WHOLE[k];
  /* 🔒 শুরুর ও শেষের ফাঁকা/নতুন-লাইন হুবহু রেখে দেওয়া হয় — নইলে দুটো লাইন
     এক লাইনে জুড়ে যেত (ফোনেও একই সুরক্ষা) */
  var lead=(s.match(/^\s*/)||[''])[0], tail=(s.match(/\s*$/)||[''])[0];
  s=s.trim();
  for(var i=0;i<WLV1_NOBN_MAP.length;i++){
    if(s.indexOf(WLV1_NOBN_MAP[i][0])>=0)s=s.split(WLV1_NOBN_MAP[i][0]).join(WLV1_NOBN_MAP[i][1]);
  }
  if(wlv1HasBn(s))s=s.replace(/[\u0980-\u09FF]/g,'');   /* শেষ জাল */
  s=s.replace(/\u0964/g,'.');
  while(s.indexOf('  ')>=0)s=s.split('  ').join(' ');
  s=s.replace(' ·  ',' · ').replace('· ·','·').replace(' .','.').trim();
  return lead+s+tail;
}
function wlv1NoBnSweep(root){
  if(!wlv1NoBnActive())return;
  try{
    var node=root||document.body;
    if(!node)return;
    var w=document.createTreeWalker(node,NodeFilter.SHOW_TEXT,null,false),n;
    var jobs=[];
    while((n=w.nextNode())){
      var tag=n.parentNode&&n.parentNode.nodeName;
      if(tag==='SCRIPT'||tag==='STYLE'||tag==='TEXTAREA')continue;   /* ⛔ লেখার ঘর নয় */
      if(wlv1HasBn(n.nodeValue))jobs.push(n);
    }
    for(var i=0;i<jobs.length;i++){
      var fixed=wlv1NoBnFix(jobs[i].nodeValue);
      if(fixed!==jobs[i].nodeValue)jobs[i].nodeValue=fixed;
    }
    /* placeholder-ও বাংলা-মুক্ত করা হয় (এটা কোথাও সেভ হয় না),
       কিন্তু ঘরের নিজের value কখনো ছোঁয়া হয় না */
    var ph=node.querySelectorAll?node.querySelectorAll('[placeholder]'):[];
    for(var j=0;j<ph.length;j++){
      var p=ph[j].getAttribute('placeholder');
      if(wlv1HasBn(p)){var f2=wlv1NoBnFix(p);if(f2!==p)ph[j].setAttribute('placeholder',f2)}
    }
  }catch(_e){}
}
function wlv1NoBnStart(){
  try{
    if(!wlv1NoBnActive())return;
    wlv1NoBnSweep(document.body);
    if(window.__wlv1NoBnObs)return;
    window.__wlv1NoBnObs=new MutationObserver(function(){
      if(window.__wlv1NoBnBusy)return;
      window.__wlv1NoBnBusy=true;
      setTimeout(function(){window.__wlv1NoBnBusy=false;wlv1NoBnSweep(document.body)},60);
    });
    window.__wlv1NoBnObs.observe(document.body,{childList:true,subtree:true,characterData:true});
  }catch(_e){}
}
try{
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(wlv1NoBnStart,300)});
  else setTimeout(wlv1NoBnStart,300);
  setInterval(function(){try{if(wlv1NoBnActive()&&!window.__wlv1NoBnObs)wlv1NoBnStart()}catch(_e){}},4000);
}catch(_e){}
window["wlv1NoBnFix"]=wlv1NoBnFix;window["wlv1NoBnSweep"]=wlv1NoBnSweep;window["wlv1NoBnStart"]=wlv1NoBnStart;

/* ── 📩 ডাক্তারকে চারটে বার্তা (ফোনের `DoctorMessage.kt`-এর হুবহু লেখা) ──
   ⛔ TK নিজে এক এক করে ফাইনাল করেছেন (খাতার সারি B157) — একটা শব্দও
      বদলানো যাবে না। কিশানগঞ্জে হিন্দি/বাংলা বাছাই (সারি B159)। */
function wlv1DocHead(br,hi){var b=wlv1BranchInfo(br);return b.clinic+'\n'+b.address+'\n'+(hi?'फ़ोन: ':'ফোন: ')+b.phone}
function wlv1DocFoot(br,hi){var b=wlv1BranchInfo(br);return (hi?'सादर,':'সবিনয়ে,')+'\nTK BISWAS\nFounder & Consultant\n'+b.clinic+' · '+b.name}
function wlv1DocName(n,m){var t=String(n||'').trim();return (t?t:String(m||'').trim()).toUpperCase()}
function wlv1DocMsg(kind,br,dr,drMob,pt,ptMob,dateText,hi,o){
  o=o||{};
  var D=wlv1DocName(dr,drMob),P=wlv1DocName(pt,ptMob),s='';
  s+=wlv1DocHead(br,hi)+'\n\n'+(hi?'आदरणीय Dr. ':'শ্রদ্ধেয় Dr. ')+D+',\n\n';
  if(kind==='intro'){
    s+=hi?'आज हमारे क्लिनिक की ओर से आपसे बात हुई। समय देने के लिए Thank you सर। हमारे क्लिनिक का परिचय आपको दे रहे हैं।\n\nहमारा इलाज\nPiles · Fissure · Fistula · Hydrocele · Gupt Rog\n\nहमारी विशेषता\nआयुर्वेद की Kshar Sutra पद्धति से बिना ऑपरेशन इलाज। मरीज़ को भर्ती रखने की ज़रूरत नहीं, खर्च आपकी पहुँच में। अनुभवी डॉक्टर की निगरानी में इलाज होता है और हर मरीज़ के ठीक होने तक नियमित follow-up रखा जाता है — इस रोग के इलाज में इस क्षेत्र में हम ही सबसे भरोसेमंद नाम हैं।\n\nReferral\nआपके भेजे हर मरीज़ के लिए हम सही referral income पूरे हिसाब के साथ, समय पर देते हैं।\n\nनिवेदन\nसर, आपके पास इस तरह के मरीज़ हों तो हमारे क्लिनिक में भेजने की व्यवस्था करें, हम आपके आभारी रहेंगे। आपके भेजे मरीज़ की पूरी ज़िम्मेदारी हमारी है।'
          :'আজ আমাদের ক্লিনিকের পক্ষ থেকে আপনার সঙ্গে কথা হলো। সময় দেওয়ার জন্য Thank you স্যার। আমাদের ক্লিনিকের পরিচয় আপনাকে জানাচ্ছি।\n\nআমাদের চিকিৎসা\nPiles · Fissure · Fistula · Hydrocele · Gupt Rog\n\nআমাদের বিশেষত্ব\nআয়ুর্বেদের Kshar Sutra পদ্ধতিতে বিনা অপারেশনে চিকিৎসা। পেশেন্টকে ভর্তি রাখতে হয় না, খরচ সাধ্যের মধ্যে। অভিজ্ঞ ডাক্তারের তত্ত্বাবধানে চিকিৎসা হয় এবং প্রতিটি পেশেন্টের সুস্থ হওয়া পর্যন্ত নিয়মিত follow-up রাখা হয় — এই রোগের চিকিৎসায় এই অঞ্চলে আমরাই সবচেয়ে ভরসার নাম।\n\nReferral\nআপনার পাঠানো প্রতিটি পেশেন্টের জন্য আমরা প্রকৃত referral income সম্পূর্ণ হিসাব সহ, যথাসময়ে দিয়ে থাকি।\n\nঅনুরোধ\nস্যার, আপনার কাছে সেই ধরনের পেশেন্ট থাকলে আমাদের ক্লিনিকে পাঠানোর ব্যবস্থা করলে আমরা কৃতজ্ঞ থাকব। আপনার পাঠানো পেশেন্টের সম্পূর্ণ দায়িত্ব আমাদের।';
  }else if(kind==='arrived'){
    s+=(hi?'आपके भेजे मरीज़ आज हमारे क्लिनिक में आए हैं। आपको यह inform कर रहे हैं।':'আপনার পাঠানো পেশেন্ট আজ আমাদের ক্লিনিকে এসেছেন। আপনাকে সেটা inform করছি।')+'\n\n';
    s+='Patient Name — '+P+'\nDate — '+dateText+'\n\n';
    s+=hi?'मरीज़ का रजिस्ट्रेशन पूरा हो गया है। डॉक्टर के चेकअप के बाद इलाज का update आपको समय पर बता दिया जाएगा।\n\nआपके भरोसे के लिए Thank you सर।'
         :'পেশেন্টের রেজিস্ট্রেশন কমপ্লিট হয়েছে। ডাক্তারের চেকআপের পর চিকিৎসার update আপনাকে যথাসময়ে জানানো হবে।\n\nআপনার ভরসার জন্য Thank you স্যার।';
  }else if(kind==='details'){
    s+=(hi?'आपके भेजे मरीज़ का update आपको बताया जा रहा है।':'আপনার পাঠানো পেশেন্টের update আপনাকে জানানো হচ্ছে।')+'\n\n';
    s+='Patient Name — '+P+'\nVisit Date — '+dateText+'\nTreatment — '+(o.treat||'')+'\nBlood Test — '+(o.blood||'')+'\nNext Visit Date — '+(o.next||'')+'\n\n';
    s+=hi?'मरीज़ का पूरा ध्यान रखा जा रहा है। अगले follow-up की जानकारी भी आपको समय पर दे दी जाएगी।\n\nआपके भरोसे के लिए Thank you सर।'
         :'পেশেন্টের প্রতি সম্পূর্ণ যত্ন নেওয়া হচ্ছে। পরবর্তী follow-up-এর খবরও আপনাকে যথাসময়ে জানানো হবে।\n\nআপনার ভরসার জন্য Thank you স্যার।';
  }else{
    s+=(hi?'आपने जो मरीज़ भेजा था, उस मरीज़ की referral income आपको भेज दी गई है।':'আপনি যে পেশেন্ট পাঠিয়েছিলেন, সেই পেশেন্টের referral income আপনাকে পাঠানো হলো।')+'\n\n';
    s+='Patient Name — '+P+'\nVisit Date — '+dateText+'\nReferral Income — Rs ______\nPayment Mode — ______ (Cash / Online)\nPayment Date — ______\nReference No. — ______\n\n';
    s+=hi?'पैसा मिलने पर एक बार बता दें तो अच्छा रहेगा सर। कोई दिक्कत हो तो ऊपर दिए नंबर पर बताएँ।\n\nआपके सहयोग के लिए Thank you सर।'
         :'টাকা পেয়ে একবার জানিয়ে দিলে ভালো হয় স্যার। কোনো অসুবিধা হলে উপরের নম্বরে জানাবেন।\n\nআপনার সহযোগিতার জন্য Thank you স্যার।';
  }
  return s+'\n\n'+wlv1DocFoot(br,hi);
}
/* ⛔ কম্পিউটারে WhatsApp Web-এ লেখা নিয়ে যাওয়া যায়, তাই wa.me লিংকই ব্যবহার */
function wlv1DocSend(mob,text){
  var d=String(mob||'').replace(/\D/g,'').slice(-10);
  if(d.length!==10)return toast('Valid 10-digit mobile not found');
  try{window.open('https://wa.me/91'+d+'?text='+encodeURIComponent(text),'_blank')}catch(_e){toast('Could not open WhatsApp')}
}
function wlv1DocIsKishanganj(br){return String(br||'').trim().toLowerCase().indexOf('kishanganj')>=0}
function wlv1DocMsgBar(id){
  return '<div class="actions" style="flex-wrap:wrap;gap:6px">'
    +'<button class="small" onclick="wlv1DocMsgPick(\''+id+'\',\'intro\')">📩 Msg 1 · Intro</button>'
    +'<button class="small" onclick="wlv1DocMsgPick(\''+id+'\',\'arrived\')">📩 Msg 2 · Arrived</button>'
    +'<button class="small" onclick="wlv1DocMsgPick(\''+id+'\',\'details\')">📩 Msg 3 · Details</button>'
    +'<button class="small" onclick="wlv1DocMsgPick(\''+id+'\',\'paid\')">📩 Msg 4 · Referral Paid</button>'
    +'</div>';
}
function wlv1DocById(id){return (load('doctor_visits')||[]).find(function(x){return String(x.id)===String(id)})||null}
function wlv1DocRefs(x){
  var nm=String(x.name||'').trim().toLowerCase(),mb=String(x.mobile||'').replace(/\D/g,'').slice(-10);
  return (load('patients')||[]).filter(function(p){
    var rb=String(p.refBy||'').trim().toLowerCase(),rm=String(p.refDoctorMobile||'').replace(/\D/g,'').slice(-10);
    return (rb&&rb===nm)||(rm&&rm===mb);
  });
}
function wlv1DocMsgPick(id,kind){
  var x=wlv1DocById(id); if(!x)return toast('Doctor not found');
  if(!String(x.branch||'').trim())return toast('This doctor has no branch saved — set the branch first');
  if(!wlv1DocIsKishanganj(x.branch))return wlv1DocMsgLang(id,kind,0);
  modal('<h2>Select Language</h2><div class="card"><div class="actions" style="gap:8px">'
    +'<button class="small" onclick="wlv1DocMsgLang(\''+id+'\',\''+kind+'\',1)">हिन्दी (Hindi)</button>'
    +'<button class="small ghost" onclick="wlv1DocMsgLang(\''+id+'\',\''+kind+'\',0)">বাংলা (Bengali)</button>'
    +'</div></div>');
}
function wlv1DocMsgLang(id,kind,hi){
  closeModal();
  var x=wlv1DocById(id); if(!x)return toast('Doctor not found');
  if(kind==='intro')return wlv1DocSend(x.mobile,wlv1DocMsg('intro',x.branch,x.name,x.mobile,'','','',hi));
  var refs=wlv1DocRefs(x);
  if(!refs.length)return toast('No patient is linked to this doctor yet');
  var rows=refs.map(function(p,i){
    var dt=wlv1Dot(p.visitDate||p.registrationDate||p.date||'');
    return '<button class="small ghost" style="display:block;width:100%;text-align:left;margin-bottom:6px" onclick="wlv1DocMsgGo(\''+id+'\',\''+kind+'\','+hi+','+i+')">'
      +esc(String(p.name||p.mobile).toUpperCase())+' · '+esc(dt)+'</button>';
  }).join('');
  window.__wlv1DocRefs=refs;
  modal('<h2>Select Patient</h2><div class="card">'+rows+'</div>');
}
function wlv1DocMsgGo(id,kind,hi,idx){
  var x=wlv1DocById(id),p=(window.__wlv1DocRefs||[])[idx];
  if(!x||!p)return toast('Not found');
  var dt=wlv1Dot(p.visitDate||p.registrationDate||p.date||'');
  if(kind==='details'){
    closeModal();
    modal('<h2>Patient Details</h2><div class="card">'
      +'<label>Treatment</label><select id="wlv1MT" class="input"><option value="1">Done</option><option value="0">Not done</option></select>'
      +'<label>Blood Test</label><select id="wlv1MB" class="input"><option value="1">Given</option><option value="0">Not given</option></select>'
      +'<label>Next Visit Date</label><input id="wlv1MN" type="date" class="input">'
      +'<button onclick="wlv1DocMsgDetailsGo(\''+id+'\','+hi+','+idx+')">📤 Send</button></div>');
    return;
  }
  closeModal();
  wlv1DocSend(x.mobile,wlv1DocMsg(kind==='paid'?'paid':'arrived',x.branch,x.name,x.mobile,p.name,p.mobile,dt,hi));
}
function wlv1DocMsgDetailsGo(id,hi,idx){
  var x=wlv1DocById(id),p=(window.__wlv1DocRefs||[])[idx];
  if(!x||!p)return toast('Not found');
  var t=($('#wlv1MT')||{}).value==='1',b=($('#wlv1MB')||{}).value==='1',nd=($('#wlv1MN')||{}).value||'';
  var o={treat:hi?(t?'कराया गया':'नहीं कराया गया'):(t?'করানো হয়েছে':'করানো হয়নি'),
         blood:hi?(b?'दिया गया':'नहीं दिया गया'):(b?'দেওয়া হয়েছে':'দেওয়া হয়নি'),
         next:nd?wlv1Dot(nd):(hi?'नहीं दिया गया':'দেওয়া হয়নি')};
  closeModal();
  wlv1DocSend(x.mobile,wlv1DocMsg('details',x.branch,x.name,x.mobile,p.name,p.mobile,wlv1Dot(p.visitDate||p.registrationDate||p.date||''),hi,o));
}
window["wlv1DocMsgBar"]=wlv1DocMsgBar;window["wlv1DocMsgPick"]=wlv1DocMsgPick;window["wlv1DocMsgLang"]=wlv1DocMsgLang;
window["wlv1DocMsgGo"]=wlv1DocMsgGo;window["wlv1DocMsgDetailsGo"]=wlv1DocMsgDetailsGo;window["wlv1DocMsg"]=wlv1DocMsg;

/* =====================================================================
   🗑️🔒 খাতার সারি B168 — ওয়েব অ্যাপের Delete ফোনের মতো নিরাপদ করা
   TK-এর ৫ নম্বর সন্দেহ (30.07.2026): "Web App-এর Delete ব্যবস্থা
   Android-এর মতো নিরাপদ নয়। Payment Delete-এর ক্ষেত্রেও Cloud Delete
   ব্যর্থ হয়েছে কি না না দেখেই স্থানীয়ভাবে Delete সফল দেখানোর পথ আছে।"
   TK-এর অনুমতি: "করুন"।

   ⛔ চালু কোনো কোডে হাত পড়েনি — সবই ফাইলের শেষে নতুন করে যোগ, আর পুরনো
      ফাংশনটা `window.<নাম>` বদলে ঢাকা হয়েছে (প্রজেক্টের চালু নিয়ম)।
   ⛔ কোনো ডিজাইন · টাকার হিসাব · ব্রাঞ্চের ছাঁকনি বদলায়নি।
   ⛔ SQL লাগবে না — `deleted_records` টেবিলটা 29.07.2026-এ TK নিজেই
      বানিয়েছেন (খাতার সারি B139)।
   ===================================================================== */

/* ক্লাউড থেকে সত্যিই মোছা — সফল/ব্যর্থ ফেরত দেয় (আগে ফল দেখাই হত না)। */
async function wlv1CloudDeleteRow(table,id){
  try{
    if(!table||!id) return false;
    let ok=await initCloudClientOnly();
    if(!ok||!sb) return false;
    let r=await sb.from(table).delete().eq('id',id);
    return !(r&&r.error);
  }catch(e){ return false }
}
window["wlv1CloudDeleteRow"]=wlv1CloudDeleteRow;

/* ডিলিটের চিহ্ন ক্লাউডে লেখা — ফোনের `DeletedGuard`-এর হুবহু একই ঘর ও একই
   আইডির ধাঁচ (`table|id`), তাই কম্পিউটার থেকে মোছা জিনিস ফোনগুলোও জেনে যায়।
   ⛔ রোগীর কোনো তথ্য বা টাকা এখানে যায় না। ব্যর্থ হলে কিছুই ভাঙে না। */
async function wlv1MarkDeletedCloud(table,id){
  try{
    if(!table||!id) return false;
    let ok=await initCloudClientOnly();
    if(!ok||!sb) return false;
    let row={id:String(table)+'|'+String(id),tableName:String(table),rowId:String(id),
             deletedBy:(user&&user.mobile)||'',deletedAt:new Date().toISOString()};
    let r=await sb.from('deleted_records').upsert([row],{onConflict:'id'});
    return !(r&&r.error);
  }catch(e){ return false }
}
window["wlv1MarkDeletedCloud"]=wlv1MarkDeletedCloud;

/* Restore করলে চিহ্নটা ক্লাউড থেকে তুলে দেওয়া — নইলে ফেরানো রেকর্ডকে
   ফোনগুলো "মুছে ফেলা" ভেবে আটকে রাখত (খাতার সারি B167-এর একই নিয়ম)। */
async function wlv1UnmarkDeletedCloud(table,id){
  try{ return await wlv1CloudDeleteRow('deleted_records',String(table)+'|'+String(id)) }
  catch(e){ return false }
}
window["wlv1UnmarkDeletedCloud"]=wlv1UnmarkDeletedCloud;

/* 🔴🔴🔒 V510 (২১.০৮.২০২৬, TK-রিপোর্ট — KAMAL ROY) — **Restore-এর সঙ্গে
   লুকিয়ে যাওয়া ফলো-আপ সারিগুলোও খুলে দেওয়া।**

   ⛔ ওয়েবে এই কাজটা **ছিলই না** (অ্যান্ড্রয়েডে `TrashRepository.restore()`-এ
      ছিল)। তাই ওয়েব থেকে Restore করলে রোগী ফিরত, কিন্তু তাঁর ফলো-আপ কার্ড
      চিরকাল লুকানো থাকত।

   ⛔ ডেটাবেসের দুটো ট্রিগার এখানে মানতেই হয় (লাইভ DB থেকে হুবহু পড়া):
      · `tk_block_deleted_return` — `deleted_records`-এ চিহ্ন থাকলে লেখা
        চুপচাপ বাতিল। ⇒ **আগে চিহ্ন তোলা** হয়।
      · `tk_terminal_no_return` — Cancelled সারিকে Active করা যায় **শুধু
        তখনই**, যখন `history`-র শেষ এন্ট্রিতে status="Active" আর remark শুরু
        "Restored" দিয়ে। ⇒ ঠিক সেই লাইনটা **শেষে যোগ** করা হয়।

   ⛔ পুরোনো `history` কখনো মোছা হয় না — শেষে একটা লাইন যোগ হয় (কে · কবে · কেন)।
   ⛔ ব্যর্থ হলে চুপচাপ ফিরে আসে; মূল Restore আটকায় না।                     */
async function wlv1RestoreCascadedFollowups(trashRow){
  try{
    let arr=(trashRow&&trashRow.cascadedFollowups)||null;
    if(!Array.isArray(arr)||!arr.length)return false;
    let ok=await initCloudClientOnly(); if(!ok||!sb)return false;
    let who=''; try{ who=(typeof user!=='undefined'&&user&&user.mobile)?String(user.mobile):'' }catch(e){}
    let stamp=new Date().toISOString().replace(/(\.\d{3})\d*Z$/,'$1Z');
    for(const it of arr){
      try{
        let fid=String((it&&it.id)||''); if(!fid)continue;
        let st=String((it&&it.status)||''); if(!st)continue;
        let ctable=String((it&&it.table)||'followups')||'followups';
        /* ১) আগে "মুছে ফেলা" চিহ্ন তোলা */
        await wlv1UnmarkDeletedCloud(ctable,fid);
        /* ২) সারিটা পড়ে নেওয়া (history হারাতে দেওয়া যাবে না) */
        let r=await sb.from(ctable).select('*').eq('id',fid).limit(1);
        if(r&&r.error)continue;
        let row=(r&&Array.isArray(r.data)&&r.data[0])?r.data[0]:null;
        if(!row)continue;
        row.status=st;
        if(ctable==='followups'&&String(st).toLowerCase()==='active'){
          let h=Array.isArray(row.history)?row.history.slice():[];
          h.push({status:'Active',remark:'Restored from Trash',at:stamp,by:who});
          row.history=h;
        }
        await directCloudUpsertRow(ctable,row);
        try{ add(ctable,row) }catch(e){}
      }catch(e){}
    }
    return true;
  }catch(e){ return false }
}
window["wlv1RestoreCascadedFollowups"]=wlv1RestoreCascadedFollowups;

/* ── Trash থেকে Restore ─────────────────────────────────────────────
   পুরনো `restoreTrash()` যা করত: রেকর্ডটা শুধু **এই কম্পিউটারে** ফিরিয়ে
   দিত ও Trash সারিটা শুধু এখান থেকেই মুছত — ক্লাউডে কিছুই হত না।
   ফল: ক্লাউডে Trash সারিটা থেকে যেত (অন্য কেউ আবার Restore দেখত), আর
   ফোনে বসানো "মুছে ফেলা" চিহ্নটা থেকে যাওয়ায় **ফেরানো রেকর্ড ফোনে
   আটকেই থাকত**।
   ⛔ পুরনো ফাংশনটা মোছা হয়নি — শুধু ঢাকা হয়েছে।                       */
/* 🔒 V223 (§C1, 01.08.2026): Restore-নিরাপদ — cloud-এ ঐ id-র বর্তমান updatedAt।
   ফেরত: **-2 = পড়া ব্যর্থ/cloud নেই** (নতুনত্ব নিশ্চিত করা যায়নি → restore বন্ধ করতে হবে)
        · **-1 = ঐ row cloud-এ নেই** (নিরাপদ নতুন insert) · **>=0 = updatedAt ms**
        (0 = অজানা/পার্স হয়নি)। এই পার্থক্যই "পড়া ব্যর্থ হলে আন্দাজে লেখা নয়" সম্ভব করে। */
async function wlv1CloudStampMs(table,id){
  try{
    if(!id) return -1;
    let ok=await initCloudClientOnly(); if(!ok||!sb) return -2;   // cloud অমিল → BLOCK
    let r=await sb.from(table).select('id,updatedAt').eq('id',id).limit(1);
    if(r&&r.error) return -2;                                     // পড়া ব্যর্থ → BLOCK
    if(!Array.isArray(r.data)||!r.data.length) return -1;         // সত্যিই row নেই
    return rowStamp(r.data[0]);
  }catch(_e){ return -2; }                                        // যেকোনো ত্রুটি → BLOCK
}
window["wlv1CloudStampMs"]=wlv1CloudStampMs;

async function wlv1VerifiedTrashEntry(id){
 try{
  if(!isMaster()||!id)return {ok:false,row:null};
  let ok=await initCloudClientOnly(); if(!ok||!sb)return {ok:false,row:null};
  let r=await sb.from('trash').select('*').eq('id',id).limit(1);
  if(r&&r.error)return {ok:false,row:null};
  let a=normalizeCloudRows((r&&Array.isArray(r.data))?r.data:[]);
  return {ok:true,row:(a[0]||null)};
 }catch(e){return {ok:false,row:null}}
}
window["wlv1VerifiedTrashEntry"]=wlv1VerifiedTrashEntry;

async function wlv1RestoreTrash(id, quiet){
  /* 🔴 V511: `quiet` শুধু একসাথে অনেকগুলো Restore করার সময় true — তখন
     প্রতিটার পরে আলাদা toast ও আলাদা `trashBin(true)` (মানে ক্লাউড থেকে
     পুরো Trash আবার নামানো) হয় না। শেষে একবারই হয়।
     ⛔ ফেরানোর আসল নিয়ম এক অক্ষরও বদলায়নি। */
  try{
    let tr=load('trash');
    let vr=await wlv1VerifiedTrashEntry(id);
    if(!vr.ok){ if(!quiet)toast('Could not verify cloud — restore stopped. Try again.'); return false; }
    let x=vr.row;
    if(!x){ save('trash',tr.filter(a=>a.id!==id),{skipCloud:true,skipBackup:true}); if(!quiet)toast('Trash entry is no longer in cloud'); return false; }
    /* Use the just-verified cloud snapshot, never a possibly stale local copy. */
    let rec=x.record||{}, rid=rec.id||'';
    /* 🔒 V223 (§C1): পুরোনো snapshot বসানোর আগে cloud-এর updatedAt **নিশ্চিতভাবে** মেলানো:
         · cloud পড়া ব্যর্থ (-2) → নতুনত্ব নিশ্চিত করা যায়নি → **restore বন্ধ**, সহজ Error;
           পুরোনো data কখনো আন্দাজে লেখা হয় না।
         · cloud-এ row আছে ও নবীন → keep newer (চাপা দেওয়া হয় না)।
         · তুলনা অসম্ভব (কোনো পাশে stamp নেই) → **restore বন্ধ** (আন্দাজে নয়)।
         · cloud-এ row নেই (-1) বা incoming ≥ cloud → নিরাপদে restore (নিচে)। */
    let incMs=rowStamp(rec);
    let cloudMs=await wlv1CloudStampMs(x.table,rid);
    if(cloudMs===-2){
      if(!quiet)toast('Could not verify cloud — restore stopped. Try again.');
      return false;
    }
    if(cloudMs>=0){
      if(incMs<=0 || cloudMs===0){
        if(!quiet)toast('Could not verify record time — restore stopped. Try again.');
        return false;
      }
      if(cloudMs>incMs){
        if(rid) await wlv1UnmarkDeletedCloud(x.table,rid);
        let goneN=await wlv1CloudDeleteRow('trash',x.id);
        if(goneN) save('trash',tr.filter(a=>a.id!==id),{skipCloud:true,skipBackup:true});
        if(!quiet){ toast('Restored — kept newer cloud copy'); trashBin(true); }
        return true;
      }
    }
    /* 🔴🔴 V510 (২১.০৮.২০২৬, TK-রিপোর্ট — লাইভ ডেটাবেস দেখে ধরা):
       **ক্রম উল্টো ছিল।** ডেটাবেসে `tk_block_deleted_return` নামে একটা ট্রিগার
       আছে — `deleted_records`-এ "মুছে ফেলা" চিহ্নটা থাকলে সে ঐ সারিটা
       **চুপচাপ বসতেই দেয় না** (`RETURN NULL`, কোনো ভুল দেখায় না)।
       আগে চিহ্ন তোলা হত **বসানোর পরে** — তাই "Restored" লেখা উঠত, অথচ
       ক্লাউডে কিছুই ফিরত না।
       ⇒ এখন **আগে চিহ্ন তোলা, তারপর বসানো** — অ্যান্ড্রয়েডে
         (`TrashRepository.restore()`) ঠিক এই ক্রমই আগে থেকে আছে। */
    /* ১. আগে "মুছে ফেলা" চিহ্নটা তুলে দেওয়া */
    if(rid) await wlv1UnmarkDeletedCloud(x.table,rid);
    /* ২. তারপর রেকর্ডটা ক্লাউডে ফেরানো */
    add(x.table,rec);
    let back=await directCloudUpsertRow(x.table,rec);
    if(!back){ if(!quiet)toast('Could not restore in cloud — try again'); return false; }
    /* ৩. সঙ্গে লুকিয়ে যাওয়া ফলো-আপ সারিগুলোও খুলে দেওয়া — অ্যান্ড্রয়েডের
          `TrashRepository.restore()`-এর হুবহু একই কাজ। ⛔ ওয়েবে এটা **ছিলই না**,
          তাই ওয়েব থেকে Restore করলে রোগী ফিরত কিন্তু তাঁর ফলো-আপ কার্ড চিরকাল
          লুকানো থাকত। */
    try{ await wlv1RestoreCascadedFollowups(x); }catch(e){}
    /* ৪. সবশেষে Trash সারিটা — ক্লাউডে ব্যর্থ হলে এখানেও রাখা হয়, যাতে
          আবার চেষ্টা করা যায় (রেকর্ড ততক্ষণে ফিরে এসেছে) */
    let gone=await wlv1CloudDeleteRow('trash',x.id);
    if(gone) save('trash',tr.filter(a=>a.id!==id),{skipCloud:true,skipBackup:true});
    if(!quiet){ toast(gone?'Restored':'Restored — Trash row will clear later'); trashBin(true); }
    return true;
  }catch(e){ if(!quiet)toast('Could not restore — try again'); return false; }
}
window["wlv1RestoreTrash"]=wlv1RestoreTrash;
window["restoreTrash"]=wlv1RestoreTrash;

/* ── Trash থেকে চিরতরে মোছা ─────────────────────────────────────────
   পুরনো `wlv1TrashDeleteForever()` ক্লাউডের ফল **দেখত না** — লাইন কেটে
   গেলেও "মুছে ফেলা হয়েছে" দেখাত, অথচ সারিটা ক্লাউডে রয়ে যেত ও পরে
   আবার ফিরে আসত।                                                     */
async function wlv1TrashDeleteForeverSafe(id, quiet){
  /* 🔴 V511: `quiet` শুধু **একসাথে অনেকগুলো** মোছার সময় true হয় — তখন
     প্রতিটার জন্য আলাদা "Sure?" ও আলাদা re-render হয় না (একবারই জিজ্ঞাসা
     হয়েছে, আর শেষে একবারই তালিকা নতুন করে আসে)। ⛔ আসল মোছার নিয়ম,
     ক্লাউড-যাচাই, ব্যর্থ হলে কিছু না মোছা — সব এক অক্ষরও বদলায়নি।
     ⛔ সফল/ব্যর্থ ফেরত দেওয়া হয় (true/false) যাতে গোনা যায়। */
  try{
    if(!isMaster()){ if(!quiet)toast('Only Master Admin'); return false; }
    let tr=load('trash');
    let vr=await wlv1VerifiedTrashEntry(id);
    if(!vr.ok){ if(!quiet)toast('Could not verify cloud — delete stopped. Try again.'); return false; }
    let x=vr.row;
    if(!x){ save('trash',tr.filter(a=>a.id!==id),{skipCloud:true,skipBackup:true}); if(!quiet)toast('Trash entry is already gone from cloud'); return true; }
    if(!quiet && !confirm('Delete forever? This cannot be undone.')) return false;
    let gone=await wlv1CloudDeleteRow('trash',x.id);
    if(!gone){ if(!quiet)toast('Could not delete in cloud — nothing was deleted'); return false; }
    save('trash',tr.filter(a=>a.id!==id),{skipCloud:true,skipBackup:true});
    if(!quiet){ toast('Deleted forever'); trashBin(true); }
    return true;
  }catch(e){ if(!quiet)toast('Could not delete — try again'); return false; }
}
window["wlv1TrashDeleteForeverSafe"]=wlv1TrashDeleteForeverSafe;
window["wlv1TrashDeleteForever"]=wlv1TrashDeleteForeverSafe;

/* Trash সারির আইডি — ফোনের `TrashHelper.trashIdFor()`-এর **হুবহু একই নিয়ম**
   (খাতার সারি B165)। একই রেকর্ডের জন্য সবসময় একই আইডি, তাই বারবার চেষ্টা
   করলেও Trash-এ একটাই এন্ট্রি থাকে — আর ফোন ও কম্পিউটার দুই জায়গা থেকে
   মুছলেও দুটো আলাদা এন্ট্রি তৈরি হয় না। */
function wlv1JavaHash(s){
  let h=0;
  for(let i=0;i<s.length;i++){ h=(Math.imul(31,h)+s.charCodeAt(i))|0 }
  return h;
}
function wlv1TrashIdFor(table,recordId){
  let raw=String(table||'').trim()+'_'+String(recordId||'').trim();
  let out='';
  for(let i=0;i<raw.length;i++){
    let c=raw[i];
    let keep=(c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c==='_'||c==='-';
    out+=keep?c:'_';
  }
  if(out.length>80) out=out.slice(out.length-80);
  return 'trash_'+out+'_'+(wlv1JavaHash(raw)>>>0).toString(16);
}
window["wlv1TrashIdFor"]=wlv1TrashIdFor;

/* 🔒 B581 (TK গ্লোবাল রুল ১৬, ০৮.০৮.২০২৬): নাম/নম্বরে লং-প্রেস → কপি।
   এক জায়গা থেকে সব লিস্টে (.wlv1NameLink=নাম, .wlv1CallLink=নম্বর)। ছোট-ট্যাপ
   আগের মতোই কাজ করে (History খোলে / কল করে); শুধু ~৫০০ms চেপে ধরলে কপি হয়।
   ⛔ কোনো ডেটা/লজিক ছোঁয়া হয়নি — শুধু একটা বাড়তি জেসচার। */
(function wlv1LongPressCopy(){
  var timer=null,longFired=false;
  function doCopy(text,label){
    try{ if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text);} }catch(e){}
    try{ if(typeof toast==='function') toast((label||'Copied')+' copied'); }catch(e){}
  }
  function start(e){
    var el=(e.target&&e.target.closest)?e.target.closest('.wlv1NameLink, .wlv1CallLink'):null;
    if(!el) return;
    longFired=false;
    timer=setTimeout(function(){
      longFired=true;
      var isCall=el.classList.contains('wlv1CallLink');
      var txt=((el.textContent||'')+'').trim();
      doCopy(isCall? txt.replace(/[^0-9+]/g,'') : txt, isCall?'Number':'Name');
    },500);
  }
  function cancel(){ if(timer){clearTimeout(timer);timer=null;} }
  document.addEventListener('touchstart',start,{passive:true});
  document.addEventListener('touchend',cancel);
  document.addEventListener('touchmove',cancel);
  document.addEventListener('mousedown',start);
  document.addEventListener('mouseup',cancel);
  document.addEventListener('click',function(e){
    if(longFired){ var el=(e.target&&e.target.closest)?e.target.closest('.wlv1NameLink, .wlv1CallLink'):null; if(el){ e.stopPropagation(); if(e.preventDefault)e.preventDefault(); longFired=false; } }
  },true);
})();

/* 🟢 B627 (11.08.2026, TK-নির্দেশ): ওয়েবে অটো লগ-আউট — নিষ্ক্রিয় থাকলে সেশন বন্ধ।
   কেন: খোলা-রাখা ওয়েব চুপচাপ ব্যাকগ্রাউন্ডে ডেটা টেনে Supabase egress খরচ করে;
   কেউ কিছুক্ষণ কাজ না করলে নিজে থেকে লগ-আউট হলে সেটা বন্ধ হয় (+ ছোট নিরাপত্তা-লাভ)।
   ⛔ শুধু নিষ্ক্রিয়তায় — সক্রিয় কাজ (ক্লিক/টাইপ/স্ক্রল) চললে টাইমার রিসেট, লগ-আউট নয়।
   ⛔ লগ-আউটের আগে বাকি কাজ flush করার চেষ্টা; ব্যর্থ হলেও pending localStorage-এ
      নিরাপদ থাকে (logout শুধু rk_session মোছে, pending নয়) — কিছু হারায় না। */
(function(){
  try{
    var IDLE_MS = 15*60*1000;              // ১৫ মিনিট নিষ্ক্রিয় হলে
    var last = Date.now(), firing = false;
    function bump(){ last = Date.now(); }
    ['pointerdown','keydown','touchstart','scroll','click'].forEach(function(ev){
      try{ window.addEventListener(ev, bump, {passive:true}); }catch(_e){}
    });
    try{ document.addEventListener('visibilitychange', function(){ if(!document.hidden) bump(); }); }catch(_e){}
    setInterval(function(){
      try{
        if(typeof user==='undefined' || !user){ last = Date.now(); return; } // লগইন না থাকলে কিছু নয়
        if(firing) return;
        if(Date.now() - last < IDLE_MS) return;
        firing = true;
        var done = function(){
          try{ logout(); }catch(_e){}
          try{ toast('নিষ্ক্রিয় থাকায় নিরাপত্তার জন্য লগ-আউট হয়েছে। আবার লগইন করুন।'); }catch(_e){}
          firing = false; last = Date.now();
        };
        try{
          if(typeof flushPendingCloud==='function'){
            /* Idle logout is not a reconciliation event: send only work that is
               actually pending. Full safety reconciliation remains available via
               Sync Now and the scheduled weekly safety pass. */
            Promise.resolve(flushPendingCloud('pending')).then(done, done);
          } else { done(); }
        }catch(_e){ done(); }
      }catch(_e){ firing = false; }
    }, 60*1000);
  }catch(_e){}
})();

/* ██████████████████████████████████████████████████████████████████████████
   V386 · DIALER — অ্যান্ড্রয়েডের `native/DialerActivity.kt` + `activity_dialer.xml`
   ██████████████████████████████████████████████████████████████████████████
   ⛔ সম্পূর্ণ **নতুন ও আলাদা** কোড — উপরের কোনো ফাংশনে হাত পড়েনি।
   ⛔ ডেটাবেসে নতুন টেবিল/কলাম লাগে না; কোনো নতুন SQL চালাতে হবে না।
      Contacts আসে ইতিমধ্যেই লোড-করা `followups` থেকে (নতুন কোনো অনুরোধ নয়)।

   🔴 সততার সঙ্গে — যা ব্রাউজারে **সম্ভব নয়**:
      অ্যান্ড্রয়েডের "All" ও "Missed" ট্যাব **ফোনের নিজের কল-লগ** পড়ে
      (`BranchSimHelper.kt:188-200` → `CallLog.Calls` + `READ_CALL_LOG` অনুমতি)।
      ওই কলগুলো সার্ভারে **কোথাও জমা থাকে না**। ব্রাউজারের এমন কোনো ক্ষমতা নেই,
      তাই ওয়েবে ওই দুই ট্যাবে তথ্য দেখানো যাবে না — আন্দাজে বানানো হয়নি,
      পরিষ্কার করে লিখে দেওয়া আছে। ট্যাব তিনটে অ্যান্ড্রয়েডের মতোই থাকল।
      "Contacts" ট্যাব ও কি-প্যাড — দুটোই সম্পূর্ণ কাজ করে।
   ██████████████████████████████████████████████████████████████████████████ */
var wlv1DlTab='contacts', wlv1DlQuery='', wlv1DlKeypad='';

/* Contacts — `DialerRepository.fetchContacts()`-এর হুবহু নিয়ম:
   Inquiry+Patient+Treatment মিলিয়ে শেষ-১০-অঙ্কে এক করা,
   অগ্রাধিকার Treatment > Patient > Inquiry, নামের (বড় হাতের) ক্রমে সাজানো।
   ব্রাঞ্চ-ছাঁকনি `scoped()` আগের মতোই করে (master = সব, বাকিরা নিজের ব্রাঞ্চ)। */
function wlv1DlContacts(){
  var rows=[]; try{ rows=mergeFollow(scoped(load('followups')))||[] }catch(e){ rows=[] }
  var rank={Treatment:3,Patient:2,Inquiry:1};
  var by={};
  rows.forEach(function(r){
    var d=String(r.mobile||'').replace(/\D/g,'').slice(-10);
    if(d.length!==10) return;
    var cur=by[d];
    if(!cur || (rank[r.stage]||0) > (rank[cur.stage]||0)) by[d]=r;
  });
  var out=Object.keys(by).map(function(d){ return by[d] });
  out.sort(function(a,b){ return String(a.name||'').toUpperCase().localeCompare(String(b.name||'').toUpperCase()) });
  return out;
}
window["wlv1DlContacts"]=wlv1DlContacts;

/* ট্যাগের লেখা — DialerActivity.kt:591-650 (STAGE · BRANCH · DISEASE · ADDRESS) */
function wlv1DlTags(r){
  var st=r.stage==='Treatment'?'PATIENT':(r.stage==='Patient'?'VISIT':'ENQUIRY');
  var t=[st];
  if(String(r.branch||'').trim()) t.push(String(r.branch).toUpperCase());
  if(String(r.disease||'').trim()) t.push(String(r.disease).toUpperCase());
  var ad=''; try{ ad=wlv1AddrTagForCard(r.mobile,r.address,r.stage)||'' }catch(e){ ad=String(r.address||'') }
  if(String(ad).trim()) t.push(String(ad).toUpperCase());
  return t;
}

function wlv1DlRow(r){
  var d=String(r.mobile||'').replace(/\D/g,'').slice(-10);
  var nm=String(r.name||'').trim()||'Name Not Available';
  var tags=wlv1DlTags(r).map(function(t){ return '<span class="dlTag">'+esc(t)+'</span>' }).join('');
  return '<div class="dlRow">'
   +'<div class="dlInfo"><div class="dlName">'+esc(nm)+'</div><div class="dlMob">'+esc(d)+'</div>'
   +(tags?'<div class="dlTags">'+tags+'</div>':'')+'</div>'
   +'<button class="dlCall" aria-label="Call" onclick="contact(\''+esc(d)+'\',\'call\');event.stopPropagation();">📞</button>'
   +'</div>';
}

function wlv1DlListHtml(){
  if(wlv1DlTab!=='contacts'){
    /* অ্যান্ড্রয়েডের খালি-অবস্থার হুবহু ধাঁচ (13sp #6B7280, padding 30dp) */
    return '<div class="dlEmpty">'
      +(wlv1DlTab==='missed'?'Missed calls':'Today’s calls')
      +' — এই তালিকা ফোনের নিজস্ব কল-লগ থেকে আসে।<br><br>'
      +'ব্রাউজার ফোনের কল-লগ পড়তে পারে না, আর এই কলগুলো সার্ভারেও জমা থাকে না — তাই এখানে দেখানো সম্ভব নয়।<br>'
      +'এই দুটো লাগলে <b>অ্যান্ড্রয়েড অ্যাপ</b>-এ দেখুন।<br><br>'
      +'<b>Contacts</b> ট্যাব ও কি-প্যাড এখানে পুরোপুরি কাজ করে।</div>';
  }
  var q=String(wlv1DlQuery||'').trim().toUpperCase();
  var list=wlv1DlContacts().filter(function(r){
    if(!q) return true;
    var d=String(r.mobile||'').replace(/\D/g,'');
    return String(r.name||'').toUpperCase().indexOf(q)>=0 || d.indexOf(q.replace(/\D/g,''))>=0;
  });
  if(!list.length) return '<div class="dlEmpty">No contacts found.</div>';
  return list.map(wlv1DlRow).join('');
}

function wlv1DlPaint(){
  var el=$id('dlList'); if(el) el.innerHTML=wlv1DlListHtml();
  ['all','missed','contacts'].forEach(function(t){
    var b=$id('dlTab_'+t); if(b) b.className='dlTab'+(wlv1DlTab===t?' on':'');
  });
  var sb=$id('dlSearchWrap'); if(sb) sb.style.display=(wlv1DlTab==='contacts')?'':'none';
}
function wlv1DlSetTab(t){ wlv1DlTab=t; wlv1DlPaint() }
function wlv1DlSearch(v){ wlv1DlQuery=v; wlv1DlPaint() }
window["wlv1DlSetTab"]=wlv1DlSetTab; window["wlv1DlSearch"]=wlv1DlSearch;

/* কি-প্যাড — activity_dialer.xml:184-306 (গাঢ় শিট #1C1C1E, ৩ কলাম) */
function wlv1DlKeyShow(v){ var s=$id('dlSheet'),f=$id('dlFab'); if(s)s.style.display=v?'':'none'; if(f)f.style.display=v?'none':''; }
function wlv1DlKey(ch){ if(wlv1DlKeypad.length<15){ wlv1DlKeypad+=ch; } var i=$id('dlInput'); if(i)i.textContent=wlv1DlKeypad; }
function wlv1DlBack(){ wlv1DlKeypad=wlv1DlKeypad.slice(0,-1); var i=$id('dlInput'); if(i)i.textContent=wlv1DlKeypad; }
function wlv1DlPaste(){
  try{
    if(navigator.clipboard && navigator.clipboard.readText){
      navigator.clipboard.readText().then(function(t){
        wlv1DlKeypad=String(t||'').replace(/\D/g,'').slice(-10);
        var i=$id('dlInput'); if(i)i.textContent=wlv1DlKeypad;
      }).catch(function(){ toast('Paste not allowed by browser') });
    } else { toast('Paste not supported here') }
  }catch(e){ toast('Paste not supported here') }
}
/* DialerActivity.kt:713-724 — ঠিক ১০ অঙ্ক না হলে কল যায় না */
function wlv1DlCall(){
  var d=String(wlv1DlKeypad||'').replace(/\D/g,'').slice(-10);
  if(d.length!==10) return toast('Enter a valid 10-digit number');
  wlv1DlKeyShow(false);
  contact(d,'call');
}
window["wlv1DlKeyShow"]=wlv1DlKeyShow; window["wlv1DlKey"]=wlv1DlKey;
window["wlv1DlBack"]=wlv1DlBack; window["wlv1DlPaste"]=wlv1DlPaste; window["wlv1DlCall"]=wlv1DlCall;

function dialerPage(){
  wlv1DlTab='contacts'; wlv1DlQuery=''; wlv1DlKeypad='';
  var tabs='<div class="dlTabWrap"><div class="dlTabPill">'
    +'<button id="dlTab_all" class="dlTab" onclick="wlv1DlSetTab(\'all\')">All</button>'
    +'<button id="dlTab_missed" class="dlTab" onclick="wlv1DlSetTab(\'missed\')">Missed</button>'
    +'<button id="dlTab_contacts" class="dlTab on" onclick="wlv1DlSetTab(\'contacts\')">Contacts</button>'
    +'</div></div>';
  var search='<div id="dlSearchWrap" class="dlSearchWrap"><input id="dlSearch" class="input dlSearch" placeholder="🔍 Search name or number" autocomplete="off" oninput="wlv1DlSearch(this.value)"></div>';
  var keys=['1','2','3','4','5','6','7','8','9','*','0','#']
    .map(function(k){ return '<button class="dlKey" onclick="wlv1DlKey(\''+k+'\')">'+k+'</button>' }).join('');
  var sheet='<div id="dlSheet" class="dlSheet" style="display:none">'
    +'<div class="dlHandleArea" onclick="wlv1DlKeyShow(false)"><div class="dlHandle"></div></div>'
    +'<div class="dlDisp"><button class="dlPaste" onclick="wlv1DlPaste()">Paste</button>'
    +'<div id="dlInput" class="dlInput"></div>'
    +'<button class="dlBs" onclick="wlv1DlBack()">⌫</button></div>'
    +'<div class="dlGrid">'+keys+'</div>'
    +'<button class="dlGo" onclick="wlv1DlCall()">📞</button></div>';
  var fab='<button id="dlFab" class="dlFab" aria-label="Keypad" onclick="wlv1DlKeyShow(true)">⌨️</button>';
  page('Dialer', '<div class="dlWrap">'+tabs+search+'<div id="dlList" class="dlList"></div></div>'+fab+sheet, true);
  wlv1DlPaint();
}
window["dialerPage"]=dialerPage;
